/**
 * TypeScript Utility Types Library
 * 
 * A collection of commonly used utility types for TypeScript projects.
 * Copy and use as needed in your projects.
 */

// =============================================================================
// BRANDED TYPES
// =============================================================================

/**
 * Create nominal/branded types to prevent primitive obsession.
 * 
 * @example
 * type UserId = Brand<string, 'UserId'>
 * type OrderId = Brand<string, 'OrderId'>
 */
export type Brand<K, T> = K & { readonly __brand: T }

// Branded type constructors
export type UserId = Brand<string, 'UserId'>
export type Email = Brand<string, 'Email'>
export type UUID = Brand<string, 'UUID'>
export type Timestamp = Brand<number, 'Timestamp'>
export type PositiveNumber = Brand<number, 'PositiveNumber'>

// =============================================================================
// RESULT TYPE (Error Handling)
// =============================================================================

/**
 * Type-safe error handling without exceptions.
 */
export type Result<T, E = Error> =
    | { success: true; data: T }
    | { success: false; error: E }

export const ok = <T>(data: T): Result<T, never> => ({
    success: true,
    data
})

export const err = <E>(error: E): Result<never, E> => ({
    success: false,
    error
})

// =============================================================================
// OPTION TYPE (Nullable Handling)  
// =============================================================================

/**
 * Explicit optional value handling.
 */
export type Option<T> = Some<T> | None

export type Some<T> = { type: 'some'; value: T }
export type None = { type: 'none' }

export const some = <T>(value: T): Some<T> => ({ type: 'some', value })
export const none: None = { type: 'none' }

// =============================================================================
// DEEP UTILITIES
// =============================================================================

/**
 * Make all properties deeply readonly.
 */
export type DeepReadonly<T> = T extends (...args: any[]) => any
    ? T
    : T extends object
    ? { readonly [K in keyof T]: DeepReadonly<T[K]> }
    : T

/**
 * Make all properties deeply optional.
 */
export type DeepPartial<T> = T extends object
    ? { [K in keyof T]?: DeepPartial<T[K]> }
    : T

/**
 * Make all properties deeply required.
 */
export type DeepRequired<T> = T extends object
    ? { [K in keyof T]-?: DeepRequired<T[K]> }
    : T

/**
 * Make all properties deeply mutable (remove readonly).
 */
export type DeepMutable<T> = T extends object
    ? { -readonly [K in keyof T]: DeepMutable<T[K]> }
    : T

// =============================================================================
// OBJECT UTILITIES
// =============================================================================

/**
 * Get keys of object where value matches type.
 */
export type KeysOfType<T, V> = {
    [K in keyof T]: T[K] extends V ? K : never
}[keyof T]

/**
 * Pick properties by value type.
 */
export type PickByType<T, V> = Pick<T, KeysOfType<T, V>>

/**
 * Omit properties by value type.
 */
export type OmitByType<T, V> = Omit<T, KeysOfType<T, V>>

/**
 * Make specific keys optional.
 */
export type PartialBy<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>

/**
 * Make specific keys required.
 */
export type RequiredBy<T, K extends keyof T> = Omit<T, K> & Required<Pick<T, K>>

/**
 * Make specific keys readonly.
 */
export type ReadonlyBy<T, K extends keyof T> = Omit<T, K> & Readonly<Pick<T, K>>

/**
 * Merge two types (second overrides first).
 */
export type Merge<T, U> = Omit<T, keyof U> & U

// =============================================================================
// ARRAY UTILITIES
// =============================================================================

/**
 * Get element type from array.
 */
export type ElementOf<T> = T extends (infer E)[] ? E : never

/**
 * Tuple of specific length.
 */
export type Tuple<T, N extends number> = N extends N
    ? number extends N
    ? T[]
    : _TupleOf<T, N, []>
    : never

type _TupleOf<T, N extends number, R extends unknown[]> = R['length'] extends N
    ? R
    : _TupleOf<T, N, [T, ...R]>

/**
 * Non-empty array.
 */
export type NonEmptyArray<T> = [T, ...T[]]

/**
 * At least N elements.
 */
export type AtLeast<T, N extends number> = [...Tuple<T, N>, ...T[]]

// =============================================================================
// FUNCTION UTILITIES
// =============================================================================

/**
 * Get function arguments as tuple.
 */
export type Arguments<T> = T extends (...args: infer A) => any ? A : never

/**
 * Get first argument of function.
 */
export type FirstArgument<T> = T extends (first: infer F, ...args: any[]) => any
    ? F
    : never

/**
 * Async version of function.
 */
export type AsyncFunction<T extends (...args: any[]) => any> = (
    ...args: Parameters<T>
) => Promise<Awaited<ReturnType<T>>>

/**
 * Promisify return type.
 */
export type Promisify<T> = T extends (...args: infer A) => infer R
    ? (...args: A) => Promise<Awaited<R>>
    : never

// =============================================================================
// STRING UTILITIES
// =============================================================================

/**
 * Split string by delimiter.
 */
export type Split<S extends string, D extends string> =
    S extends `${infer T}${D}${infer U}`
    ? [T, ...Split<U, D>]
    : [S]

/**
 * Join tuple to string.
 */
export type Join<T extends string[], D extends string> =
    T extends []
    ? ''
    : T extends [infer F extends string]
    ? F
    : T extends [infer F extends string, ...infer R extends string[]]
    ? `${F}${D}${Join<R, D>}`
    : never

/**
 * Path to nested object.
 */
export type PathOf<T, K extends keyof T = keyof T> = K extends string
    ? T[K] extends object
    ? K | `${K}.${PathOf<T[K]>}`
    : K
    : never

// =============================================================================
// UNION UTILITIES
// =============================================================================

/**
 * Last element of union.
 */
export type UnionLast<T> = UnionToIntersection<
    T extends any ? () => T : never
> extends () => infer R
    ? R
    : never

/**
 * Union to intersection.
 */
export type UnionToIntersection<U> = (
    U extends any ? (k: U) => void : never
) extends (k: infer I) => void
    ? I
    : never

/**
 * Union to tuple.
 */
export type UnionToTuple<T, L = UnionLast<T>> = [T] extends [never]
    ? []
    : [...UnionToTuple<Exclude<T, L>>, L]

// =============================================================================
// VALIDATION UTILITIES
// =============================================================================

/**
 * Assert type at compile time.
 */
export type AssertEqual<T, U> =
    (<V>() => V extends T ? 1 : 2) extends (<V>() => V extends U ? 1 : 2)
    ? true
    : false

/**
 * Ensure type is not never.
 */
export type IsNever<T> = [T] extends [never] ? true : false

/**
 * Ensure type is any.
 */
export type IsAny<T> = 0 extends 1 & T ? true : false

/**
 * Ensure type is unknown.
 */
export type IsUnknown<T> = IsAny<T> extends true
    ? false
    : unknown extends T
    ? true
    : false

// =============================================================================
// JSON UTILITIES
// =============================================================================

/**
 * JSON-safe types.
 */
export type JsonPrimitive = string | number | boolean | null
export type JsonArray = JsonValue[]
export type JsonObject = { [key: string]: JsonValue }
export type JsonValue = JsonPrimitive | JsonArray | JsonObject

/**
 * Make type JSON-serializable.
 */
export type Jsonify<T> = T extends JsonPrimitive
    ? T
    : T extends undefined | ((...args: any[]) => any) | symbol
    ? never
    : T extends { toJSON(): infer R }
    ? R
    : T extends object
    ? { [K in keyof T]: Jsonify<T[K]> }
    : never

// =============================================================================
// EXHAUSTIVE CHECK
// =============================================================================

/**
 * Ensure all cases are handled in switch/if.
 */
export function assertNever(value: never, message?: string): never {
    throw new Error(message ?? `Unexpected value: ${value}`)
}

/**
 * Exhaustive check without throwing.
 */
export function exhaustiveCheck(_value: never): void {
    // This function should never be called
}

"use client"

import { useState, useEffect } from "react"
import { useRouter } from "next/navigation"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select"
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "@/components/ui/dialog"
import { Label } from "@/components/ui/label"
import { Textarea } from "@/components/ui/textarea"
import { Loader2, User, Lock, Eye, EyeOff, AlertCircle, CheckCircle } from "lucide-react"
import { useAuth } from "@/components/providers/auth-provider"

export default function LoginPage() {
    const router = useRouter()
    const { signIn, user, isLoading: authLoading } = useAuth()
    const [username, setUsername] = useState("")
    const [password, setPassword] = useState("")
    const [role, setRole] = useState("analyst")
    const [isLoading, setIsLoading] = useState(false)
    const [showPassword, setShowPassword] = useState(false)
    const [error, setError] = useState<string | null>(null)

    // Redirect to dashboard if already logged in
    useEffect(() => {
        if (!authLoading && user) {
            router.replace("/")
        }
    }, [user, authLoading, router])

    // Contact Support States
    const [isContactOpen, setIsContactOpen] = useState(false)
    const [isSubmitting, setIsSubmitting] = useState(false)
    const [submitSuccess, setSubmitSuccess] = useState(false)
    const [contactForm, setContactForm] = useState({
        name: "",
        company: "",
        contact: "",
        issue: "",
    })

    const handleLogin = async (e: React.FormEvent) => {
        e.preventDefault()
        setIsLoading(true)
        setError(null)

        const result = await signIn(username, password, role)

        if (result.success) {
            router.push("/")
        } else {
            setError(result.error || "Login gagal")
            setIsLoading(false)
        }
    }

    const handleContactSubmit = async () => {
        if (!contactForm.name || !contactForm.company || !contactForm.contact || !contactForm.issue) {
            return
        }
        setIsSubmitting(true)
        try {
            const response = await fetch("/api/support", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify(contactForm),
            })
            if (response.ok) {
                setSubmitSuccess(true)
                setContactForm({ name: "", company: "", contact: "", issue: "" })
                setTimeout(() => {
                    setIsContactOpen(false)
                    setSubmitSuccess(false)
                }, 2000)
            }
        } catch (error) {
            console.error("Contact support error:", error)
        } finally {
            setIsSubmitting(false)
        }
    }

    return (
        <div className="min-h-screen flex flex-col bg-[#f5f7f8] dark:bg-[#101922]">
            {/* Header */}
            <header className="flex items-center justify-between px-8 py-4 w-full absolute top-0 z-10">
                <div className="flex items-center gap-3">
                    <img src="/logo.png" alt="LabFlow" className="h-8 w-8 object-contain" />
                    <h2 className="text-xl font-bold leading-tight tracking-tight text-foreground">
                        LabFlow
                    </h2>
                </div>
                <Dialog open={isContactOpen} onOpenChange={setIsContactOpen}>
                    <DialogTrigger asChild>
                        <Button variant="outline" className="h-9 px-4">
                            Contact Support
                        </Button>
                    </DialogTrigger>
                    <DialogContent className="sm:max-w-[425px]">
                        <DialogHeader>
                            <DialogTitle>Hubungi Support</DialogTitle>
                            <DialogDescription>
                                Isi formulir di bawah untuk menghubungi tim support kami.
                            </DialogDescription>
                        </DialogHeader>
                        {submitSuccess ? (
                            <div className="py-8 text-center">
                                <CheckCircle className="h-12 w-12 text-green-500 mx-auto mb-4" />
                                <p className="font-medium text-green-600">Permintaan berhasil dikirim!</p>
                                <p className="text-sm text-muted-foreground mt-2">Tim kami akan menghubungi Anda segera.</p>
                            </div>
                        ) : (
                            <>
                                <div className="grid gap-4 py-4">
                                    <div className="grid gap-2">
                                        <Label htmlFor="name">Nama *</Label>
                                        <Input
                                            id="name"
                                            placeholder="Masukkan nama Anda"
                                            value={contactForm.name}
                                            onChange={(e) => setContactForm(prev => ({ ...prev, name: e.target.value }))}
                                        />
                                    </div>
                                    <div className="grid gap-2">
                                        <Label htmlFor="company">Perusahaan *</Label>
                                        <Input
                                            id="company"
                                            placeholder="Nama perusahaan Anda"
                                            value={contactForm.company}
                                            onChange={(e) => setContactForm(prev => ({ ...prev, company: e.target.value }))}
                                        />
                                    </div>
                                    <div className="grid gap-2">
                                        <Label htmlFor="contact">Kontak/Email *</Label>
                                        <Input
                                            id="contact"
                                            placeholder="Email atau nomor telepon"
                                            value={contactForm.contact}
                                            onChange={(e) => setContactForm(prev => ({ ...prev, contact: e.target.value }))}
                                        />
                                    </div>
                                    <div className="grid gap-2">
                                        <Label htmlFor="issue">Masalah *</Label>
                                        <Textarea
                                            id="issue"
                                            placeholder="Jelaskan masalah atau pertanyaan Anda"
                                            value={contactForm.issue}
                                            onChange={(e) => setContactForm(prev => ({ ...prev, issue: e.target.value }))}
                                            rows={4}
                                        />
                                    </div>
                                </div>
                                <DialogFooter>
                                    <Button
                                        type="submit"
                                        onClick={handleContactSubmit}
                                        disabled={isSubmitting || !contactForm.name || !contactForm.company || !contactForm.contact || !contactForm.issue}
                                    >
                                        {isSubmitting ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : null}
                                        Kirim
                                    </Button>
                                </DialogFooter>
                            </>
                        )}
                    </DialogContent>
                </Dialog>
            </header>

            {/* Main Content */}
            <div className="flex-1 flex flex-col lg:flex-row h-full">
                {/* Left Side: Login Form */}
                <div className="w-full lg:w-[45%] xl:w-[40%] flex flex-col justify-center items-center p-8 lg:p-16 xl:p-24 relative z-0">
                    <div className="w-full max-w-[480px] flex flex-col gap-6">
                        {/* Mobile Logo */}
                        <div className="lg:hidden flex justify-center mb-6">
                            <img src="/logo.png" alt="LabFlow" className="h-16 w-16 object-contain" />
                        </div>

                        {/* Welcome Text */}
                        <div className="mb-4 text-center lg:text-left">
                            <h1 className="text-[32px] font-bold leading-tight tracking-tight mb-3">
                                Welcome Back
                            </h1>
                            <p className="text-muted-foreground text-base">
                                Systems for managing inventory and instruments for Labmania Indonesia
                            </p>
                        </div>

                        {/* Form */}
                        <form onSubmit={handleLogin} className="flex flex-col gap-5">
                            {/* Username */}
                            <div className="flex flex-col gap-2">
                                <label className="text-base font-medium">Username</label>
                                <div className="relative">
                                    <User className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-muted-foreground" />
                                    <Input
                                        type="text"
                                        placeholder="Enter your username"
                                        value={username}
                                        onChange={(e) => setUsername(e.target.value)}
                                        className="h-14 pl-12 pr-4 text-base"
                                        required
                                    />
                                </div>
                            </div>

                            {/* Role Selector */}
                            <div className="flex flex-col gap-2">
                                <label className="text-base font-medium">Login As</label>
                                <Select value={role} onValueChange={setRole}>
                                    <SelectTrigger className="h-14 pl-4 pr-4 text-base">
                                        <SelectValue placeholder="Select role" />
                                    </SelectTrigger>
                                    <SelectContent>
                                        <SelectItem value="analyst">Analyst</SelectItem>
                                        <SelectItem value="manager">Manager</SelectItem>
                                        <SelectItem value="admin">Admin</SelectItem>
                                    </SelectContent>
                                </Select>
                            </div>

                            {/* Password */}
                            <div className="flex flex-col gap-2">
                                <label className="text-base font-medium">Password</label>
                                <div className="relative">
                                    <Lock className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-muted-foreground" />
                                    <Input
                                        type={showPassword ? "text" : "password"}
                                        placeholder="Enter your password"
                                        value={password}
                                        onChange={(e) => setPassword(e.target.value)}
                                        className="h-14 pl-12 pr-12 text-base"
                                        required
                                    />
                                    <button
                                        type="button"
                                        onClick={() => setShowPassword(!showPassword)}
                                        className="absolute right-4 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-primary transition-colors"
                                    >
                                        {showPassword ? (
                                            <EyeOff className="h-5 w-5" />
                                        ) : (
                                            <Eye className="h-5 w-5" />
                                        )}
                                    </button>
                                </div>
                            </div>

                            {/* Error Message */}
                            {error && (
                                <div className="flex items-center gap-2 p-3 rounded-lg bg-destructive/10 text-destructive border border-destructive/20">
                                    <AlertCircle className="h-5 w-5 flex-shrink-0" />
                                    <span className="text-sm font-medium">{error}</span>
                                </div>
                            )}

                            {/* Submit Button */}
                            <Button
                                type="submit"
                                className="h-12 text-base font-bold mt-2 shadow-lg shadow-primary/20"
                                disabled={isLoading}
                            >
                                {isLoading ? (
                                    <>
                                        <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                                        Memproses...
                                    </>
                                ) : (
                                    "Sign In"
                                )}
                            </Button>
                        </form>

                        <p className="text-center text-muted-foreground text-sm mt-4">
                            Powered by LabFlow Indonesia
                        </p>
                    </div>
                </div>

                {/* Right Side: Hero Image */}
                <div className="hidden lg:flex w-[55%] xl:w-[60%] bg-white dark:bg-gray-900 relative overflow-hidden items-center justify-center p-4">
                    {/* Background Image Container */}
                    <div className="absolute inset-0 z-0">
                        <div
                            className="w-full h-full bg-cover bg-center"
                            style={{
                                backgroundImage: "url('https://images.unsplash.com/photo-1582719471384-894fbb16e074?ixlib=rb-4.0.3&auto=format&fit=crop&w=1920&q=80')"
                            }}
                        />
                        {/* Gradient Overlay */}
                        <div className="absolute inset-0 bg-gradient-to-br from-primary/80 to-[#101922]/90" />
                        {/* Pattern Overlay */}
                        <div className="absolute inset-0 opacity-10"
                            style={{
                                backgroundImage: "url(\"data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.4'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E\")"
                            }}
                        />
                    </div>

                    {/* Floating Card Content */}
                    <div className="relative z-10 max-w-md text-white p-8">
                        <h2 className="text-4xl font-bold mb-4 tracking-tight leading-snug">
                            Efficient Lab Management for Modern Science
                        </h2>
                        <p className="text-lg text-white/80 leading-relaxed font-light">
                            Streamline your inventory, track instruments, and optimize your laboratory workflow with LabFlow&apos;s comprehensive management suite.
                        </p>

                        {/* Stat items */}
                        <div className="grid grid-cols-2 gap-4 mt-10">
                            <div className="p-4 rounded-lg bg-white/10 backdrop-blur-sm border border-white/10">
                                <div className="text-3xl font-bold mb-1">99%</div>
                                <div className="text-sm text-white/70">Uptime Reliability</div>
                            </div>
                            <div className="p-4 rounded-lg bg-white/10 backdrop-blur-sm border border-white/10">
                                <div className="text-3xl font-bold mb-1">24/7</div>
                                <div className="text-sm text-white/70">Support Access</div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    )
}

"use client"

import { toast } from "sonner"

import { useState } from "react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select"
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from "@/components/ui/table"
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "@/components/ui/dialog"
import {
    AlertDialog,
    AlertDialogAction,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle,
} from "@/components/ui/alert-dialog"
import { Label } from "@/components/ui/label"
import { Textarea } from "@/components/ui/textarea"
import { Plus, Search, FileText, Pencil, Trash2, Download, Loader2, RefreshCw, Upload } from "lucide-react"
import { Badge } from "@/components/ui/badge"
import { useFetchPaginated, useFetch, useMutation } from "@/hooks/use-api"
import { Pagination } from "@/components/ui/pagination"

interface CalibrationLog {
    id: string
    instrumentId: string
    instrumentName: string
    assetType: string
    performedDate: string
    calibratorName: string | null
    calibratorPhone: string | null
    notes: string | null
    jobReportDocument: string | null
}

interface InstrumentOption {
    id: string
    name: string
    assetType: string
}

export default function CalibrationLogsPage() {
    const [typeFilter, setTypeFilter] = useState<string>("all")
    const [isAddDialogOpen, setIsAddDialogOpen] = useState(false)
    const [isEditDialogOpen, setIsEditDialogOpen] = useState(false)
    const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false)
    const [selectedLog, setSelectedLog] = useState<CalibrationLog | null>(null)

    // Form state for add
    const [formData, setFormData] = useState({
        instrumentId: "",
        performedDate: new Date().toISOString().split("T")[0],
        calibratorName: "",
        calibratorPhone: "",
        notes: "",
        jobReportDocument: "",
    })

    // Form state for edit
    const [editFormData, setEditFormData] = useState({
        performedDate: "",
        calibratorName: "",
        calibratorPhone: "",
        notes: "",
        jobReportDocument: "",
    })

    const [isUploading, setIsUploading] = useState(false)
    const [isEditUploading, setIsEditUploading] = useState(false)
    const [isEditLoading, setIsEditLoading] = useState(false)

    // Fetch calibration logs from API with pagination
    const { data: logs, pagination, isLoading, isFetching, error, refetch, search, setSearch, setPage } = useFetchPaginated<CalibrationLog>(
        "/api/instruments/calibration",
        { assetType: typeFilter }
    )
    const displayLogs = logs || []

    // Fetch instruments for dropdown (all instruments)
    const { data: instruments = [], isLoading: isLoadingInstruments } = useFetch<InstrumentOption[]>("/api/instruments?limit=all")

    // Create mutation
    const createMutation = useMutation<CalibrationLog, typeof formData>(
        "/api/instruments/calibration",
        "POST",
        {
            onSuccess: () => {
                setIsAddDialogOpen(false)
                setFormData({
                    instrumentId: "",
                    performedDate: new Date().toISOString().split("T")[0],
                    calibratorName: "",
                    calibratorPhone: "",
                    notes: "",
                    jobReportDocument: "",
                })
                refetch()
            }
        }
    )

    // NOTE: updateMutation removed - using direct fetch in handleEditSubmit to fix closure issue

    // Delete mutation
    const deleteMutation = useMutation<{ success: boolean }, undefined>(
        selectedLog ? `/api/instruments/calibration/${selectedLog.id}` : "",
        "DELETE",
        {
            onSuccess: () => {
                setIsDeleteDialogOpen(false)
                setSelectedLog(null)
                refetch()
            }
        }
    )

    const handleSubmit = async () => {
        if (!formData.instrumentId || !formData.performedDate) {
            return
        }
        await createMutation.mutate(formData)
    }

    const handleEdit = (log: CalibrationLog) => {
        setSelectedLog(log)
        setEditFormData({
            performedDate: log.performedDate,
            calibratorName: log.calibratorName || "",
            calibratorPhone: log.calibratorPhone || "",
            notes: log.notes || "",
            jobReportDocument: log.jobReportDocument || "",
        })
        setIsEditDialogOpen(true)
    }

    const handleEditSubmit = async () => {
        if (!editFormData.performedDate || !selectedLog) {
            return
        }

        setIsEditLoading(true)
        try {
            const response = await fetch(`/api/instruments/calibration/${selectedLog.id}`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(editFormData),
            })

            if (!response.ok) {
                const errorData = await response.json()
                throw new Error(errorData.error || 'Gagal menyimpan')
            }

            toast.success('Log kalibrasi berhasil diperbarui')
            setIsEditDialogOpen(false)
            setSelectedLog(null)
            refetch()
        } catch (error) {
            toast.error(error instanceof Error ? error.message : 'Terjadi kesalahan')
        } finally {
            setIsEditLoading(false)
        }
    }

    const handleDelete = (log: CalibrationLog) => {
        setSelectedLog(log)
        setIsDeleteDialogOpen(true)
    }

    const handleDeleteConfirm = async () => {
        await deleteMutation.mutate(undefined)
    }

    // Loading state
    if (isLoading) {
        return (
            <div className="flex flex-col items-center justify-center py-24">
                <Loader2 className="h-8 w-8 animate-spin text-primary mb-4" />
                <p className="text-muted-foreground">Memuat data kalibrasi...</p>
            </div>
        )
    }

    // Error state
    if (error) {
        return (
            <div className="flex flex-col items-center justify-center py-24">
                <p className="text-destructive mb-4">{error}</p>
                <Button onClick={refetch} variant="outline">
                    <RefreshCw className="h-4 w-4 mr-2" />
                    Coba Lagi
                </Button>
            </div>
        )
    }

    return (
        <div className="space-y-6">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight">Log Kalibrasi</h1>
                    <p className="text-muted-foreground">
                        Riwayat pelaksanaan kalibrasi instrumen dan peralatan
                    </p>
                </div>
                <Dialog open={isAddDialogOpen} onOpenChange={setIsAddDialogOpen}>
                    <DialogTrigger asChild>
                        <Button>
                            <Plus className="mr-2 h-4 w-4" />
                            Input Kalibrasi
                        </Button>
                    </DialogTrigger>
                    <DialogContent className="max-w-2xl">
                        <DialogHeader>
                            <DialogTitle>Input Log Kalibrasi</DialogTitle>
                            <DialogDescription>
                                Catat pelaksanaan kalibrasi instrumen
                            </DialogDescription>
                        </DialogHeader>
                        <div className="grid gap-4 py-4">
                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-2">
                                    <Label htmlFor="date">Tanggal Pelaksanaan *</Label>
                                    <Input
                                        id="date"
                                        type="date"
                                        value={formData.performedDate}
                                        onChange={(e) => setFormData(prev => ({ ...prev, performedDate: e.target.value }))}
                                    />
                                </div>
                                <div className="space-y-2">
                                    <Label htmlFor="instrument">Nama Alat *</Label>
                                    <Select
                                        value={formData.instrumentId}
                                        onValueChange={(value) => setFormData(prev => ({ ...prev, instrumentId: value }))}
                                        disabled={isLoadingInstruments}
                                    >
                                        <SelectTrigger>
                                            <SelectValue placeholder={isLoadingInstruments ? "Memuat..." : "Pilih instrumen"} />
                                        </SelectTrigger>
                                        <SelectContent>
                                            {(instruments ?? []).length === 0 ? (
                                                <SelectItem value="__empty__" disabled>
                                                    {isLoadingInstruments ? "Memuat data..." : "Tidak ada instrumen"}
                                                </SelectItem>
                                            ) : (
                                                (instruments ?? []).map((inst) => (
                                                    <SelectItem key={inst.id} value={inst.id}>
                                                        {inst.name}
                                                    </SelectItem>
                                                ))
                                            )}
                                        </SelectContent>
                                    </Select>
                                </div>
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-2">
                                    <Label htmlFor="calibrator">Nama Pengkalibrasi</Label>
                                    <Input
                                        id="calibrator"
                                        placeholder="Contoh: Teknisi A"
                                        value={formData.calibratorName}
                                        onChange={(e) => setFormData(prev => ({ ...prev, calibratorName: e.target.value }))}
                                    />
                                </div>
                                <div className="space-y-2">
                                    <Label htmlFor="phone">No HP Pengkalibrasi</Label>
                                    <Input
                                        id="phone"
                                        placeholder="Contoh: 081234567890"
                                        value={formData.calibratorPhone}
                                        onChange={(e) => setFormData(prev => ({ ...prev, calibratorPhone: e.target.value }))}
                                    />
                                </div>
                            </div>
                            <div className="space-y-2">
                                <Label htmlFor="notes">Catatan</Label>
                                <Textarea
                                    id="notes"
                                    placeholder="Catatan pelaksanaan kalibrasi"
                                    rows={3}
                                    value={formData.notes}
                                    onChange={(e) => setFormData(prev => ({ ...prev, notes: e.target.value }))}
                                />
                            </div>
                            <div className="space-y-2">
                                <Label htmlFor="document">Dokumen Laporan</Label>
                                <div className="flex items-center gap-2">
                                    <Input
                                        id="document"
                                        type="file"
                                        accept=".pdf,.doc,.docx"
                                        onChange={async (e) => {
                                            const file = e.target.files?.[0]
                                            if (!file) return

                                            // Validate file size (max 10MB for documents)
                                            const maxSize = 10 * 1024 * 1024
                                            if (file.size > maxSize) {
                                                toast.error("Ukuran file terlalu besar. Maksimal: 10MB")
                                                e.target.value = ""
                                                return
                                            }

                                            setIsUploading(true)
                                            try {
                                                const formDataUpload = new FormData()
                                                formDataUpload.append("file", file)
                                                formDataUpload.append("bucket", "calibration-reports")

                                                const response = await fetch("/api/upload", {
                                                    method: "POST",
                                                    body: formDataUpload,
                                                })

                                                if (response.ok) {
                                                    const data = await response.json()
                                                    setFormData(prev => ({ ...prev, jobReportDocument: data.publicUrl }))
                                                    toast.success("Dokumen berhasil diupload")
                                                } else {
                                                    const errorData = await response.json().catch(() => ({}))
                                                    toast.error(errorData.error || "Upload gagal")
                                                }
                                            } catch (error) {
                                                console.error("Upload error:", error)
                                                toast.error("Gagal mengupload dokumen")
                                            } finally {
                                                setIsUploading(false)
                                            }
                                        }}
                                        className="flex-1"
                                    />
                                    {isUploading && <Loader2 className="h-4 w-4 animate-spin" />}
                                    {formData.jobReportDocument && (
                                        <Badge variant="secondary" className="gap-1">
                                            <FileText className="h-3 w-3" />
                                            Uploaded
                                        </Badge>
                                    )}
                                </div>
                                <p className="text-xs text-muted-foreground">Format: PDF, DOC, DOCX (max 10MB)</p>
                            </div>
                            {createMutation.error && (
                                <p className="text-sm text-destructive">{createMutation.error}</p>
                            )}
                        </div>
                        <DialogFooter>
                            <Button variant="outline" onClick={() => setIsAddDialogOpen(false)}>
                                Batal
                            </Button>
                            <Button onClick={handleSubmit} disabled={createMutation.isLoading}>
                                {createMutation.isLoading && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
                                Simpan
                            </Button>
                        </DialogFooter>
                    </DialogContent>
                </Dialog>
            </div>

            {/* Filters */}
            <div className="flex gap-4">
                <div className="relative flex-1 max-w-sm">
                    <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
                    <Input
                        placeholder="Cari instrumen atau teknisi..."
                        value={search}
                        onChange={(e) => setSearch(e.target.value)}
                        className="pl-9"
                    />
                </div>
                <Select value={typeFilter} onValueChange={setTypeFilter}>
                    <SelectTrigger className="w-[180px]">
                        <SelectValue placeholder="Tipe Aset" />
                    </SelectTrigger>
                    <SelectContent>
                        <SelectItem value="all">Semua Tipe</SelectItem>
                        <SelectItem value="instrumen">Instrumen</SelectItem>
                        <SelectItem value="peralatan">Peralatan</SelectItem>
                    </SelectContent>
                </Select>
            </div>

            {/* Table */}
            <div className="rounded-md border">
                <Table>
                    <TableHeader>
                        <TableRow>
                            <TableHead>Tanggal</TableHead>
                            <TableHead>Nama Alat</TableHead>
                            <TableHead>Tipe</TableHead>
                            <TableHead>Pengkalibrasi</TableHead>
                            <TableHead>No HP</TableHead>
                            <TableHead>Catatan</TableHead>
                            <TableHead>Dokumen</TableHead>
                            <TableHead className="text-right">Aksi</TableHead>
                        </TableRow>
                    </TableHeader>
                    <TableBody>
                        {displayLogs.map((log) => (
                            <TableRow key={log.id}>
                                <TableCell>{new Date(log.performedDate).toLocaleDateString("id-ID")}</TableCell>
                                <TableCell className="font-medium">{log.instrumentName}</TableCell>
                                <TableCell>
                                    <Badge variant="outline">
                                        {log.assetType === "instrumen" ? "Instrumen" : "Peralatan"}
                                    </Badge>
                                </TableCell>
                                <TableCell>{log.calibratorName || "-"}</TableCell>
                                <TableCell>{log.calibratorPhone || "-"}</TableCell>
                                <TableCell className="max-w-[200px] truncate">{log.notes || "-"}</TableCell>
                                <TableCell>
                                    {log.jobReportDocument && (
                                        <Button variant="ghost" size="sm" asChild>
                                            <a href={log.jobReportDocument} target="_blank" rel="noopener noreferrer">
                                                <Download className="h-4 w-4 mr-1" />
                                                PDF
                                            </a>
                                        </Button>
                                    )}
                                </TableCell>
                                <TableCell className="text-right">
                                    <div className="flex justify-end gap-1">
                                        <Button variant="ghost" size="icon" onClick={() => handleEdit(log)}>
                                            <Pencil className="h-4 w-4" />
                                        </Button>
                                        <Button variant="ghost" size="icon" onClick={() => handleDelete(log)}>
                                            <Trash2 className="h-4 w-4 text-destructive" />
                                        </Button>
                                    </div>
                                </TableCell>
                            </TableRow>
                        ))}
                    </TableBody>
                </Table>
            </div>

            {displayLogs.length === 0 && (
                <div className="flex flex-col items-center justify-center py-12 text-center">
                    <FileText className="h-12 w-12 text-muted-foreground/50 mb-4" />
                    <p className="text-muted-foreground">Tidak ada log kalibrasi ditemukan</p>
                </div>
            )}

            {/* Pagination */}
            {pagination.totalPages > 1 && (
                <Pagination
                    pagination={pagination}
                    onPageChange={setPage}
                />
            )}

            {/* Edit Dialog */}
            <Dialog open={isEditDialogOpen} onOpenChange={setIsEditDialogOpen}>
                <DialogContent className="max-w-2xl">
                    <DialogHeader>
                        <DialogTitle>Edit Log Kalibrasi</DialogTitle>
                        <DialogDescription>
                            Edit data kalibrasi untuk {selectedLog?.instrumentName}
                        </DialogDescription>
                    </DialogHeader>
                    <div className="grid gap-4 py-4">
                        <div className="grid grid-cols-2 gap-4">
                            <div className="space-y-2">
                                <Label htmlFor="edit-date">Tanggal Pelaksanaan *</Label>
                                <Input
                                    id="edit-date"
                                    type="date"
                                    value={editFormData.performedDate}
                                    onChange={(e) => setEditFormData(prev => ({ ...prev, performedDate: e.target.value }))}
                                />
                            </div>
                            <div className="space-y-2">
                                <Label>Nama Alat</Label>
                                <Input value={selectedLog?.instrumentName || ""} disabled />
                            </div>
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <div className="space-y-2">
                                <Label htmlFor="edit-calibrator">Nama Pengkalibrasi</Label>
                                <Input
                                    id="edit-calibrator"
                                    placeholder="Contoh: Teknisi A"
                                    value={editFormData.calibratorName}
                                    onChange={(e) => setEditFormData(prev => ({ ...prev, calibratorName: e.target.value }))}
                                />
                            </div>
                            <div className="space-y-2">
                                <Label htmlFor="edit-phone">No HP Pengkalibrasi</Label>
                                <Input
                                    id="edit-phone"
                                    placeholder="Contoh: 081234567890"
                                    value={editFormData.calibratorPhone}
                                    onChange={(e) => setEditFormData(prev => ({ ...prev, calibratorPhone: e.target.value }))}
                                />
                            </div>
                        </div>
                        <div className="space-y-2">
                            <Label htmlFor="edit-notes">Catatan</Label>
                            <Textarea
                                id="edit-notes"
                                placeholder="Catatan pelaksanaan kalibrasi"
                                rows={3}
                                value={editFormData.notes}
                                onChange={(e) => setEditFormData(prev => ({ ...prev, notes: e.target.value }))}
                            />
                        </div>
                        <div className="space-y-2">
                            <Label htmlFor="edit-document">Dokumen Laporan</Label>
                            <div className="flex items-center gap-2">
                                <Input
                                    id="edit-document"
                                    type="file"
                                    accept=".pdf,.doc,.docx"
                                    onChange={async (e) => {
                                        const file = e.target.files?.[0]
                                        if (!file) return

                                        // Validate file size (max 10MB for documents)
                                        const maxSize = 10 * 1024 * 1024
                                        if (file.size > maxSize) {
                                            toast.error("Ukuran file terlalu besar. Maksimal: 10MB")
                                            e.target.value = ""
                                            return
                                        }

                                        setIsEditUploading(true)
                                        try {
                                            const formDataUpload = new FormData()
                                            formDataUpload.append("file", file)
                                            formDataUpload.append("bucket", "calibration-reports")

                                            const response = await fetch("/api/upload", {
                                                method: "POST",
                                                body: formDataUpload,
                                            })

                                            if (response.ok) {
                                                const data = await response.json()
                                                setEditFormData(prev => ({ ...prev, jobReportDocument: data.publicUrl }))
                                                toast.success("Dokumen berhasil diupload")
                                            } else {
                                                const errorData = await response.json().catch(() => ({}))
                                                toast.error(errorData.error || "Upload gagal")
                                            }
                                        } catch (error) {
                                            console.error("Upload error:", error)
                                            toast.error("Gagal mengupload dokumen")
                                        } finally {
                                            setIsEditUploading(false)
                                        }
                                    }}
                                    className="flex-1"
                                />
                                {isEditUploading && <Loader2 className="h-4 w-4 animate-spin" />}
                                {editFormData.jobReportDocument && (
                                    <Badge variant="secondary" className="gap-1">
                                        <FileText className="h-3 w-3" />
                                        Uploaded
                                    </Badge>
                                )}
                            </div>
                            <p className="text-xs text-muted-foreground">Format: PDF, DOC, DOCX (max 10MB)</p>
                        </div>
                    </div>
                    <DialogFooter>
                        <Button variant="outline" onClick={() => setIsEditDialogOpen(false)}>
                            Batal
                        </Button>
                        <Button onClick={handleEditSubmit} disabled={isEditLoading}>
                            {isEditLoading && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
                            Simpan
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>

            {/* Delete Confirmation Dialog */}
            <AlertDialog open={isDeleteDialogOpen} onOpenChange={setIsDeleteDialogOpen}>
                <AlertDialogContent>
                    <AlertDialogHeader>
                        <AlertDialogTitle>Hapus Log Kalibrasi?</AlertDialogTitle>
                        <AlertDialogDescription>
                            Apakah Anda yakin ingin menghapus log kalibrasi untuk <strong>{selectedLog?.instrumentName}</strong> pada tanggal {selectedLog ? new Date(selectedLog.performedDate).toLocaleDateString("id-ID") : ""}? Tindakan ini tidak dapat dibatalkan.
                        </AlertDialogDescription>
                    </AlertDialogHeader>
                    <AlertDialogFooter>
                        <AlertDialogCancel>Batal</AlertDialogCancel>
                        <AlertDialogAction
                            onClick={handleDeleteConfirm}
                            className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
                        >
                            {deleteMutation.isLoading ? (
                                <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                            ) : null}
                            Hapus
                        </AlertDialogAction>
                    </AlertDialogFooter>
                </AlertDialogContent>
            </AlertDialog>
        </div>
    )
}

"use client";

import { useState, useEffect, useCallback } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from "@/components/ui/table";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogHeader,
    DialogTitle,
    DialogFooter,
} from "@/components/ui/dialog";
import {
    FileText,
    Search,
    Filter,
    Eye,
    Download,
    Trash2,
    RefreshCw,
    Loader2,
    ChevronLeft,
    ChevronRight,
    FileWarning,
    Upload,
    ExternalLink,
} from "lucide-react";
import { format } from "date-fns";
import { id as localeID } from "date-fns/locale";

// Types
interface DocumentItem {
    id: string;
    name: string;
    documentType: 'msds' | 'coa';
    fileUrl: string;
    fileSize: number | null;
    mimeType: string;
    catalogType: 'reagent' | 'standard';
    catalogId: string;
    catalogName?: string;
    uploadedAt: string;
    createdAt: string;
}

interface DocumentStats {
    total: number;
    msds: number;
    coa: number;
    byReagent: number;
    byStandard: number;
}

export default function DocumentLibraryPage() {
    const [documents, setDocuments] = useState<DocumentItem[]>([]);
    const [pagination, setPagination] = useState({
        page: 1,
        limit: 20,
        total: 0,
        totalPages: 0,
    });
    const [stats, setStats] = useState<DocumentStats | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    // Filters
    const [search, setSearch] = useState("");
    const [documentTypeFilter, setDocumentTypeFilter] = useState<string>("all");
    const [catalogTypeFilter, setCatalogTypeFilter] = useState<string>("all");

    // Preview
    const [previewUrl, setPreviewUrl] = useState<string | null>(null);
    const [previewOpen, setPreviewOpen] = useState(false);
    const [previewDocument, setPreviewDocument] = useState<DocumentItem | null>(null);

    // Upload Dialog
    const [uploadOpen, setUploadOpen] = useState(false);
    const [isUploading, setIsUploading] = useState(false);
    const [uploadForm, setUploadForm] = useState({
        name: "",
        documentType: "msds" as "msds" | "coa",
        catalogType: "reagent" as "reagent" | "standard",
        catalogId: "",
    });
    const [selectedFile, setSelectedFile] = useState<File | null>(null);
    const [catalogs, setCatalogs] = useState<{ id: string; name: string }[]>([]);
    const [loadingCatalogs, setLoadingCatalogs] = useState(false);

    // Fetch catalogs based on selected type
    const fetchCatalogs = useCallback(async (type: "reagent" | "standard") => {
        setLoadingCatalogs(true);
        try {
            const endpoint = type === "reagent" ? "/api/inventory/reagents" : "/api/inventory/standards";
            const response = await fetch(endpoint);
            if (response.ok) {
                const result = await response.json();
                const items = result.data || result;
                setCatalogs(
                    items.map((item: { id: string; reagentName?: string; standardName?: string; name?: string }) => ({
                        id: item.id,
                        name: item.reagentName || item.standardName || item.name || "Unknown",
                    }))
                );
            }
        } catch (err) {
            console.error("Failed to fetch catalogs:", err);
            setCatalogs([]);
        } finally {
            setLoadingCatalogs(false);
        }
    }, []);

    // Handle catalog type change
    useEffect(() => {
        if (uploadOpen) {
            fetchCatalogs(uploadForm.catalogType);
            setUploadForm(prev => ({ ...prev, catalogId: "" }));
        }
    }, [uploadForm.catalogType, uploadOpen, fetchCatalogs]);

    // Handle file selection
    const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            // Validate file type
            const allowedTypes = [
                'application/pdf',
                'application/msword',
                'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
            ];
            if (!allowedTypes.includes(file.type)) {
                alert("Tipe file tidak didukung. Hanya PDF, DOC, dan DOCX yang diizinkan.");
                return;
            }
            // Validate file size (10MB)
            if (file.size > 10 * 1024 * 1024) {
                alert("Ukuran file terlalu besar. Maksimal 10MB.");
                return;
            }
            setSelectedFile(file);
            // Auto-fill name if empty
            if (!uploadForm.name) {
                setUploadForm(prev => ({ ...prev, name: file.name.replace(/\.[^/.]+$/, '') }));
            }
        }
    };

    // Handle upload
    const handleUpload = async () => {
        if (!uploadForm.name || !selectedFile || !uploadForm.catalogId) {
            alert("Semua field wajib diisi!");
            return;
        }

        setIsUploading(true);
        try {
            // Step 1: Upload file to Supabase Storage
            const formData = new FormData();
            formData.append('file', selectedFile);
            formData.append('catalogType', uploadForm.catalogType);
            formData.append('catalogId', uploadForm.catalogId);
            formData.append('documentType', uploadForm.documentType);

            const uploadResponse = await fetch("/api/inventory/documents/upload", {
                method: "POST",
                body: formData,
            });

            if (!uploadResponse.ok) {
                const err = await uploadResponse.json();
                throw new Error(err.error || "Gagal mengupload file");
            }

            const uploadResult = await uploadResponse.json();

            // Step 2: Create document record in database
            const response = await fetch("/api/inventory/documents", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    name: uploadForm.name,
                    documentType: uploadForm.documentType,
                    fileUrl: uploadResult.publicUrl,
                    fileSize: uploadResult.fileSize,
                    mimeType: uploadResult.mimeType,
                    catalogType: uploadForm.catalogType,
                    catalogId: uploadForm.catalogId,
                }),
            });

            if (response.ok) {
                setUploadOpen(false);
                setUploadForm({
                    name: "",
                    documentType: "msds",
                    catalogType: "reagent",
                    catalogId: "",
                });
                setSelectedFile(null);
                fetchDocuments();
                fetchStats();
            } else {
                const err = await response.json();
                alert(err.error || "Gagal menyimpan dokumen");
            }
        } catch (err) {
            console.error("Upload error:", err);
            alert(err instanceof Error ? err.message : "Terjadi kesalahan saat upload");
        } finally {
            setIsUploading(false);
        }
    };

    // Fetch documents
    const fetchDocuments = useCallback(async () => {
        setIsLoading(true);
        setError(null);
        try {
            const params = new URLSearchParams();
            params.set("page", pagination.page.toString());
            params.set("limit", "20");
            if (search) params.set("search", search);
            if (documentTypeFilter !== "all") params.set("documentType", documentTypeFilter);
            if (catalogTypeFilter !== "all") params.set("catalogType", catalogTypeFilter);

            const response = await fetch(`/api/inventory/documents?${params.toString()}`);
            if (!response.ok) {
                const errorData = await response.json();
                throw new Error(errorData.error || "Gagal mengambil data");
            }
            const result = await response.json();
            setDocuments(result.data);
            setPagination(result.pagination);
        } catch (err) {
            setError(err instanceof Error ? err.message : "Terjadi kesalahan");
        } finally {
            setIsLoading(false);
        }
    }, [pagination.page, search, documentTypeFilter, catalogTypeFilter]);

    // Fetch stats
    const fetchStats = useCallback(async () => {
        try {
            const response = await fetch("/api/inventory/documents/stats");
            if (response.ok) {
                const result = await response.json();
                setStats(result.stats);
            }
        } catch (err) {
            console.error("Failed to fetch stats:", err);
        }
    }, []);

    useEffect(() => {
        fetchDocuments();
    }, [fetchDocuments]);

    useEffect(() => {
        fetchStats();
    }, [fetchStats]);

    // Debounce search
    useEffect(() => {
        const timer = setTimeout(() => {
            setPagination(prev => ({ ...prev, page: 1 }));
            fetchDocuments();
        }, 300);
        return () => clearTimeout(timer);
    }, [search]);

    // Handle filter changes
    const handleFilterChange = () => {
        setPagination(prev => ({ ...prev, page: 1 }));
    };

    useEffect(() => {
        handleFilterChange();
    }, [documentTypeFilter, catalogTypeFilter]);

    // Preview document
    const handlePreview = (doc: DocumentItem) => {
        setPreviewDocument(doc);
        setPreviewUrl(doc.fileUrl);
        setPreviewOpen(true);
    };

    // Delete document
    const handleDelete = async (id: string) => {
        if (!confirm("Yakin ingin menghapus dokumen ini?")) return;

        try {
            const response = await fetch(`/api/inventory/documents/${id}`, {
                method: "DELETE",
            });
            if (response.ok) {
                fetchDocuments();
                fetchStats();
            }
        } catch (err) {
            console.error("Failed to delete:", err);
        }
    };

    // Format file size
    const formatFileSize = (bytes: number | null): string => {
        if (!bytes) return "-";
        if (bytes < 1024) return `${bytes} B`;
        if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
        return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
    };

    return (
        <div className="space-y-6">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight">Document Library</h1>
                    <p className="text-muted-foreground">
                        Pusat dokumen MSDS dan CoA untuk reagent dan standard
                    </p>
                </div>
                <div className="flex items-center space-x-2">
                    <Button onClick={() => setUploadOpen(true)}>
                        <Upload className="mr-2 h-4 w-4" />
                        Upload Dokumen
                    </Button>
                    <Button variant="outline" onClick={() => { fetchDocuments(); fetchStats(); }} disabled={isLoading}>
                        <RefreshCw className={`mr-2 h-4 w-4 ${isLoading ? 'animate-spin' : ''}`} />
                        Refresh
                    </Button>
                </div>
            </div>

            {/* Stats Cards */}
            <div className="grid gap-4 grid-cols-2 md:grid-cols-5">
                <Card>
                    <CardContent className="pt-4">
                        <div className="flex items-center space-x-2">
                            <FileText className="h-5 w-5 text-blue-500" />
                            <div>
                                <p className="text-2xl font-bold">{stats?.total || 0}</p>
                                <p className="text-xs text-muted-foreground">Total Dokumen</p>
                            </div>
                        </div>
                    </CardContent>
                </Card>
                <Card>
                    <CardContent className="pt-4">
                        <div className="flex items-center space-x-2">
                            <FileWarning className="h-5 w-5 text-orange-500" />
                            <div>
                                <p className="text-2xl font-bold">{stats?.msds || 0}</p>
                                <p className="text-xs text-muted-foreground">MSDS</p>
                            </div>
                        </div>
                    </CardContent>
                </Card>
                <Card>
                    <CardContent className="pt-4">
                        <div className="flex items-center space-x-2">
                            <FileText className="h-5 w-5 text-green-500" />
                            <div>
                                <p className="text-2xl font-bold">{stats?.coa || 0}</p>
                                <p className="text-xs text-muted-foreground">CoA</p>
                            </div>
                        </div>
                    </CardContent>
                </Card>
                <Card>
                    <CardContent className="pt-4">
                        <div className="flex items-center space-x-2">
                            <div className="h-3 w-3 rounded-full bg-purple-500" />
                            <div>
                                <p className="text-2xl font-bold">{stats?.byReagent || 0}</p>
                                <p className="text-xs text-muted-foreground">Reagent</p>
                            </div>
                        </div>
                    </CardContent>
                </Card>
                <Card>
                    <CardContent className="pt-4">
                        <div className="flex items-center space-x-2">
                            <div className="h-3 w-3 rounded-full bg-cyan-500" />
                            <div>
                                <p className="text-2xl font-bold">{stats?.byStandard || 0}</p>
                                <p className="text-xs text-muted-foreground">Standard</p>
                            </div>
                        </div>
                    </CardContent>
                </Card>
            </div>

            {/* Filters */}
            <Card>
                <CardHeader>
                    <CardTitle className="text-base">Filter & Pencarian</CardTitle>
                </CardHeader>
                <CardContent>
                    <div className="flex flex-wrap gap-4">
                        <div className="flex-1 min-w-[200px]">
                            <div className="relative">
                                <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
                                <Input
                                    placeholder="Cari nama dokumen..."
                                    className="pl-8"
                                    value={search}
                                    onChange={(e) => setSearch(e.target.value)}
                                />
                            </div>
                        </div>
                        <Select value={documentTypeFilter} onValueChange={setDocumentTypeFilter}>
                            <SelectTrigger className="w-[150px]">
                                <SelectValue placeholder="Tipe Dokumen" />
                            </SelectTrigger>
                            <SelectContent>
                                <SelectItem value="all">Semua Tipe</SelectItem>
                                <SelectItem value="msds">MSDS</SelectItem>
                                <SelectItem value="coa">CoA</SelectItem>
                            </SelectContent>
                        </Select>
                        <Select value={catalogTypeFilter} onValueChange={setCatalogTypeFilter}>
                            <SelectTrigger className="w-[150px]">
                                <SelectValue placeholder="Kategori" />
                            </SelectTrigger>
                            <SelectContent>
                                <SelectItem value="all">Semua Kategori</SelectItem>
                                <SelectItem value="reagent">Reagent</SelectItem>
                                <SelectItem value="standard">Standard</SelectItem>
                            </SelectContent>
                        </Select>
                    </div>
                </CardContent>
            </Card>

            {/* Documents Table */}
            <Card>
                <CardContent className="p-0">
                    {isLoading ? (
                        <div className="flex items-center justify-center h-64">
                            <Loader2 className="h-8 w-8 animate-spin text-primary" />
                        </div>
                    ) : error ? (
                        <div className="flex flex-col items-center justify-center h-64 space-y-4">
                            <p className="text-destructive">{error}</p>
                            <Button onClick={fetchDocuments}>Coba Lagi</Button>
                        </div>
                    ) : (
                        <Table>
                            <TableHeader>
                                <TableRow>
                                    <TableHead>Nama Dokumen</TableHead>
                                    <TableHead>Tipe</TableHead>
                                    <TableHead>Kategori</TableHead>
                                    <TableHead>Item Terkait</TableHead>
                                    <TableHead>Ukuran</TableHead>
                                    <TableHead>Diupload</TableHead>
                                    <TableHead className="text-center">Aksi</TableHead>
                                </TableRow>
                            </TableHeader>
                            <TableBody>
                                {documents.length === 0 ? (
                                    <TableRow>
                                        <TableCell colSpan={7} className="text-center py-8 text-muted-foreground">
                                            <FileText className="h-12 w-12 mx-auto mb-2 opacity-50" />
                                            <p>Belum ada dokumen</p>
                                            <p className="text-sm">Upload dokumen MSDS atau CoA dari halaman katalog</p>
                                        </TableCell>
                                    </TableRow>
                                ) : (
                                    documents.map((doc) => (
                                        <TableRow key={doc.id}>
                                            <TableCell>
                                                <div className="flex items-center space-x-2">
                                                    <FileText className="h-4 w-4 text-muted-foreground" />
                                                    <span className="font-medium">{doc.name}</span>
                                                </div>
                                            </TableCell>
                                            <TableCell>
                                                <Badge
                                                    variant={doc.documentType === 'msds' ? 'default' : 'secondary'}
                                                    className={doc.documentType === 'msds' ? 'bg-orange-500' : 'bg-green-500'}
                                                >
                                                    {doc.documentType?.toUpperCase() || '-'}
                                                </Badge>
                                            </TableCell>
                                            <TableCell>
                                                <Badge variant="outline">
                                                    {doc.catalogType === 'reagent' ? 'Reagent' : doc.catalogType === 'standard' ? 'Standard' : '-'}
                                                </Badge>
                                            </TableCell>
                                            <TableCell>{doc.catalogName || '-'}</TableCell>
                                            <TableCell>{formatFileSize(doc.fileSize)}</TableCell>
                                            <TableCell>
                                                {format(new Date(doc.uploadedAt), 'dd MMM yyyy', { locale: localeID })}
                                            </TableCell>
                                            <TableCell>
                                                <div className="flex items-center justify-center space-x-1">
                                                    <Button
                                                        variant="ghost"
                                                        size="icon"
                                                        onClick={() => handlePreview(doc)}
                                                        title="Preview"
                                                    >
                                                        <Eye className="h-4 w-4" />
                                                    </Button>
                                                    <Button
                                                        variant="ghost"
                                                        size="icon"
                                                        onClick={() => window.open(doc.fileUrl, '_blank')}
                                                        title="Download"
                                                    >
                                                        <Download className="h-4 w-4" />
                                                    </Button>
                                                    <Button
                                                        variant="ghost"
                                                        size="icon"
                                                        onClick={() => handleDelete(doc.id)}
                                                        className="text-destructive hover:text-destructive"
                                                        title="Hapus"
                                                    >
                                                        <Trash2 className="h-4 w-4" />
                                                    </Button>
                                                </div>
                                            </TableCell>
                                        </TableRow>
                                    ))
                                )}
                            </TableBody>
                        </Table>
                    )}

                    {/* Pagination */}
                    {pagination.totalPages > 1 && (
                        <div className="flex items-center justify-between p-4 border-t">
                            <p className="text-sm text-muted-foreground">
                                Menampilkan {((pagination.page - 1) * pagination.limit) + 1} - {Math.min(pagination.page * pagination.limit, pagination.total)} dari {pagination.total} dokumen
                            </p>
                            <div className="flex items-center space-x-2">
                                <Button
                                    variant="outline"
                                    size="sm"
                                    onClick={() => setPagination(prev => ({ ...prev, page: prev.page - 1 }))}
                                    disabled={pagination.page <= 1}
                                >
                                    <ChevronLeft className="h-4 w-4" />
                                </Button>
                                <span className="text-sm">
                                    Hal {pagination.page} / {pagination.totalPages}
                                </span>
                                <Button
                                    variant="outline"
                                    size="sm"
                                    onClick={() => setPagination(prev => ({ ...prev, page: prev.page + 1 }))}
                                    disabled={pagination.page >= pagination.totalPages}
                                >
                                    <ChevronRight className="h-4 w-4" />
                                </Button>
                            </div>
                        </div>
                    )}
                </CardContent>
            </Card>

            {/* Preview Dialog */}
            <Dialog open={previewOpen} onOpenChange={setPreviewOpen}>
                <DialogContent className="max-w-4xl max-h-[90vh]">
                    <DialogHeader>
                        <DialogTitle className="flex items-center space-x-2">
                            <FileText className="h-5 w-5" />
                            <span>{previewDocument?.name}</span>
                        </DialogTitle>
                        <DialogDescription>
                            {previewDocument?.catalogName || '-'} ΓÇó {previewDocument?.documentType?.toUpperCase() || '-'}
                        </DialogDescription>
                    </DialogHeader>

                    {previewUrl && (
                        <div className="h-[60vh] border rounded-md overflow-hidden">
                            <iframe
                                src={previewUrl}
                                className="w-full h-full"
                                title="Document Preview"
                            />
                        </div>
                    )}

                    <DialogFooter>
                        <Button variant="outline" onClick={() => setPreviewOpen(false)}>
                            Tutup
                        </Button>
                        <Button onClick={() => previewUrl && window.open(previewUrl, '_blank')}>
                            <ExternalLink className="h-4 w-4 mr-2" />
                            Buka di Tab Baru
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>

            {/* Upload Dialog */}
            <Dialog open={uploadOpen} onOpenChange={setUploadOpen}>
                <DialogContent className="sm:max-w-md">
                    <DialogHeader>
                        <DialogTitle className="flex items-center space-x-2">
                            <Upload className="h-5 w-5" />
                            <span>Upload Dokumen Baru</span>
                        </DialogTitle>
                        <DialogDescription>
                            Upload dokumen MSDS atau CoA untuk reagent atau standard
                        </DialogDescription>
                    </DialogHeader>

                    <div className="space-y-4 py-4">
                        {/* Document Name */}
                        <div className="space-y-2">
                            <label className="text-sm font-medium">Nama Dokumen *</label>
                            <Input
                                placeholder="Contoh: MSDS - Methanol"
                                value={uploadForm.name}
                                onChange={(e) => setUploadForm(prev => ({ ...prev, name: e.target.value }))}
                            />
                        </div>

                        {/* Document Type */}
                        <div className="space-y-2">
                            <label className="text-sm font-medium">Tipe Dokumen *</label>
                            <Select
                                value={uploadForm.documentType}
                                onValueChange={(value: "msds" | "coa") => setUploadForm(prev => ({ ...prev, documentType: value }))}
                            >
                                <SelectTrigger>
                                    <SelectValue />
                                </SelectTrigger>
                                <SelectContent>
                                    <SelectItem value="msds">MSDS (Material Safety Data Sheet)</SelectItem>
                                    <SelectItem value="coa">CoA (Certificate of Analysis)</SelectItem>
                                </SelectContent>
                            </Select>
                        </div>

                        {/* Catalog Type */}
                        <div className="space-y-2">
                            <label className="text-sm font-medium">Kategori *</label>
                            <Select
                                value={uploadForm.catalogType}
                                onValueChange={(value: "reagent" | "standard") => setUploadForm(prev => ({ ...prev, catalogType: value }))}
                            >
                                <SelectTrigger>
                                    <SelectValue />
                                </SelectTrigger>
                                <SelectContent>
                                    <SelectItem value="reagent">Reagent</SelectItem>
                                    <SelectItem value="standard">Standard</SelectItem>
                                </SelectContent>
                            </Select>
                        </div>

                        {/* Catalog Item */}
                        <div className="space-y-2">
                            <label className="text-sm font-medium">Item Terkait *</label>
                            <Select
                                value={uploadForm.catalogId}
                                onValueChange={(value) => setUploadForm(prev => ({ ...prev, catalogId: value }))}
                                disabled={loadingCatalogs}
                            >
                                <SelectTrigger>
                                    <SelectValue placeholder={loadingCatalogs ? "Loading..." : "Pilih item"} />
                                </SelectTrigger>
                                <SelectContent>
                                    {catalogs.map((item) => (
                                        <SelectItem key={item.id} value={item.id}>
                                            {item.name}
                                        </SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                        </div>

                        {/* File Upload */}
                        <div className="space-y-2">
                            <label className="text-sm font-medium">File Dokumen (PDF/DOC/DOCX) *</label>
                            <div className="border-2 border-dashed border-muted-foreground/25 rounded-lg p-4 text-center hover:border-primary/50 transition-colors">
                                <input
                                    type="file"
                                    accept=".pdf,.doc,.docx,application/pdf,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document"
                                    onChange={handleFileSelect}
                                    className="hidden"
                                    id="file-upload"
                                />
                                <label htmlFor="file-upload" className="cursor-pointer">
                                    {selectedFile ? (
                                        <div className="flex items-center justify-center space-x-2">
                                            <FileText className="h-5 w-5 text-primary" />
                                            <span className="text-sm font-medium">{selectedFile.name}</span>
                                            <Badge variant="secondary">
                                                {(selectedFile.size / 1024).toFixed(1)} KB
                                            </Badge>
                                        </div>
                                    ) : (
                                        <div className="flex flex-col items-center space-y-2">
                                            <Upload className="h-8 w-8 text-muted-foreground" />
                                            <span className="text-sm text-muted-foreground">
                                                Klik untuk pilih file atau drag & drop
                                            </span>
                                            <span className="text-xs text-muted-foreground">
                                                PDF, DOC, DOCX (Maks. 10MB)
                                            </span>
                                        </div>
                                    )}
                                </label>
                            </div>
                        </div>
                    </div>

                    <DialogFooter>
                        <Button variant="outline" onClick={() => setUploadOpen(false)}>
                            Batal
                        </Button>
                        <Button onClick={handleUpload} disabled={isUploading}>
                            {isUploading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                            Simpan
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>
        </div>
    );
}

"use client"

import { useState } from "react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Badge } from "@/components/ui/badge"
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select"
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from "@/components/ui/table"
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "@/components/ui/dialog"
import { Label } from "@/components/ui/label"
import { Textarea } from "@/components/ui/textarea"
import { Plus, Search, ShoppingCart, Check, X, Loader2, RefreshCw, ChevronDown, ChevronUp, Trash2 } from "lucide-react"
import {
    AlertDialog,
    AlertDialogAction,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle,
} from "@/components/ui/alert-dialog"
import { OrderStatus } from "@/types"
import { useFetchPaginated, useMutation } from "@/hooks/use-api"
import { Pagination } from "@/components/ui/pagination"

interface OrderItem {
    id: string
    itemName: string
    quantity: number
    unit?: string
    notes?: string
}

interface Order {
    id: string
    orderNumber: string
    orderDate: string
    orderedBy: string
    orderedByUser?: { fullName: string }
    status: OrderStatus
    items: OrderItem[]
    approvedBy?: string
    approvedByUser?: { fullName: string }
    approvedDate?: string
    notes?: string
}

const statusConfig: Record<OrderStatus, { label: string; variant: "default" | "secondary" | "destructive" | "outline" }> = {
    pending: { label: "Menunggu Approval", variant: "secondary" },
    approved: { label: "Disetujui", variant: "default" },
    rejected: { label: "Ditolak", variant: "destructive" },
    received: { label: "Diterima", variant: "outline" },
    cancelled: { label: "Dibatalkan", variant: "outline" },
}

export default function OrdersPage() {
    const [statusFilter, setStatusFilter] = useState<string>("all")
    const [isAddDialogOpen, setIsAddDialogOpen] = useState(false)
    const [newOrderItems, setNewOrderItems] = useState("")
    const [newOrderNotes, setNewOrderNotes] = useState("")
    const [expandedOrders, setExpandedOrders] = useState<Set<string>>(new Set())
    const [deleteId, setDeleteId] = useState<string | null>(null)
    const [isDeleting, setIsDeleting] = useState(false)

    const toggleExpand = (orderId: string) => {
        const newExpanded = new Set(expandedOrders)
        if (newExpanded.has(orderId)) {
            newExpanded.delete(orderId)
        } else {
            newExpanded.add(orderId)
        }
        setExpandedOrders(newExpanded)
    }

    // Fetch orders from API with pagination
    const { data: displayOrders, pagination, isLoading, isFetching, error, refetch, search, setSearch, setPage } = useFetchPaginated<Order>(
        "/api/inventory/orders",
        { status: statusFilter }
    )

    // Mutations
    const createOrder = useMutation<Order, { items: { itemName: string; quantity: number }[]; notes?: string }>(
        "/api/inventory/orders",
        "POST",
        {
            onSuccess: () => {
                refetch()
                setIsAddDialogOpen(false)
                setNewOrderItems("")
                setNewOrderNotes("")
            },
        }
    )

    const approveOrder = useMutation<Order, { action: string }>(
        "/api/inventory/orders",
        "POST",
        { onSuccess: () => refetch() }
    )

    const handleCreateOrder = async () => {
        // Parse items from textarea
        const lines = newOrderItems.split("\n").filter(line => line.trim())
        const items = lines.map(line => {
            // Parse format: "- Item name x quantity" or "Item name x quantity"
            const cleanLine = line.replace(/^[-ΓÇó]\s*/, "").trim()
            const match = cleanLine.match(/(.+?)\s*[xX]\s*(\d+)$/)
            if (match) {
                return { itemName: match[1].trim(), quantity: parseInt(match[2]) }
            }
            return { itemName: cleanLine, quantity: 1 }
        })

        if (items.length > 0) {
            await createOrder.mutate({ items, notes: newOrderNotes || undefined })
        }
    }

    const handleApprove = async (orderId: string) => {
        await fetch(`/api/inventory/orders/${orderId}/approve`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ action: "approve" }),
        })
        refetch()
    }

    const handleReject = async (orderId: string) => {
        await fetch(`/api/inventory/orders/${orderId}/approve`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ action: "reject" }),
        })
        refetch()
    }

    const handleDelete = async () => {
        if (!deleteId) return
        setIsDeleting(true)
        try {
            const res = await fetch(`/api/inventory/orders/${deleteId}`, { method: "DELETE" })
            if (!res.ok) throw new Error("Gagal menghapus")
            refetch()
        } catch (err) {
            console.error(err)
        } finally {
            setIsDeleting(false)
            setDeleteId(null)
        }
    }

    // Loading state
    if (isLoading) {
        return (
            <div className="flex items-center justify-center h-64">
                <Loader2 className="h-8 w-8 animate-spin text-primary" />
                <span className="ml-2 text-muted-foreground">Memuat data pesanan...</span>
            </div>
        )
    }

    // Error state
    if (error) {
        return (
            <div className="flex flex-col items-center justify-center h-64 space-y-4">
                <p className="text-destructive">{error}</p>
                <Button variant="outline" onClick={() => refetch()}>
                    <RefreshCw className="mr-2 h-4 w-4" />
                    Coba Lagi
                </Button>
            </div>
        )
    }

    return (
        <div className="space-y-6">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight">Pesanan</h1>
                    <p className="text-muted-foreground">
                        Kelola pesanan bahan dan peralatan laboratorium
                    </p>
                </div>
                <Dialog open={isAddDialogOpen} onOpenChange={setIsAddDialogOpen}>
                    <DialogTrigger asChild>
                        <Button>
                            <Plus className="mr-2 h-4 w-4" />
                            Buat Pesanan
                        </Button>
                    </DialogTrigger>
                    <DialogContent className="max-w-2xl">
                        <DialogHeader>
                            <DialogTitle>Buat Pesanan Baru</DialogTitle>
                            <DialogDescription>
                                Tambahkan item yang akan dipesan
                            </DialogDescription>
                        </DialogHeader>
                        <div className="grid gap-4 py-4">
                            <div className="space-y-2">
                                <Label htmlFor="items">Item yang Dipesan</Label>
                                <Textarea
                                    id="items"
                                    placeholder="Contoh:&#10;- Methanol HPLC Grade 2.5L x 5&#10;- Fintip 100-1000 ┬╡L x 10"
                                    rows={5}
                                    value={newOrderItems}
                                    onChange={(e) => setNewOrderItems(e.target.value)}
                                />
                            </div>
                            <div className="space-y-2">
                                <Label htmlFor="notes">Catatan</Label>
                                <Textarea
                                    id="notes"
                                    placeholder="Catatan tambahan (opsional)"
                                    rows={3}
                                    value={newOrderNotes}
                                    onChange={(e) => setNewOrderNotes(e.target.value)}
                                />
                            </div>
                        </div>
                        <DialogFooter>
                            <Button variant="outline" onClick={() => setIsAddDialogOpen(false)}>
                                Batal
                            </Button>
                            <Button
                                onClick={handleCreateOrder}
                                disabled={createOrder.isLoading || !newOrderItems.trim()}
                            >
                                {createOrder.isLoading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                                Kirim Pesanan
                            </Button>
                        </DialogFooter>
                    </DialogContent>
                </Dialog>
            </div>

            {/* Filters */}
            <div className="flex gap-4">
                <div className="relative flex-1 max-w-sm">
                    <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
                    <Input
                        placeholder="Cari nomor order atau nama..."
                        value={search}
                        onChange={(e) => setSearch(e.target.value)}
                        className="pl-9"
                    />
                </div>
                <Select value={statusFilter} onValueChange={setStatusFilter}>
                    <SelectTrigger className="w-[200px]">
                        <SelectValue placeholder="Filter Status" />
                    </SelectTrigger>
                    <SelectContent>
                        <SelectItem value="all">Semua Status</SelectItem>
                        <SelectItem value="pending">Menunggu Approval</SelectItem>
                        <SelectItem value="approved">Disetujui</SelectItem>
                        <SelectItem value="received">Diterima</SelectItem>
                        <SelectItem value="rejected">Ditolak</SelectItem>
                    </SelectContent>
                </Select>
                <Button variant="outline" size="icon" onClick={() => refetch()}>
                    <RefreshCw className="h-4 w-4" />
                </Button>
            </div>

            {/* Table */}
            <div className="rounded-md border">
                <Table>
                    <TableHeader>
                        <TableRow>
                            <TableHead>No. Order</TableHead>
                            <TableHead>Tanggal</TableHead>
                            <TableHead>Dipesan Oleh</TableHead>
                            <TableHead>Item</TableHead>
                            <TableHead>Status</TableHead>
                            <TableHead>Disetujui Oleh</TableHead>
                            <TableHead className="text-right">Aksi</TableHead>
                        </TableRow>
                    </TableHeader>
                    <TableBody>
                        {displayOrders.map((order) => (
                            <TableRow key={order.id}>
                                <TableCell className="font-medium">{order.orderNumber}</TableCell>
                                <TableCell>{new Date(order.orderDate).toLocaleDateString("id-ID")}</TableCell>
                                <TableCell>{order.orderedByUser?.fullName || "-"}</TableCell>
                                <TableCell>
                                    <div className="max-w-[250px]">
                                        {(expandedOrders.has(order.id) ? order.items : order.items.slice(0, 2)).map((item, idx) => (
                                            <p key={idx} className="text-sm truncate">
                                                ΓÇó {item.itemName} x{item.quantity}
                                            </p>
                                        ))}
                                        {order.items.length > 2 && (
                                            <button
                                                onClick={() => toggleExpand(order.id)}
                                                className="text-sm text-primary hover:underline flex items-center gap-1 mt-1"
                                            >
                                                {expandedOrders.has(order.id) ? (
                                                    <>
                                                        <ChevronUp className="h-3 w-3" />
                                                        Sembunyikan
                                                    </>
                                                ) : (
                                                    <>
                                                        <ChevronDown className="h-3 w-3" />
                                                        +{order.items.length - 2} item lainnya
                                                    </>
                                                )}
                                            </button>
                                        )}
                                    </div>
                                </TableCell>
                                <TableCell>
                                    <Badge variant={statusConfig[order.status].variant}>
                                        {statusConfig[order.status].label}
                                    </Badge>
                                </TableCell>
                                <TableCell>
                                    {order.approvedByUser?.fullName || "-"}
                                </TableCell>
                                <TableCell className="text-right">
                                    <div className="flex justify-end gap-1">
                                        {order.status === "pending" && (
                                            <>
                                                <Button
                                                    variant="ghost"
                                                    size="icon"
                                                    className="text-green-600"
                                                    onClick={() => handleApprove(order.id)}
                                                >
                                                    <Check className="h-4 w-4" />
                                                </Button>
                                                <Button
                                                    variant="ghost"
                                                    size="icon"
                                                    className="text-destructive"
                                                    onClick={() => handleReject(order.id)}
                                                >
                                                    <X className="h-4 w-4" />
                                                </Button>
                                            </>
                                        )}
                                        <Button
                                            variant="ghost"
                                            size="icon"
                                            className="text-destructive hover:text-destructive"
                                            onClick={() => setDeleteId(order.id)}
                                        >
                                            <Trash2 className="h-4 w-4" />
                                        </Button>
                                    </div>
                                </TableCell>
                            </TableRow>
                        ))}
                    </TableBody>
                </Table>
            </div>

            {displayOrders.length === 0 && (
                <div className="flex flex-col items-center justify-center py-12 text-center">
                    <ShoppingCart className="h-12 w-12 text-muted-foreground/50 mb-4" />
                    <p className="text-muted-foreground">Tidak ada pesanan ditemukan</p>
                </div>
            )}

            {/* Pagination */}
            {pagination.totalPages > 1 && (
                <Pagination
                    pagination={pagination}
                    onPageChange={setPage}
                />
            )}

            {/* Delete Confirmation Dialog */}
            <AlertDialog open={!!deleteId} onOpenChange={() => setDeleteId(null)}>
                <AlertDialogContent>
                    <AlertDialogHeader>
                        <AlertDialogTitle>Hapus Pesanan?</AlertDialogTitle>
                        <AlertDialogDescription>
                            Apakah Anda yakin ingin menghapus pesanan ini? Tindakan ini tidak dapat dibatalkan.
                        </AlertDialogDescription>
                    </AlertDialogHeader>
                    <AlertDialogFooter>
                        <AlertDialogCancel disabled={isDeleting}>Batal</AlertDialogCancel>
                        <AlertDialogAction
                            onClick={handleDelete}
                            disabled={isDeleting}
                            className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
                        >
                            {isDeleting ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : null}
                            Hapus
                        </AlertDialogAction>
                    </AlertDialogFooter>
                </AlertDialogContent>
            </AlertDialog>
        </div>
    )
}

"use client"

import { useState, useEffect, useRef } from "react"
import { useRouter } from "next/navigation"
import { toast } from "sonner"
import { Card, CardContent, CardFooter } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Badge } from "@/components/ui/badge"
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select"
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "@/components/ui/dialog"
import {
    AlertDialog,
    AlertDialogAction,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle,
} from "@/components/ui/alert-dialog"
import { Label } from "@/components/ui/label"
import { Plus, Search, FlaskConical, Eye, Edit, Trash2, Loader2, Upload, X, RefreshCw } from "lucide-react"
import { StockStatus } from "@/types"
import { useFetchPaginated } from "@/hooks/use-api"
import { Pagination } from "@/components/ui/pagination"

const statusConfig: Record<StockStatus, { label: string; variant: "default" | "secondary" | "destructive" | "outline" }> = {
    available: { label: "Tersedia", variant: "default" },
    low_stock: { label: "Stok Menipis", variant: "secondary" },
    out_of_stock: { label: "Habis", variant: "outline" },
    expired: { label: "Expired", variant: "destructive" },
}

interface Reagent {
    id: string
    reagentName: string
    casNumber: string | null
    supplier: string | null
    storageLocation: string
    form: string
    currentStock: number
    minimumStockLevel: number
    status: StockStatus
    nearestExpDate?: string
    productPhoto?: string | null
}

const initialFormData = {
    reagentName: "",
    casNumber: "",
    supplier: "",
    storageLocation: "",
    form: "",
    minimumStockLevel: 0,
    productPhoto: "",
}

export default function ReagentsPage() {
    const router = useRouter()
    const [statusFilter, setStatusFilter] = useState<string>("all")
    const [sortBy, setSortBy] = useState<'fefo' | 'name' | 'stock'>("fefo")
    const [isAddDialogOpen, setIsAddDialogOpen] = useState(false)
    const [isEditDialogOpen, setIsEditDialogOpen] = useState(false)
    const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false)
    const [editingReagent, setEditingReagent] = useState<Reagent | null>(null)
    const [deletingReagent, setDeletingReagent] = useState<Reagent | null>(null)

    // Form state
    const [formData, setFormData] = useState(initialFormData)
    const [isSubmitting, setIsSubmitting] = useState(false)
    const [photoPreview, setPhotoPreview] = useState<string | null>(null)
    const [isUploading, setIsUploading] = useState(false)
    const [isDragging, setIsDragging] = useState(false)
    const fileInputRef = useRef<HTMLInputElement>(null)

    // Fetch reagents from API with pagination
    const { data: reagents, pagination, isLoading, isFetching, error, refetch, search, setSearch, setPage } = useFetchPaginated<Reagent>(
        "/api/inventory/reagents",
        { status: statusFilter, sortBy }
    )
    const displayReagents = reagents || []

    const resetForm = () => {
        setFormData(initialFormData)
        setPhotoPreview(null)
        if (fileInputRef.current) {
            fileInputRef.current.value = ""
        }
    }

    const handlePhotoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0]
        if (!file) return

        // Validate file size (max 5MB)
        const maxSize = 5 * 1024 * 1024 // 5MB in bytes
        if (file.size > maxSize) {
            toast.error("Ukuran file terlalu besar. Maksimal: 5MB")
            e.target.value = ""
            return
        }

        // Preview
        const reader = new FileReader()
        reader.onloadend = () => {
            setPhotoPreview(reader.result as string)
        }
        reader.readAsDataURL(file)

        // Upload to Supabase
        setIsUploading(true)
        try {
            const formDataUpload = new FormData()
            formDataUpload.append("file", file)
            formDataUpload.append("bucket", "images")

            const response = await fetch("/api/upload", {
                method: "POST",
                body: formDataUpload,
            })

            if (!response.ok) {
                const errorData = await response.json().catch(() => ({}))
                throw new Error(errorData.error || "Upload gagal")
            }
            const { publicUrl } = await response.json()
            setFormData((prev) => ({ ...prev, productPhoto: publicUrl }))
            toast.success("Foto berhasil diupload")
        } catch (err) {
            console.error("Upload error:", err)
            toast.error(err instanceof Error ? err.message : "Gagal mengupload foto")
            setPhotoPreview(null)
        } finally {
            setIsUploading(false)
        }
    }

    const clearPhoto = () => {
        setPhotoPreview(null)
        setFormData((prev) => ({ ...prev, productPhoto: "" }))
        if (fileInputRef.current) {
            fileInputRef.current.value = ""
        }
    }

    // Handle drag-drop file upload
    const handleDrop = async (e: React.DragEvent<HTMLDivElement>) => {
        e.preventDefault()
        setIsDragging(false)

        const file = e.dataTransfer.files?.[0]
        if (!file) return

        // Check if it's an image
        if (!file.type.startsWith('image/')) {
            toast.error("File harus berupa gambar")
            return
        }

        // Validate file size (max 5MB)
        const maxSize = 5 * 1024 * 1024
        if (file.size > maxSize) {
            toast.error("Ukuran file terlalu besar. Maksimal: 5MB")
            return
        }

        // Preview
        const reader = new FileReader()
        reader.onloadend = () => {
            setPhotoPreview(reader.result as string)
        }
        reader.readAsDataURL(file)

        // Upload to Supabase
        setIsUploading(true)
        try {
            const formDataUpload = new FormData()
            formDataUpload.append("file", file)
            formDataUpload.append("bucket", "images")

            const response = await fetch("/api/upload", {
                method: "POST",
                body: formDataUpload,
            })

            if (!response.ok) {
                const errorData = await response.json().catch(() => ({}))
                throw new Error(errorData.error || "Upload gagal")
            }
            const { publicUrl } = await response.json()
            setFormData((prev) => ({ ...prev, productPhoto: publicUrl }))
            toast.success("Foto berhasil diupload")
        } catch (err) {
            console.error("Upload error:", err)
            toast.error(err instanceof Error ? err.message : "Gagal mengupload foto")
            setPhotoPreview(null)
        } finally {
            setIsUploading(false)
        }
    }

    const handleDragOver = (e: React.DragEvent<HTMLDivElement>) => {
        e.preventDefault()
        setIsDragging(true)
    }

    const handleDragLeave = (e: React.DragEvent<HTMLDivElement>) => {
        e.preventDefault()
        setIsDragging(false)
    }

    const handleAddReagent = async () => {
        if (!formData.reagentName || !formData.storageLocation || !formData.form) {
            return
        }

        setIsSubmitting(true)
        try {
            const response = await fetch("/api/inventory/reagents", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify(formData),
            })
            if (!response.ok) throw new Error("Gagal menambah reagen")
            setIsAddDialogOpen(false)
            resetForm()
            refetch()
        } catch (err) {
            console.error(err)
        } finally {
            setIsSubmitting(false)
        }
    }

    const handleEdit = (e: React.MouseEvent, reagent: Reagent) => {
        e.stopPropagation()
        setEditingReagent(reagent)
        setFormData({
            reagentName: reagent.reagentName,
            casNumber: reagent.casNumber || "",
            supplier: reagent.supplier || "",
            storageLocation: reagent.storageLocation,
            form: reagent.form,
            minimumStockLevel: reagent.minimumStockLevel,
            productPhoto: reagent.productPhoto || "",
        })
        setPhotoPreview(reagent.productPhoto || null)
        setIsEditDialogOpen(true)
    }

    const handleUpdate = async () => {
        if (!editingReagent || !formData.reagentName || !formData.storageLocation || !formData.form) {
            return
        }

        setIsSubmitting(true)
        try {
            const response = await fetch(`/api/inventory/reagents/${editingReagent.id}`, {
                method: "PUT",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify(formData),
            })
            if (!response.ok) throw new Error("Gagal mengupdate reagen")
            setIsEditDialogOpen(false)
            setEditingReagent(null)
            resetForm()
            refetch()
        } catch (err) {
            console.error(err)
        } finally {
            setIsSubmitting(false)
        }
    }

    const handleDeleteClick = (e: React.MouseEvent, reagent: Reagent) => {
        e.stopPropagation()
        setDeletingReagent(reagent)
        setIsDeleteDialogOpen(true)
    }

    const handleDelete = async () => {
        if (!deletingReagent) return

        setIsSubmitting(true)
        try {
            const response = await fetch(`/api/inventory/reagents/${deletingReagent.id}`, {
                method: "DELETE",
            })
            if (!response.ok) throw new Error("Gagal menghapus reagen")
            setIsDeleteDialogOpen(false)
            setDeletingReagent(null)
            refetch()
        } catch (err) {
            console.error(err)
        } finally {
            setIsSubmitting(false)
        }
    }

    // Form fields JSX - inlined to prevent focus loss on re-render
    const formFieldsContent = (
        <div className="grid gap-4 py-4">
            <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                    <Label htmlFor="name">Nama Reagen *</Label>
                    <Input
                        id="name"
                        placeholder="Contoh: Methanol HPLC Grade"
                        value={formData.reagentName}
                        onChange={(e) => setFormData({ ...formData, reagentName: e.target.value })}
                    />
                </div>
                <div className="space-y-2">
                    <Label htmlFor="cas">CAS Number</Label>
                    <Input
                        id="cas"
                        placeholder="Contoh: 67-56-1"
                        value={formData.casNumber}
                        onChange={(e) => setFormData({ ...formData, casNumber: e.target.value })}
                    />
                </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                    <Label htmlFor="supplier">Supplier</Label>
                    <Input
                        id="supplier"
                        placeholder="Contoh: Merck"
                        value={formData.supplier}
                        onChange={(e) => setFormData({ ...formData, supplier: e.target.value })}
                    />
                </div>
                <div className="space-y-2">
                    <Label htmlFor="location">Lokasi Penyimpanan *</Label>
                    <Select
                        value={formData.storageLocation}
                        onValueChange={(value) => setFormData({ ...formData, storageLocation: value })}
                    >
                        <SelectTrigger>
                            <SelectValue placeholder="Pilih lokasi" />
                        </SelectTrigger>
                        <SelectContent>
                            <SelectItem value="TC 1">TC 1</SelectItem>
                            <SelectItem value="TC 2">TC 2</SelectItem>
                            <SelectItem value="TC 3">TC 3</SelectItem>
                        </SelectContent>
                    </Select>
                </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                    <Label htmlFor="form">Bentuk *</Label>
                    <Select
                        value={formData.form}
                        onValueChange={(value) => setFormData({ ...formData, form: value })}
                    >
                        <SelectTrigger>
                            <SelectValue placeholder="Pilih bentuk" />
                        </SelectTrigger>
                        <SelectContent>
                            <SelectItem value="solid">Solid</SelectItem>
                            <SelectItem value="liquid">Liquid</SelectItem>
                            <SelectItem value="gas">Gas</SelectItem>
                        </SelectContent>
                    </Select>
                </div>
                <div className="space-y-2">
                    <Label htmlFor="minStock">Minimum Stok</Label>
                    <Input
                        id="minStock"
                        type="number"
                        placeholder="Contoh: 3"
                        value={formData.minimumStockLevel}
                        onChange={(e) => setFormData({ ...formData, minimumStockLevel: parseInt(e.target.value) || 0 })}
                    />
                </div>
            </div>
            {/* Photo Upload */}
            <div className="space-y-2">
                <Label>Foto Produk</Label>
                <div className="flex items-center gap-4">
                    {photoPreview ? (
                        <div className="relative w-24 h-24 rounded-lg overflow-hidden border">
                            <img src={photoPreview} alt="Preview" className="w-full h-full object-cover" />
                            <Button
                                type="button"
                                variant="destructive"
                                size="icon"
                                className="absolute top-1 right-1 h-6 w-6"
                                onClick={clearPhoto}
                            >
                                <X className="h-3 w-3" />
                            </Button>
                        </div>
                    ) : (
                        <div
                            className={`w-24 h-24 rounded-lg border-2 border-dashed flex items-center justify-center bg-muted cursor-pointer transition-colors ${isDragging ? 'border-primary bg-primary/10' : ''}`}
                            onDrop={handleDrop}
                            onDragOver={handleDragOver}
                            onDragLeave={handleDragLeave}
                            onClick={() => fileInputRef.current?.click()}
                        >
                            <FlaskConical className="h-8 w-8 text-muted-foreground/50" />
                        </div>
                    )}
                    <div>
                        <Input
                            ref={fileInputRef}
                            id="photo"
                            type="file"
                            accept="image/*"
                            className="hidden"
                            onChange={handlePhotoUpload}
                        />
                        <Button
                            type="button"
                            variant="outline"
                            onClick={() => fileInputRef.current?.click()}
                            disabled={isUploading}
                        >
                            {isUploading ? (
                                <>
                                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                                    Uploading...
                                </>
                            ) : (
                                <>
                                    <Upload className="mr-2 h-4 w-4" />
                                    Upload Foto
                                </>
                            )}
                        </Button>
                    </div>
                </div>
            </div>
        </div>
    )

    if (isLoading) {
        return (
            <div className="flex items-center justify-center py-12">
                <Loader2 className="h-8 w-8 animate-spin text-primary" />
            </div>
        )
    }

    if (error) {
        return (
            <div className="flex flex-col items-center justify-center py-12 text-center">
                <p className="text-destructive mb-4">{error}</p>
                <Button onClick={refetch}>Coba Lagi</Button>
            </div>
        )
    }

    return (
        <div className="space-y-6">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight">Katalog Reagen</h1>
                    <p className="text-muted-foreground">
                        Kelola daftar reagen dan bahan kimia laboratorium
                    </p>
                </div>
                <Dialog open={isAddDialogOpen} onOpenChange={(open) => { setIsAddDialogOpen(open); if (!open) resetForm() }}>
                    <DialogTrigger asChild>
                        <Button>
                            <Plus className="mr-2 h-4 w-4" />
                            Tambah Baru
                        </Button>
                    </DialogTrigger>
                    <DialogContent className="max-w-2xl">
                        <DialogHeader>
                            <DialogTitle>Tambah Reagen Baru</DialogTitle>
                            <DialogDescription>
                                Masukkan informasi reagen yang akan ditambahkan ke katalog
                            </DialogDescription>
                        </DialogHeader>
                        {formFieldsContent}
                        <DialogFooter>
                            <Button variant="outline" onClick={() => { setIsAddDialogOpen(false); resetForm() }}>
                                Batal
                            </Button>
                            <Button onClick={handleAddReagent} disabled={isSubmitting || isUploading}>
                                {isSubmitting ? (
                                    <>
                                        <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                                        Menyimpan...
                                    </>
                                ) : (
                                    "Simpan"
                                )}
                            </Button>
                        </DialogFooter>
                    </DialogContent>
                </Dialog>
            </div>

            {/* Edit Dialog */}
            <Dialog open={isEditDialogOpen} onOpenChange={(open) => { setIsEditDialogOpen(open); if (!open) { resetForm(); setEditingReagent(null) } }}>
                <DialogContent className="max-w-2xl">
                    <DialogHeader>
                        <DialogTitle>Edit Reagen</DialogTitle>
                        <DialogDescription>
                            Ubah informasi reagen
                        </DialogDescription>
                    </DialogHeader>
                    {formFieldsContent}
                    <DialogFooter>
                        <Button variant="outline" onClick={() => { setIsEditDialogOpen(false); resetForm(); setEditingReagent(null) }}>
                            Batal
                        </Button>
                        <Button onClick={handleUpdate} disabled={isSubmitting || isUploading}>
                            {isSubmitting ? (
                                <>
                                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                                    Menyimpan...
                                </>
                            ) : (
                                "Simpan Perubahan"
                            )}
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>

            {/* Delete Confirmation Dialog */}
            <AlertDialog open={isDeleteDialogOpen} onOpenChange={setIsDeleteDialogOpen}>
                <AlertDialogContent>
                    <AlertDialogHeader>
                        <AlertDialogTitle>Hapus Reagen?</AlertDialogTitle>
                        <AlertDialogDescription>
                            Tindakan ini tidak dapat dibatalkan. Reagen &quot;{deletingReagent?.reagentName}&quot; akan dihapus secara permanen.
                        </AlertDialogDescription>
                    </AlertDialogHeader>
                    <AlertDialogFooter>
                        <AlertDialogCancel onClick={() => setDeletingReagent(null)}>Batal</AlertDialogCancel>
                        <AlertDialogAction
                            onClick={handleDelete}
                            className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
                            disabled={isSubmitting}
                        >
                            {isSubmitting ? (
                                <>
                                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                                    Menghapus...
                                </>
                            ) : (
                                "Hapus"
                            )}
                        </AlertDialogAction>
                    </AlertDialogFooter>
                </AlertDialogContent>
            </AlertDialog>

            {/* Filters */}
            <div className="flex gap-4">
                <div className="relative flex-1 max-w-sm">
                    <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
                    <Input
                        placeholder="Cari reagen atau CAS number..."
                        value={search}
                        onChange={(e) => setSearch(e.target.value)}
                        className="pl-9"
                    />
                </div>
                <Select value={statusFilter} onValueChange={setStatusFilter}>
                    <SelectTrigger className="w-[180px]">
                        <SelectValue placeholder="Filter Status" />
                    </SelectTrigger>
                    <SelectContent>
                        <SelectItem value="all">Semua Status</SelectItem>
                        <SelectItem value="available">Tersedia</SelectItem>
                        <SelectItem value="low_stock">Stok Menipis</SelectItem>
                        <SelectItem value="out_of_stock">Habis</SelectItem>
                        <SelectItem value="expired">Expired</SelectItem>
                    </SelectContent>
                </Select>
                <Select value={sortBy} onValueChange={(val) => setSortBy(val as 'fefo' | 'name' | 'stock')}>
                    <SelectTrigger className="w-[180px]">
                        <SelectValue placeholder="Urutkan" />
                    </SelectTrigger>
                    <SelectContent>
                        <SelectItem value="fefo">FEFO (Exp Terdekat)</SelectItem>
                        <SelectItem value="name">Nama A-Z</SelectItem>
                        <SelectItem value="stock">Stok Terendah</SelectItem>
                    </SelectContent>
                </Select>
            </div>

            {/* Cards Grid */}
            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
                {displayReagents.map((reagent) => (
                    <Card
                        key={reagent.id}
                        className="overflow-hidden cursor-pointer transition-all duration-300 hover:shadow-lg hover:border-primary/50 hover:-translate-y-1"
                        onClick={() => router.push(`/inventory/reagents/${reagent.id}`)}
                    >
                        {/* Image */}
                        <div className="aspect-square bg-muted flex items-center justify-center transition-colors hover:bg-muted/80 overflow-hidden">
                            {reagent.productPhoto ? (
                                <img src={reagent.productPhoto} alt={reagent.reagentName} className="w-full h-full object-cover" />
                            ) : (
                                <FlaskConical className="h-16 w-16 text-muted-foreground/50" />
                            )}
                        </div>
                        <CardContent className="p-4">
                            <h3 className="font-semibold truncate">{reagent.reagentName}</h3>
                            <p className="text-sm text-muted-foreground">CAS: {reagent.casNumber || "-"}</p>
                            <div className="mt-2 flex items-center justify-between">
                                <Badge variant={statusConfig[reagent.status]?.variant || "default"}>
                                    {statusConfig[reagent.status]?.label || reagent.status}
                                </Badge>
                                <span className="text-sm">Stok: {reagent.currentStock ?? 0}</span>
                            </div>
                            {reagent.nearestExpDate && (
                                <p className="mt-2 text-xs text-muted-foreground">
                                    Exp: {new Date(reagent.nearestExpDate).toLocaleDateString("id-ID")}
                                </p>
                            )}
                        </CardContent>
                        <CardFooter className="border-t p-2 flex justify-end gap-1">
                            <Button variant="ghost" size="icon" onClick={(e) => { e.stopPropagation(); router.push(`/inventory/reagents/${reagent.id}`) }}>
                                <Eye className="h-4 w-4" />
                            </Button>
                            <Button variant="ghost" size="icon" onClick={(e) => handleEdit(e, reagent)}>
                                <Edit className="h-4 w-4" />
                            </Button>
                            <Button variant="ghost" size="icon" className="text-destructive" onClick={(e) => handleDeleteClick(e, reagent)}>
                                <Trash2 className="h-4 w-4" />
                            </Button>
                        </CardFooter>
                    </Card>
                ))}
            </div>

            {displayReagents.length === 0 && (
                <div className="flex flex-col items-center justify-center py-12 text-center">
                    <FlaskConical className="h-12 w-12 text-muted-foreground/50 mb-4" />
                    <p className="text-muted-foreground">Tidak ada reagen ditemukan</p>
                </div>
            )}

            {/* Pagination */}
            {pagination.totalPages > 1 && (
                <Pagination
                    pagination={pagination}
                    onPageChange={setPage}
                />
            )}
        </div>
    )
}

"use client"

import { useState, useRef } from "react"
import { useRouter } from "next/navigation"
import { toast } from "sonner"
import { Card, CardContent, CardFooter } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Badge } from "@/components/ui/badge"
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select"
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "@/components/ui/dialog"
import {
    AlertDialog,
    AlertDialogAction,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle,
} from "@/components/ui/alert-dialog"
import { Label } from "@/components/ui/label"
import { Plus, Search, TestTube2, Eye, Edit, Trash2, Loader2, Upload, X } from "lucide-react"
import { StockStatus } from "@/types"
import { useFetchPaginated } from "@/hooks/use-api"
import { Pagination } from "@/components/ui/pagination"

const statusConfig: Record<StockStatus, { label: string; variant: "default" | "secondary" | "destructive" | "outline" }> = {
    available: { label: "Tersedia", variant: "default" },
    low_stock: { label: "Stok Menipis", variant: "secondary" },
    out_of_stock: { label: "Habis", variant: "outline" },
    expired: { label: "Expired", variant: "destructive" },
}

interface Sample {
    id: string
    sampleName: string
    matrix: string | null
    storageLocation: string
    form: string
    currentStock: number
    minimumStockLevel: number
    status: StockStatus
    nearestExpDate?: string
    photo?: string | null
}

const initialFormData = {
    sampleName: "",
    matrix: "",
    storageLocation: "",
    form: "",
    minimumStockLevel: 0,
    photo: "",
}

export default function SamplesPage() {
    const router = useRouter()
    const [statusFilter, setStatusFilter] = useState<string>("all")
    const [sortBy, setSortBy] = useState<'fefo' | 'name' | 'stock'>("fefo")
    const [isAddDialogOpen, setIsAddDialogOpen] = useState(false)
    const [isEditDialogOpen, setIsEditDialogOpen] = useState(false)
    const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false)
    const [editingSample, setEditingSample] = useState<Sample | null>(null)
    const [deletingSample, setDeletingSample] = useState<Sample | null>(null)

    // Form state
    const [formData, setFormData] = useState(initialFormData)
    const [isSubmitting, setIsSubmitting] = useState(false)
    const [photoPreview, setPhotoPreview] = useState<string | null>(null)
    const [isUploading, setIsUploading] = useState(false)
    const fileInputRef = useRef<HTMLInputElement>(null)

    // Fetch samples from API with pagination
    const { data: samples, pagination, isLoading, isFetching, error, refetch, search, setSearch, setPage } = useFetchPaginated<Sample>(
        "/api/inventory/samples",
        { status: statusFilter, sortBy }
    )
    const displaySamples = samples || []

    const resetForm = () => {
        setFormData(initialFormData)
        setPhotoPreview(null)
        if (fileInputRef.current) {
            fileInputRef.current.value = ""
        }
    }

    const handlePhotoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0]
        if (!file) return

        // Validate file size (max 5MB)
        const maxSize = 5 * 1024 * 1024 // 5MB in bytes
        if (file.size > maxSize) {
            toast.error("Ukuran file terlalu besar. Maksimal: 5MB")
            e.target.value = ""
            return
        }

        // Preview
        const reader = new FileReader()
        reader.onloadend = () => {
            setPhotoPreview(reader.result as string)
        }
        reader.readAsDataURL(file)

        // Upload to Supabase
        setIsUploading(true)
        try {
            const formDataUpload = new FormData()
            formDataUpload.append("file", file)
            formDataUpload.append("bucket", "images")

            const response = await fetch("/api/upload", {
                method: "POST",
                body: formDataUpload,
            })

            if (!response.ok) {
                const errorData = await response.json().catch(() => ({}))
                throw new Error(errorData.error || "Upload gagal")
            }
            const { publicUrl } = await response.json()
            setFormData((prev) => ({ ...prev, photo: publicUrl }))
            toast.success("Foto berhasil diupload")
        } catch (err) {
            console.error("Upload error:", err)
            toast.error(err instanceof Error ? err.message : "Gagal mengupload foto")
            setPhotoPreview(null)
        } finally {
            setIsUploading(false)
        }
    }

    const clearPhoto = () => {
        setPhotoPreview(null)
        setFormData((prev) => ({ ...prev, photo: "" }))
        if (fileInputRef.current) {
            fileInputRef.current.value = ""
        }
    }

    const handleAddSample = async () => {
        if (!formData.sampleName || !formData.storageLocation || !formData.form) {
            return
        }

        setIsSubmitting(true)
        try {
            const response = await fetch("/api/inventory/samples", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify(formData),
            })
            if (!response.ok) throw new Error("Gagal menambah sample")
            setIsAddDialogOpen(false)
            resetForm()
            refetch()
        } catch (err) {
            console.error(err)
        } finally {
            setIsSubmitting(false)
        }
    }

    const handleEdit = (e: React.MouseEvent, sample: Sample) => {
        e.stopPropagation()
        setEditingSample(sample)
        setFormData({
            sampleName: sample.sampleName,
            matrix: sample.matrix || "",
            storageLocation: sample.storageLocation,
            form: sample.form,
            minimumStockLevel: sample.minimumStockLevel,
            photo: sample.photo || "",
        })
        setPhotoPreview(sample.photo || null)
        setIsEditDialogOpen(true)
    }

    const handleUpdate = async () => {
        if (!editingSample || !formData.sampleName || !formData.storageLocation || !formData.form) {
            return
        }

        setIsSubmitting(true)
        try {
            const response = await fetch(`/api/inventory/samples/${editingSample.id}`, {
                method: "PUT",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify(formData),
            })
            if (!response.ok) throw new Error("Gagal mengupdate sample")
            setIsEditDialogOpen(false)
            setEditingSample(null)
            resetForm()
            refetch()
        } catch (err) {
            console.error(err)
        } finally {
            setIsSubmitting(false)
        }
    }

    const handleDeleteClick = (e: React.MouseEvent, sample: Sample) => {
        e.stopPropagation()
        setDeletingSample(sample)
        setIsDeleteDialogOpen(true)
    }

    const handleDelete = async () => {
        if (!deletingSample) return

        setIsSubmitting(true)
        try {
            const response = await fetch(`/api/inventory/samples/${deletingSample.id}`, {
                method: "DELETE",
            })
            if (!response.ok) throw new Error("Gagal menghapus sample")
            setIsDeleteDialogOpen(false)
            setDeletingSample(null)
            refetch()
        } catch (err) {
            console.error(err)
        } finally {
            setIsSubmitting(false)
        }
    }

    // Form fields JSX
    const formFieldsContent = (
        <div className="grid gap-4 py-4">
            <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                    <Label htmlFor="name">Nama Sample *</Label>
                    <Input
                        id="name"
                        placeholder="Contoh: Anggur Putih Botol"
                        value={formData.sampleName}
                        onChange={(e) => setFormData({ ...formData, sampleName: e.target.value })}
                    />
                </div>
                <div className="space-y-2">
                    <Label htmlFor="matrix">Matrix</Label>
                    <Input
                        id="matrix"
                        placeholder="Contoh: Wine, Water, Oil"
                        value={formData.matrix}
                        onChange={(e) => setFormData({ ...formData, matrix: e.target.value })}
                    />
                </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                    <Label htmlFor="location">Lokasi Penyimpanan *</Label>
                    <Select
                        value={formData.storageLocation}
                        onValueChange={(value) => setFormData({ ...formData, storageLocation: value })}
                    >
                        <SelectTrigger>
                            <SelectValue placeholder="Pilih lokasi" />
                        </SelectTrigger>
                        <SelectContent>
                            <SelectItem value="TC 1">TC 1</SelectItem>
                            <SelectItem value="TC 2">TC 2</SelectItem>
                            <SelectItem value="TC 3">TC 3</SelectItem>
                        </SelectContent>
                    </Select>
                </div>
                <div className="space-y-2">
                    <Label htmlFor="form">Bentuk *</Label>
                    <Select
                        value={formData.form}
                        onValueChange={(value) => setFormData({ ...formData, form: value })}
                    >
                        <SelectTrigger>
                            <SelectValue placeholder="Pilih bentuk" />
                        </SelectTrigger>
                        <SelectContent>
                            <SelectItem value="solid">Solid</SelectItem>
                            <SelectItem value="liquid">Liquid</SelectItem>
                            <SelectItem value="gas">Gas</SelectItem>
                        </SelectContent>
                    </Select>
                </div>
            </div>
            <div className="space-y-2">
                <Label htmlFor="minStock">Minimum Stok</Label>
                <Input
                    id="minStock"
                    type="number"
                    placeholder="Contoh: 3"
                    value={formData.minimumStockLevel}
                    onChange={(e) => setFormData({ ...formData, minimumStockLevel: parseInt(e.target.value) || 0 })}
                />
            </div>
            {/* Photo Upload */}
            <div className="space-y-2">
                <Label>Foto Sample</Label>
                <div className="flex items-center gap-4">
                    {photoPreview ? (
                        <div className="relative w-24 h-24 rounded-lg overflow-hidden border">
                            <img src={photoPreview} alt="Preview" className="w-full h-full object-cover" />
                            <Button
                                type="button"
                                variant="destructive"
                                size="icon"
                                className="absolute top-1 right-1 h-6 w-6"
                                onClick={clearPhoto}
                            >
                                <X className="h-3 w-3" />
                            </Button>
                        </div>
                    ) : (
                        <div className="w-24 h-24 rounded-lg border-2 border-dashed flex items-center justify-center bg-muted">
                            <TestTube2 className="h-8 w-8 text-muted-foreground/50" />
                        </div>
                    )}
                    <div>
                        <Input
                            ref={fileInputRef}
                            id="photo"
                            type="file"
                            accept="image/*"
                            className="hidden"
                            onChange={handlePhotoUpload}
                        />
                        <Button
                            type="button"
                            variant="outline"
                            onClick={() => fileInputRef.current?.click()}
                            disabled={isUploading}
                        >
                            {isUploading ? (
                                <>
                                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                                    Uploading...
                                </>
                            ) : (
                                <>
                                    <Upload className="mr-2 h-4 w-4" />
                                    Upload Foto
                                </>
                            )}
                        </Button>
                    </div>
                </div>
            </div>
        </div>
    )

    if (isLoading) {
        return (
            <div className="flex items-center justify-center py-12">
                <Loader2 className="h-8 w-8 animate-spin text-primary" />
            </div>
        )
    }

    if (error) {
        return (
            <div className="flex flex-col items-center justify-center py-12 text-center">
                <p className="text-destructive mb-4">{error}</p>
                <Button onClick={refetch}>Coba Lagi</Button>
            </div>
        )
    }

    return (
        <div className="space-y-6">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight">Katalog Sample</h1>
                    <p className="text-muted-foreground">
                        Kelola daftar QC sample untuk training dan testing
                    </p>
                </div>
                <Dialog open={isAddDialogOpen} onOpenChange={(open) => { setIsAddDialogOpen(open); if (!open) resetForm() }}>
                    <DialogTrigger asChild>
                        <Button>
                            <Plus className="mr-2 h-4 w-4" />
                            Tambah Baru
                        </Button>
                    </DialogTrigger>
                    <DialogContent className="max-w-2xl">
                        <DialogHeader>
                            <DialogTitle>Tambah Sample Baru</DialogTitle>
                            <DialogDescription>
                                Masukkan informasi sample yang akan ditambahkan ke katalog
                            </DialogDescription>
                        </DialogHeader>
                        {formFieldsContent}
                        <DialogFooter>
                            <Button variant="outline" onClick={() => { setIsAddDialogOpen(false); resetForm() }}>
                                Batal
                            </Button>
                            <Button onClick={handleAddSample} disabled={isSubmitting || isUploading}>
                                {isSubmitting ? (
                                    <>
                                        <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                                        Menyimpan...
                                    </>
                                ) : (
                                    "Simpan"
                                )}
                            </Button>
                        </DialogFooter>
                    </DialogContent>
                </Dialog>
            </div>

            {/* Edit Dialog */}
            <Dialog open={isEditDialogOpen} onOpenChange={(open) => { setIsEditDialogOpen(open); if (!open) { resetForm(); setEditingSample(null) } }}>
                <DialogContent className="max-w-2xl">
                    <DialogHeader>
                        <DialogTitle>Edit Sample</DialogTitle>
                        <DialogDescription>
                            Ubah informasi sample
                        </DialogDescription>
                    </DialogHeader>
                    {formFieldsContent}
                    <DialogFooter>
                        <Button variant="outline" onClick={() => { setIsEditDialogOpen(false); resetForm(); setEditingSample(null) }}>
                            Batal
                        </Button>
                        <Button onClick={handleUpdate} disabled={isSubmitting || isUploading}>
                            {isSubmitting ? (
                                <>
                                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                                    Menyimpan...
                                </>
                            ) : (
                                "Simpan Perubahan"
                            )}
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>

            {/* Delete Confirmation Dialog */}
            <AlertDialog open={isDeleteDialogOpen} onOpenChange={setIsDeleteDialogOpen}>
                <AlertDialogContent>
                    <AlertDialogHeader>
                        <AlertDialogTitle>Hapus Sample?</AlertDialogTitle>
                        <AlertDialogDescription>
                            Tindakan ini tidak dapat dibatalkan. Sample &quot;{deletingSample?.sampleName}&quot; akan dihapus secara permanen.
                        </AlertDialogDescription>
                    </AlertDialogHeader>
                    <AlertDialogFooter>
                        <AlertDialogCancel onClick={() => setDeletingSample(null)}>Batal</AlertDialogCancel>
                        <AlertDialogAction
                            onClick={handleDelete}
                            className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
                            disabled={isSubmitting}
                        >
                            {isSubmitting ? (
                                <>
                                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                                    Menghapus...
                                </>
                            ) : (
                                "Hapus"
                            )}
                        </AlertDialogAction>
                    </AlertDialogFooter>
                </AlertDialogContent>
            </AlertDialog>

            {/* Filters */}
            <div className="flex gap-4">
                <div className="relative flex-1 max-w-sm">
                    <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
                    <Input
                        placeholder="Cari sample atau matrix..."
                        value={search}
                        onChange={(e) => setSearch(e.target.value)}
                        className="pl-9"
                    />
                </div>
                <Select value={statusFilter} onValueChange={setStatusFilter}>
                    <SelectTrigger className="w-[180px]">
                        <SelectValue placeholder="Filter Status" />
                    </SelectTrigger>
                    <SelectContent>
                        <SelectItem value="all">Semua Status</SelectItem>
                        <SelectItem value="available">Tersedia</SelectItem>
                        <SelectItem value="low_stock">Stok Menipis</SelectItem>
                        <SelectItem value="out_of_stock">Habis</SelectItem>
                        <SelectItem value="expired">Expired</SelectItem>
                    </SelectContent>
                </Select>
                <Select value={sortBy} onValueChange={(val) => setSortBy(val as 'fefo' | 'name' | 'stock')}>
                    <SelectTrigger className="w-[180px]">
                        <SelectValue placeholder="Urutkan" />
                    </SelectTrigger>
                    <SelectContent>
                        <SelectItem value="fefo">FEFO (Exp Terdekat)</SelectItem>
                        <SelectItem value="name">Nama A-Z</SelectItem>
                        <SelectItem value="stock">Stok Terendah</SelectItem>
                    </SelectContent>
                </Select>
            </div>

            {/* Cards Grid */}
            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
                {displaySamples.map((sample) => (
                    <Card
                        key={sample.id}
                        className="overflow-hidden cursor-pointer transition-all duration-300 hover:shadow-lg hover:border-primary/50 hover:-translate-y-1"
                        onClick={() => router.push(`/inventory/samples/${sample.id}`)}
                    >
                        {/* Image */}
                        <div className="aspect-square bg-muted flex items-center justify-center transition-colors hover:bg-muted/80 overflow-hidden">
                            {sample.photo ? (
                                <img src={sample.photo} alt={sample.sampleName} className="w-full h-full object-cover" />
                            ) : (
                                <TestTube2 className="h-16 w-16 text-muted-foreground/50" />
                            )}
                        </div>
                        <CardContent className="p-4">
                            <h3 className="font-semibold truncate">{sample.sampleName}</h3>
                            <p className="text-sm text-muted-foreground">Matrix: {sample.matrix || "-"}</p>
                            <div className="mt-2 flex items-center justify-between">
                                <Badge variant={statusConfig[sample.status]?.variant || "default"}>
                                    {statusConfig[sample.status]?.label || sample.status}
                                </Badge>
                                <span className="text-sm">Stok: {sample.currentStock ?? 0}</span>
                            </div>
                            {sample.nearestExpDate && (
                                <p className="mt-2 text-xs text-muted-foreground">
                                    Exp: {new Date(sample.nearestExpDate).toLocaleDateString("id-ID")}
                                </p>
                            )}
                        </CardContent>
                        <CardFooter className="border-t p-2 flex justify-end gap-1">
                            <Button variant="ghost" size="icon" onClick={(e) => { e.stopPropagation(); router.push(`/inventory/samples/${sample.id}`) }}>
                                <Eye className="h-4 w-4" />
                            </Button>
                            <Button variant="ghost" size="icon" onClick={(e) => handleEdit(e, sample)}>
                                <Edit className="h-4 w-4" />
                            </Button>
                            <Button variant="ghost" size="icon" className="text-destructive" onClick={(e) => handleDeleteClick(e, sample)}>
                                <Trash2 className="h-4 w-4" />
                            </Button>
                        </CardFooter>
                    </Card>
                ))}
            </div>

            {displaySamples.length === 0 && (
                <div className="flex flex-col items-center justify-center py-12 text-center">
                    <TestTube2 className="h-12 w-12 text-muted-foreground/50 mb-4" />
                    <p className="text-muted-foreground">Tidak ada sample ditemukan</p>
                </div>
            )}

            {/* Pagination */}
            {pagination.totalPages > 1 && (
                <Pagination
                    pagination={pagination}
                    onPageChange={setPage}
                />
            )}
        </div>
    )
}

"use client"

import { useState, useRef } from "react"
import { useRouter } from "next/navigation"
import { toast } from "sonner"
import { Card, CardContent, CardFooter } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Badge } from "@/components/ui/badge"
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select"
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "@/components/ui/dialog"
import {
    AlertDialog,
    AlertDialogAction,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle,
} from "@/components/ui/alert-dialog"
import { Label } from "@/components/ui/label"
import { Plus, Search, TestTubes, Eye, Edit, Trash2, Loader2, RefreshCw, Upload, X } from "lucide-react"
import { StockStatus } from "@/types"
import { useFetchPaginated, useMutation } from "@/hooks/use-api"
import { Pagination } from "@/components/ui/pagination"

interface Standard {
    id: string
    standardName: string
    casNumber: string | null
    chemicalFormula: string | null
    supplier: string | null
    sizeValue: string | null
    sizeUnit: string | null
    form: "solid" | "liquid" | "gas"
    storageLocation: "TC 1" | "TC 2" | "TC 3"
    currentStock: number
    minimumStockLevel: number
    status: StockStatus
    nearestExpDate: string | null
    productPhoto?: string | null
}

const statusConfig: Record<StockStatus, { label: string; variant: "default" | "secondary" | "destructive" | "outline" }> = {
    available: { label: "Tersedia", variant: "default" },
    low_stock: { label: "Stok Menipis", variant: "secondary" },
    out_of_stock: { label: "Habis", variant: "outline" },
    expired: { label: "Expired", variant: "destructive" },
}

const initialFormData = {
    standardName: "",
    casNumber: "",
    chemicalFormula: "",
    supplier: "",
    sizeValue: "",
    sizeUnit: "ml",
    form: "liquid" as "solid" | "liquid" | "gas",
    storageLocation: "TC 1" as "TC 1" | "TC 2" | "TC 3",
    minimumStockLevel: 2,
    productPhoto: "",
}

export default function StandardsPage() {
    const router = useRouter()
    const [statusFilter, setStatusFilter] = useState<string>("all")
    const [sortBy, setSortBy] = useState<'fefo' | 'name' | 'stock'>("fefo")
    const [isAddDialogOpen, setIsAddDialogOpen] = useState(false)
    const [isEditDialogOpen, setIsEditDialogOpen] = useState(false)
    const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false)
    const [editingStandard, setEditingStandard] = useState<Standard | null>(null)
    const [deletingStandard, setDeletingStandard] = useState<Standard | null>(null)

    // Form state
    const [formData, setFormData] = useState(initialFormData)
    const [photoPreview, setPhotoPreview] = useState<string | null>(null)
    const [isUploading, setIsUploading] = useState(false)
    const fileInputRef = useRef<HTMLInputElement>(null)

    // Fetch standards from API with pagination
    const { data: standards, pagination, isLoading, isFetching, error, refetch, search, setSearch, setPage } = useFetchPaginated<Standard>(
        "/api/inventory/standards",
        { status: statusFilter, sortBy }
    )
    const displayStandards = standards || []

    // Create mutation
    const createMutation = useMutation<Standard, typeof formData>(
        "/api/inventory/standards",
        "POST",
        {
            onSuccess: () => {
                setIsAddDialogOpen(false)
                resetForm()
                refetch()
            }
        }
    )

    // Delete mutation
    const deleteMutation = useMutation<void, void>(
        "/api/inventory/standards",
        "DELETE",
        {
            onSuccess: () => {
                refetch()
            }
        }
    )

    const resetForm = () => {
        setFormData(initialFormData)
        setPhotoPreview(null)
        if (fileInputRef.current) {
            fileInputRef.current.value = ""
        }
    }

    const handlePhotoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0]
        if (!file) return

        // Validate file size (max 5MB)
        const maxSize = 5 * 1024 * 1024 // 5MB in bytes
        if (file.size > maxSize) {
            toast.error("Ukuran file terlalu besar. Maksimal: 5MB")
            e.target.value = ""
            return
        }

        // Preview
        const reader = new FileReader()
        reader.onloadend = () => {
            setPhotoPreview(reader.result as string)
        }
        reader.readAsDataURL(file)

        // Upload to Supabase
        setIsUploading(true)
        try {
            const formDataUpload = new FormData()
            formDataUpload.append("file", file)
            formDataUpload.append("bucket", "images")

            const response = await fetch("/api/upload", {
                method: "POST",
                body: formDataUpload,
            })

            if (!response.ok) {
                const errorData = await response.json().catch(() => ({}))
                throw new Error(errorData.error || "Upload gagal")
            }
            const { publicUrl } = await response.json()
            setFormData((prev) => ({ ...prev, productPhoto: publicUrl }))
            toast.success("Foto berhasil diupload")
        } catch (err) {
            console.error("Upload error:", err)
            toast.error(err instanceof Error ? err.message : "Gagal mengupload foto")
            setPhotoPreview(null)
        } finally {
            setIsUploading(false)
        }
    }

    const clearPhoto = () => {
        setPhotoPreview(null)
        setFormData((prev) => ({ ...prev, productPhoto: "" }))
        if (fileInputRef.current) {
            fileInputRef.current.value = ""
        }
    }

    const handleSubmit = async () => {
        if (!formData.standardName || !formData.form || !formData.storageLocation) {
            return
        }
        await createMutation.mutate(formData)
    }

    const handleEdit = (e: React.MouseEvent, standard: Standard) => {
        e.stopPropagation()
        setEditingStandard(standard)
        setFormData({
            standardName: standard.standardName,
            casNumber: standard.casNumber || "",
            chemicalFormula: standard.chemicalFormula || "",
            supplier: standard.supplier || "",
            sizeValue: standard.sizeValue || "",
            sizeUnit: standard.sizeUnit || "ml",
            form: standard.form,
            storageLocation: standard.storageLocation,
            minimumStockLevel: standard.minimumStockLevel,
            productPhoto: standard.productPhoto || "",
        })
        setPhotoPreview(standard.productPhoto || null)
        setIsEditDialogOpen(true)
    }

    const handleUpdate = async () => {
        if (!editingStandard || !formData.standardName || !formData.form || !formData.storageLocation) {
            return
        }

        try {
            const response = await fetch(`/api/inventory/standards/${editingStandard.id}`, {
                method: "PUT",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify(formData),
            })
            if (!response.ok) throw new Error("Gagal mengupdate standard")
            setIsEditDialogOpen(false)
            setEditingStandard(null)
            resetForm()
            refetch()
        } catch (err) {
            console.error(err)
        }
    }

    const handleDeleteClick = (e: React.MouseEvent, standard: Standard) => {
        e.stopPropagation()
        setDeletingStandard(standard)
        setIsDeleteDialogOpen(true)
    }

    const handleDelete = async () => {
        if (!deletingStandard) return

        try {
            await fetch(`/api/inventory/standards/${deletingStandard.id}`, { method: "DELETE" })
            setIsDeleteDialogOpen(false)
            setDeletingStandard(null)
            refetch()
        } catch (err) {
            console.error(err)
        }
    }

    // Form fields JSX - inlined to prevent focus loss on re-render
    const formFieldsContent = (
        <div className="grid gap-4 py-4">
            <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                    <Label htmlFor="name">Nama Standard *</Label>
                    <Input
                        id="name"
                        placeholder="Contoh: Cu Standard 1000 ppm"
                        value={formData.standardName}
                        onChange={(e) => setFormData(prev => ({ ...prev, standardName: e.target.value }))}
                    />
                </div>
                <div className="space-y-2">
                    <Label htmlFor="cas">CAS Number</Label>
                    <Input
                        id="cas"
                        placeholder="Contoh: 7440-50-8"
                        value={formData.casNumber}
                        onChange={(e) => setFormData(prev => ({ ...prev, casNumber: e.target.value }))}
                    />
                </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                    <Label htmlFor="formula">Rumus Kimia</Label>
                    <Input
                        id="formula"
                        placeholder="Contoh: Cu"
                        value={formData.chemicalFormula}
                        onChange={(e) => setFormData(prev => ({ ...prev, chemicalFormula: e.target.value }))}
                    />
                </div>
                <div className="space-y-2">
                    <Label htmlFor="supplier">Supplier</Label>
                    <Input
                        id="supplier"
                        placeholder="Contoh: Merck"
                        value={formData.supplier}
                        onChange={(e) => setFormData(prev => ({ ...prev, supplier: e.target.value }))}
                    />
                </div>
            </div>
            <div className="grid grid-cols-4 gap-4">
                <div className="space-y-2">
                    <Label htmlFor="sizeValue">Ukuran</Label>
                    <Input
                        id="sizeValue"
                        type="number"
                        placeholder="100"
                        value={formData.sizeValue}
                        onChange={(e) => setFormData(prev => ({ ...prev, sizeValue: e.target.value }))}
                    />
                </div>
                <div className="space-y-2">
                    <Label htmlFor="sizeUnit">Satuan</Label>
                    <Select
                        value={formData.sizeUnit}
                        onValueChange={(value) => setFormData(prev => ({ ...prev, sizeUnit: value }))}
                    >
                        <SelectTrigger>
                            <SelectValue placeholder="Pilih" />
                        </SelectTrigger>
                        <SelectContent>
                            <SelectItem value="ml">ml</SelectItem>
                            <SelectItem value="g">gram</SelectItem>
                            <SelectItem value="L">Liter</SelectItem>
                        </SelectContent>
                    </Select>
                </div>
                <div className="space-y-2">
                    <Label htmlFor="form">Form *</Label>
                    <Select
                        value={formData.form}
                        onValueChange={(value: "solid" | "liquid" | "gas") => setFormData(prev => ({ ...prev, form: value }))}
                    >
                        <SelectTrigger>
                            <SelectValue placeholder="Pilih" />
                        </SelectTrigger>
                        <SelectContent>
                            <SelectItem value="liquid">Liquid</SelectItem>
                            <SelectItem value="solid">Solid</SelectItem>
                            <SelectItem value="gas">Gas</SelectItem>
                        </SelectContent>
                    </Select>
                </div>
                <div className="space-y-2">
                    <Label htmlFor="location">Lokasi *</Label>
                    <Select
                        value={formData.storageLocation}
                        onValueChange={(value: "TC 1" | "TC 2" | "TC 3") => setFormData(prev => ({ ...prev, storageLocation: value }))}
                    >
                        <SelectTrigger>
                            <SelectValue placeholder="Pilih" />
                        </SelectTrigger>
                        <SelectContent>
                            <SelectItem value="TC 1">TC 1</SelectItem>
                            <SelectItem value="TC 2">TC 2</SelectItem>
                            <SelectItem value="TC 3">TC 3</SelectItem>
                        </SelectContent>
                    </Select>
                </div>
            </div>
            <div className="space-y-2">
                <Label htmlFor="minStock">Stok Minimum</Label>
                <Input
                    id="minStock"
                    type="number"
                    value={formData.minimumStockLevel}
                    onChange={(e) => setFormData(prev => ({ ...prev, minimumStockLevel: parseInt(e.target.value) || 0 }))}
                />
            </div>
            {/* Photo Upload */}
            <div className="space-y-2">
                <Label>Foto Produk</Label>
                <div className="flex items-center gap-4">
                    {photoPreview ? (
                        <div className="relative w-24 h-24 rounded-lg overflow-hidden border">
                            <img src={photoPreview} alt="Preview" className="w-full h-full object-cover" />
                            <Button
                                type="button"
                                variant="destructive"
                                size="icon"
                                className="absolute top-1 right-1 h-6 w-6"
                                onClick={clearPhoto}
                            >
                                <X className="h-3 w-3" />
                            </Button>
                        </div>
                    ) : (
                        <div className="w-24 h-24 rounded-lg border-2 border-dashed flex items-center justify-center bg-muted">
                            <TestTubes className="h-8 w-8 text-muted-foreground/50" />
                        </div>
                    )}
                    <div>
                        <Input
                            ref={fileInputRef}
                            id="photo"
                            type="file"
                            accept="image/*"
                            className="hidden"
                            onChange={handlePhotoUpload}
                        />
                        <Button
                            type="button"
                            variant="outline"
                            onClick={() => fileInputRef.current?.click()}
                            disabled={isUploading}
                        >
                            {isUploading ? (
                                <>
                                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                                    Uploading...
                                </>
                            ) : (
                                <>
                                    <Upload className="mr-2 h-4 w-4" />
                                    Upload Foto
                                </>
                            )}
                        </Button>
                    </div>
                </div>
            </div>
            {createMutation.error && (
                <p className="text-sm text-destructive">{createMutation.error}</p>
            )}
        </div>
    )

    // Loading state
    if (isLoading) {
        return (
            <div className="flex flex-col items-center justify-center py-24">
                <Loader2 className="h-8 w-8 animate-spin text-primary mb-4" />
                <p className="text-muted-foreground">Memuat data standards...</p>
            </div>
        )
    }

    // Error state
    if (error) {
        return (
            <div className="flex flex-col items-center justify-center py-24">
                <p className="text-destructive mb-4">{error}</p>
                <Button onClick={refetch} variant="outline">
                    <RefreshCw className="h-4 w-4 mr-2" />
                    Coba Lagi
                </Button>
            </div>
        )
    }

    return (
        <div className="space-y-6">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight">Katalog Standard Stock</h1>
                    <p className="text-muted-foreground">
                        Kelola daftar larutan standar induk laboratorium
                    </p>
                </div>
                <Dialog open={isAddDialogOpen} onOpenChange={(open) => { setIsAddDialogOpen(open); if (!open) resetForm() }}>
                    <DialogTrigger asChild>
                        <Button>
                            <Plus className="mr-2 h-4 w-4" />
                            Tambah Baru
                        </Button>
                    </DialogTrigger>
                    <DialogContent className="max-w-2xl">
                        <DialogHeader>
                            <DialogTitle>Tambah Standard Stock Baru</DialogTitle>
                            <DialogDescription>
                                Masukkan informasi larutan standar yang akan ditambahkan ke katalog
                            </DialogDescription>
                        </DialogHeader>
                        {formFieldsContent}
                        <DialogFooter>
                            <Button variant="outline" onClick={() => { setIsAddDialogOpen(false); resetForm() }}>
                                Batal
                            </Button>
                            <Button onClick={handleSubmit} disabled={createMutation.isLoading || isUploading}>
                                {createMutation.isLoading && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
                                Simpan
                            </Button>
                        </DialogFooter>
                    </DialogContent>
                </Dialog>
            </div>

            {/* Edit Dialog */}
            <Dialog open={isEditDialogOpen} onOpenChange={(open) => { setIsEditDialogOpen(open); if (!open) { resetForm(); setEditingStandard(null) } }}>
                <DialogContent className="max-w-2xl">
                    <DialogHeader>
                        <DialogTitle>Edit Standard</DialogTitle>
                        <DialogDescription>
                            Ubah informasi standard stock
                        </DialogDescription>
                    </DialogHeader>
                    {formFieldsContent}
                    <DialogFooter>
                        <Button variant="outline" onClick={() => { setIsEditDialogOpen(false); resetForm(); setEditingStandard(null) }}>
                            Batal
                        </Button>
                        <Button onClick={handleUpdate} disabled={isUploading}>
                            {isUploading && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
                            Simpan Perubahan
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>

            {/* Delete Confirmation Dialog */}
            <AlertDialog open={isDeleteDialogOpen} onOpenChange={setIsDeleteDialogOpen}>
                <AlertDialogContent>
                    <AlertDialogHeader>
                        <AlertDialogTitle>Hapus Standard?</AlertDialogTitle>
                        <AlertDialogDescription>
                            Tindakan ini tidak dapat dibatalkan. Standard &quot;{deletingStandard?.standardName}&quot; akan dihapus secara permanen.
                        </AlertDialogDescription>
                    </AlertDialogHeader>
                    <AlertDialogFooter>
                        <AlertDialogCancel onClick={() => setDeletingStandard(null)}>Batal</AlertDialogCancel>
                        <AlertDialogAction
                            onClick={handleDelete}
                            className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
                        >
                            Hapus
                        </AlertDialogAction>
                    </AlertDialogFooter>
                </AlertDialogContent>
            </AlertDialog>

            {/* Filters */}
            <div className="flex gap-4">
                <div className="relative flex-1 max-w-sm">
                    <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
                    <Input
                        placeholder="Cari standard atau CAS number..."
                        value={search}
                        onChange={(e) => setSearch(e.target.value)}
                        className="pl-9"
                    />
                </div>
                <Select value={statusFilter} onValueChange={setStatusFilter}>
                    <SelectTrigger className="w-[180px]">
                        <SelectValue placeholder="Filter Status" />
                    </SelectTrigger>
                    <SelectContent>
                        <SelectItem value="all">Semua Status</SelectItem>
                        <SelectItem value="available">Tersedia</SelectItem>
                        <SelectItem value="low_stock">Stok Menipis</SelectItem>
                        <SelectItem value="out_of_stock">Habis</SelectItem>
                        <SelectItem value="expired">Expired</SelectItem>
                    </SelectContent>
                </Select>
                <Select value={sortBy} onValueChange={(val) => setSortBy(val as 'fefo' | 'name' | 'stock')}>
                    <SelectTrigger className="w-[180px]">
                        <SelectValue placeholder="Urutkan" />
                    </SelectTrigger>
                    <SelectContent>
                        <SelectItem value="fefo">FEFO (Exp Terdekat)</SelectItem>
                        <SelectItem value="name">Nama A-Z</SelectItem>
                        <SelectItem value="stock">Stok Terendah</SelectItem>
                    </SelectContent>
                </Select>
            </div>

            {/* Cards Grid */}
            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
                {displayStandards.map((standard) => (
                    <Card
                        key={standard.id}
                        className="overflow-hidden cursor-pointer transition-all duration-300 hover:shadow-lg hover:border-primary/50 hover:-translate-y-1"
                        onClick={() => router.push(`/inventory/standards/${standard.id}`)}
                    >
                        {/* Image */}
                        <div className="aspect-square bg-muted flex items-center justify-center transition-colors hover:bg-muted/80 overflow-hidden">
                            {standard.productPhoto ? (
                                <img src={standard.productPhoto} alt={standard.standardName} className="w-full h-full object-cover" />
                            ) : (
                                <TestTubes className="h-16 w-16 text-muted-foreground/50" />
                            )}
                        </div>
                        <CardContent className="p-4">
                            <h3 className="font-semibold truncate">{standard.standardName}</h3>
                            <p className="text-sm text-muted-foreground">CAS: {standard.casNumber || "-"}</p>
                            <p className="text-sm text-muted-foreground">
                                {standard.chemicalFormula || "-"} ΓÇó {standard.sizeValue || "-"} {standard.sizeUnit || ""}
                            </p>
                            <div className="mt-2 flex items-center justify-between">
                                <Badge variant={statusConfig[standard.status]?.variant || "secondary"}>
                                    {statusConfig[standard.status]?.label || standard.status}
                                </Badge>
                                <span className="text-sm">Stok: {standard.currentStock}</span>
                            </div>
                            {standard.nearestExpDate && (
                                <p className="mt-2 text-xs text-muted-foreground">
                                    Exp: {new Date(standard.nearestExpDate).toLocaleDateString("id-ID")}
                                </p>
                            )}
                        </CardContent>
                        <CardFooter className="border-t p-2 flex justify-end gap-1">
                            <Button variant="ghost" size="icon" onClick={(e) => { e.stopPropagation(); router.push(`/inventory/standards/${standard.id}`) }}>
                                <Eye className="h-4 w-4" />
                            </Button>
                            <Button variant="ghost" size="icon" onClick={(e) => handleEdit(e, standard)}>
                                <Edit className="h-4 w-4" />
                            </Button>
                            <Button variant="ghost" size="icon" className="text-destructive" onClick={(e) => handleDeleteClick(e, standard)}>
                                <Trash2 className="h-4 w-4" />
                            </Button>
                        </CardFooter>
                    </Card>
                ))}
            </div>

            {displayStandards.length === 0 && (
                <div className="flex flex-col items-center justify-center py-12 text-center">
                    <TestTubes className="h-12 w-12 text-muted-foreground/50 mb-4" />
                    <p className="text-muted-foreground">Tidak ada standard stock ditemukan</p>
                </div>
            )}

            {/* Pagination */}
            {pagination.totalPages > 1 && (
                <Pagination
                    pagination={pagination}
                    onPageChange={setPage}
                />
            )}
        </div>
    )
}

"use client"

import { useState } from "react"
import { useRouter } from "next/navigation"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select"
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "@/components/ui/dialog"
import {
    AlertDialog,
    AlertDialogAction,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle,
} from "@/components/ui/alert-dialog"
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from "@/components/ui/table"
import { Label } from "@/components/ui/label"
import { Badge } from "@/components/ui/badge"
import { GraduationCap, Play, Users, CheckCircle2, XCircle, AlertTriangle, Loader2, RefreshCw, Plus, Trash2, Search } from "lucide-react"
import { useFetchPaginated, useMutation } from "@/hooks/use-api"
import { Pagination } from "@/components/ui/pagination"
import { SearchableSelect } from "@/components/ui/searchable-select"

interface TrainingSetItem {
    id: string
    itemType: string
    itemName: string
    quantity: string
    unit: string | null
}

interface TrainingSet {
    id: string
    trainingName: string
    participantsPerSet: number
    items: TrainingSetItem[]
}

type StockCheckResult = {
    item: string
    type: string
    required: number
    available: number
    unit: string
    status: "available" | "insufficient" | "not_found"
}

export default function TrainingPage() {
    const router = useRouter()
    const [selectedTraining, setSelectedTraining] = useState<string>("")
    const [participants, setParticipants] = useState<string>("")
    const [isCheckDialogOpen, setIsCheckDialogOpen] = useState(false)
    const [checkResults, setCheckResults] = useState<StockCheckResult[]>([])
    const [isProcessing, setIsProcessing] = useState(false)
    const [isChecking, setIsChecking] = useState(false)
    const [deleteId, setDeleteId] = useState<string | null>(null)
    const [isDeleting, setIsDeleting] = useState(false)

    // Form state for adding new training set
    const [isAddDialogOpen, setIsAddDialogOpen] = useState(false)
    const [newTrainingName, setNewTrainingName] = useState("")
    const [newParticipantsPerSet, setNewParticipantsPerSet] = useState("")
    const [newItems, setNewItems] = useState<{ itemType: string; itemName: string; quantity: string; unit: string }[]>([])

    // Warehouse options for dropdowns
    const [warehouseOptions, setWarehouseOptions] = useState<Record<string, { id: string; name: string; unit: string }[]>>({})
    const [loadingOptions, setLoadingOptions] = useState<Record<string, boolean>>({})

    // Fetch training sets from API with pagination
    const { data: trainingSets, pagination, isLoading, isFetching, error, refetch, search, setSearch, setPage } = useFetchPaginated<TrainingSet>(
        "/api/inventory/training",
        {}
    )
    const displayTrainingSets = trainingSets || []

    // Create training set mutation
    const createTraining = useMutation<TrainingSet, { trainingName: string; participantsPerSet: number; items: typeof newItems }>(
        "/api/inventory/training",
        "POST",
        {
            onSuccess: () => {
                setIsAddDialogOpen(false)
                setNewTrainingName("")
                setNewParticipantsPerSet("")
                setNewItems([])
                setWarehouseOptions({})
                refetch()
            }
        }
    )

    // Fetch warehouse options based on type
    const fetchWarehouseOptions = async (type: string) => {
        if (warehouseOptions[type] || loadingOptions[type]) return

        setLoadingOptions(prev => ({ ...prev, [type]: true }))
        try {
            const response = await fetch(`/api/inventory/warehouse-options?type=${type}`)
            if (response.ok) {
                const data = await response.json()
                setWarehouseOptions(prev => ({ ...prev, [type]: data.items || [] }))
            }
        } catch (err) {
            console.error("Error fetching warehouse options:", err)
        } finally {
            setLoadingOptions(prev => ({ ...prev, [type]: false }))
        }
    }

    const handleAddItem = () => {
        setNewItems([...newItems, { itemType: "", itemName: "", quantity: "", unit: "" }])
    }

    const handleRemoveItem = (index: number) => {
        setNewItems(newItems.filter((_, i) => i !== index))
    }

    const handleUpdateItem = async (index: number, field: string, value: string) => {
        const updated = [...newItems]
        updated[index] = { ...updated[index], [field]: value }

        // If type changed, reset item name and unit, and fetch options
        if (field === "itemType") {
            updated[index].itemName = ""
            updated[index].unit = ""
            await fetchWarehouseOptions(value)
        }

        // If item name changed, auto-fill unit from warehouse options
        if (field === "itemName" && updated[index].itemType) {
            const options = warehouseOptions[updated[index].itemType] || []
            const selectedItem = options.find(opt => opt.id === value || opt.name === value)
            if (selectedItem) {
                updated[index].itemName = selectedItem.name
                updated[index].unit = selectedItem.unit
            }
        }

        setNewItems(updated)
    }

    // Convert warehouse options to SearchableSelect format
    const getWarehouseSelectOptions = (type: string) => {
        const options = warehouseOptions[type] || []
        return options.map(opt => ({
            value: opt.name,
            label: opt.name,
        }))
    }

    const handleCreateTraining = async () => {
        if (!newTrainingName || !newParticipantsPerSet || newItems.length === 0) return

        await createTraining.mutate({
            trainingName: newTrainingName,
            participantsPerSet: parseInt(newParticipantsPerSet),
            items: newItems.filter(item => item.itemName && item.quantity)
        })
    }

    const handleDeleteTraining = async () => {
        if (!deleteId) return
        setIsDeleting(true)
        try {
            const res = await fetch(`/api/inventory/training/${deleteId}`, { method: "DELETE" })
            if (!res.ok) throw new Error("Gagal menghapus")
            refetch()
        } catch (err) {
            console.error(err)
        } finally {
            setIsDeleting(false)
            setDeleteId(null)
        }
    }

    const handleCheckStock = async () => {
        if (!selectedTraining || !participants) return

        setIsChecking(true)
        try {
            const response = await fetch(`/api/inventory/training/${selectedTraining}?action=check-stock`, {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ participants: parseInt(participants) }),
            })

            if (response.ok) {
                const data = await response.json()
                setCheckResults(data.stockCheck || [])
            } else {
                // Fallback to mock if API fails
                const training = displayTrainingSets.find(t => t.id === selectedTraining)
                if (training) {
                    const numParticipants = parseInt(participants)
                    const sets = Math.ceil(numParticipants / training.participantsPerSet)

                    const results: StockCheckResult[] = training.items.map(item => ({
                        item: item.itemName,
                        type: item.itemType,
                        required: Number(item.quantity) * sets,
                        available: Math.floor(Math.random() * 30) + 5,
                        unit: item.unit || "unit",
                        status: Math.random() > 0.2 ? "available" as const : "insufficient" as const,
                    }))
                    setCheckResults(results)
                }
            }
        } catch (err) {
            console.error("Stock check error:", err)
        } finally {
            setIsChecking(false)
            setIsCheckDialogOpen(true)
        }
    }

    const hasInsufficientStock = checkResults.some(r => r.status === "insufficient" || r.status === "not_found")

    const handleProcessTraining = async () => {
        if (!selectedTraining || !participants) return

        setIsProcessing(true)
        try {
            const response = await fetch(`/api/inventory/training/${selectedTraining}?action=process`, {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ participants: parseInt(participants) }),
            })

            const result = await response.json()

            if (response.ok && result.success) {
                setIsCheckDialogOpen(false)
                setSelectedTraining("")
                setParticipants("")
                setCheckResults([])
                alert(`Training berhasil diproses! ${result.message}\n\nItem yang diproses:\n${result.processed.map((p: { item: string; action: string; quantity: number }) => `- ${p.item}: ${p.action === 'reduced' ? 'dikurangi' : 'dipantau'} ${p.quantity}`).join('\n')}`)
            } else {
                alert(`Gagal memproses training: ${result.message || result.error}`)
            }
        } catch (err) {
            console.error("Process training error:", err)
            alert("Terjadi kesalahan saat memproses training")
        } finally {
            setIsProcessing(false)
        }
    }

    // Group items by type for display
    const groupItemsByType = (items: TrainingSetItem[]) => {
        const equipment = items.filter(i => i.itemType === "equipment" || i.itemType === "barang")
        const consumables = items.filter(i => i.itemType === "consumable")
        const reagents = items.filter(i => i.itemType === "reagent" || i.itemType === "standard" || i.itemType === "reagent_standard")
        const samples = items.filter(i => i.itemType === "sample")
        return { equipment, consumables, reagents, samples }
    }

    // Loading state
    if (isLoading) {
        return (
            <div className="flex flex-col items-center justify-center py-24">
                <Loader2 className="h-8 w-8 animate-spin text-primary mb-4" />
                <p className="text-muted-foreground">Memuat data training...</p>
            </div>
        )
    }

    // Error state
    if (error) {
        return (
            <div className="flex flex-col items-center justify-center py-24">
                <p className="text-destructive mb-4">{error}</p>
                <Button onClick={refetch} variant="outline">
                    <RefreshCw className="h-4 w-4 mr-2" />
                    Coba Lagi
                </Button>
            </div>
        )
    }

    return (
        <div className="space-y-6">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight">Training Usage</h1>
                    <p className="text-muted-foreground">
                        Kelola penggunaan bahan untuk training laboratorium
                    </p>
                </div>
                <Dialog open={isAddDialogOpen} onOpenChange={setIsAddDialogOpen}>
                    <DialogTrigger asChild>
                        <Button>
                            <Plus className="mr-2 h-4 w-4" />
                            Tambah Training Set
                        </Button>
                    </DialogTrigger>
                    <DialogContent className="max-w-2xl max-h-[85vh] overflow-y-auto">
                        <DialogHeader>
                            <DialogTitle>Tambah Training Set Baru</DialogTitle>
                            <DialogDescription>
                                Buat konfigurasi kebutuhan item untuk training baru
                            </DialogDescription>
                        </DialogHeader>
                        <div className="grid gap-4 py-4">
                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-2">
                                    <Label htmlFor="trainingName">Nama Training *</Label>
                                    <Input
                                        id="trainingName"
                                        placeholder="Contoh: Praktikum HPLC Dasar"
                                        value={newTrainingName}
                                        onChange={(e) => setNewTrainingName(e.target.value)}
                                    />
                                </div>
                                <div className="space-y-2">
                                    <Label htmlFor="participantsPerSet">Peserta per Set *</Label>
                                    <Input
                                        id="participantsPerSet"
                                        type="number"
                                        placeholder="5"
                                        value={newParticipantsPerSet}
                                        onChange={(e) => setNewParticipantsPerSet(e.target.value)}
                                    />
                                </div>
                            </div>

                            <div className="space-y-3">
                                <div className="flex items-center justify-between">
                                    <Label>Items yang Dibutuhkan</Label>
                                    <Button type="button" variant="outline" size="sm" onClick={handleAddItem}>
                                        <Plus className="mr-1 h-3 w-3" />
                                        Tambah Item
                                    </Button>
                                </div>

                                {newItems.length === 0 ? (
                                    <p className="text-sm text-muted-foreground text-center py-4">
                                        Belum ada item. Klik &quot;Tambah Item&quot; untuk menambahkan.
                                    </p>
                                ) : (
                                    <div className="space-y-2">
                                        {newItems.map((item, idx) => (
                                            <div key={idx} className="flex items-center gap-2 p-3 border rounded-lg">
                                                <Select
                                                    value={item.itemType}
                                                    onValueChange={(value) => handleUpdateItem(idx, "itemType", value)}
                                                >
                                                    <SelectTrigger className="w-[130px]">
                                                        <SelectValue placeholder="Tipe" />
                                                    </SelectTrigger>
                                                    <SelectContent>
                                                        <SelectItem value="reagent">Reagen</SelectItem>
                                                        <SelectItem value="standard">Standard</SelectItem>
                                                        <SelectItem value="sample">Sample</SelectItem>
                                                        <SelectItem value="barang">Barang</SelectItem>
                                                        <SelectItem value="consumable">Consumable</SelectItem>
                                                    </SelectContent>
                                                </Select>
                                                <SearchableSelect
                                                    options={getWarehouseSelectOptions(item.itemType)}
                                                    value={item.itemName}
                                                    onValueChange={(value) => handleUpdateItem(idx, "itemName", value)}
                                                    placeholder={loadingOptions[item.itemType] ? "Loading..." : "Pilih atau cari item..."}
                                                    searchPlaceholder="Ketik untuk mencari..."
                                                    disabled={!item.itemType}
                                                    isLoading={loadingOptions[item.itemType]}
                                                    className="flex-1"
                                                />
                                                <Input
                                                    type="number"
                                                    placeholder="Qty"
                                                    className="w-20"
                                                    value={item.quantity}
                                                    onChange={(e) => handleUpdateItem(idx, "quantity", e.target.value)}
                                                />
                                                <Input
                                                    placeholder="Unit"
                                                    className="w-[80px]"
                                                    value={item.unit}
                                                    readOnly
                                                    disabled
                                                />
                                                <Button
                                                    type="button"
                                                    variant="ghost"
                                                    size="icon"
                                                    className="text-destructive"
                                                    onClick={() => handleRemoveItem(idx)}
                                                >
                                                    <Trash2 className="h-4 w-4" />
                                                </Button>
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </div>
                        </div>
                        <DialogFooter>
                            <Button variant="outline" onClick={() => setIsAddDialogOpen(false)}>
                                Batal
                            </Button>
                            <Button
                                onClick={handleCreateTraining}
                                disabled={createTraining.isLoading || !newTrainingName || !newParticipantsPerSet || newItems.length === 0}
                            >
                                {createTraining.isLoading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                                Simpan
                            </Button>
                        </DialogFooter>
                    </DialogContent>
                </Dialog>
            </div>

            {/* Training Check Card */}
            <Card>
                <CardHeader>
                    <CardTitle className="flex items-center gap-2">
                        <GraduationCap className="h-5 w-5" />
                        Cek Stok Training
                    </CardTitle>
                    <CardDescription>
                        Pilih training dan jumlah peserta untuk mengecek ketersediaan stok
                    </CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                    <div className="grid gap-4 md:grid-cols-3">
                        <div className="space-y-2">
                            <Label>Nama Training</Label>
                            <Select value={selectedTraining} onValueChange={setSelectedTraining}>
                                <SelectTrigger>
                                    <SelectValue placeholder="Pilih training" />
                                </SelectTrigger>
                                <SelectContent>
                                    {displayTrainingSets.map(t => (
                                        <SelectItem key={t.id} value={t.id}>
                                            {t.trainingName}
                                        </SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                        </div>
                        <div className="space-y-2">
                            <Label>Jumlah Peserta</Label>
                            <Input
                                type="number"
                                placeholder="Contoh: 10"
                                value={participants}
                                onChange={(e) => setParticipants(e.target.value)}
                            />
                        </div>
                        <div className="flex items-end">
                            <Button
                                onClick={handleCheckStock}
                                disabled={!selectedTraining || !participants || isChecking}
                                className="w-full"
                            >
                                {isChecking ? (
                                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                                ) : (
                                    <Play className="mr-2 h-4 w-4" />
                                )}
                                Mulai Cek Stok
                            </Button>
                        </div>
                    </div>
                </CardContent>
            </Card>

            {/* Training Sets List */}
            <Card>
                <CardHeader>
                    <CardTitle>Daftar Set Training</CardTitle>
                    <CardDescription>
                        Konfigurasi kebutuhan item per set training
                    </CardDescription>
                </CardHeader>
                <CardContent>
                    {displayTrainingSets.length === 0 ? (
                        <div className="flex flex-col items-center justify-center py-12 text-center">
                            <GraduationCap className="h-12 w-12 text-muted-foreground/50 mb-4" />
                            <p className="text-muted-foreground">Belum ada training set</p>
                        </div>
                    ) : (
                        <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
                            {displayTrainingSets.map((training) => {
                                const { equipment, consumables, reagents, samples } = groupItemsByType(training.items)
                                return (
                                    <Card
                                        key={training.id}
                                        className="cursor-pointer transition-all duration-300 hover:shadow-lg hover:border-primary/50 hover:-translate-y-1"
                                        onClick={() => router.push(`/inventory/training/${training.id}`)}
                                    >
                                        <CardHeader className="pb-2">
                                            <CardTitle className="text-lg">{training.trainingName}</CardTitle>
                                            <CardDescription className="flex items-center gap-1">
                                                <Users className="h-4 w-4" />
                                                Per {training.participantsPerSet} orang
                                            </CardDescription>
                                        </CardHeader>
                                        <CardContent className="text-sm space-y-2">
                                            {equipment.length > 0 && (
                                                <div>
                                                    <p className="font-medium text-muted-foreground">Peralatan:</p>
                                                    {equipment.map((eq, i) => (
                                                        <p key={i}>ΓÇó {eq.itemName} ({eq.quantity} {eq.unit || "pcs"})</p>
                                                    ))}
                                                </div>
                                            )}
                                            {consumables.length > 0 && (
                                                <div>
                                                    <p className="font-medium text-muted-foreground">Consumable:</p>
                                                    {consumables.map((c, i) => (
                                                        <p key={i}>ΓÇó {c.itemName} ({c.quantity} {c.unit})</p>
                                                    ))}
                                                </div>
                                            )}
                                            {reagents.length > 0 && (
                                                <div>
                                                    <p className="font-medium text-muted-foreground">Reagen/Standard:</p>
                                                    {reagents.map((r, i) => (
                                                        <p key={i}>ΓÇó {r.itemName} ({r.quantity} {r.unit})</p>
                                                    ))}
                                                </div>
                                            )}
                                            {samples.length > 0 && (
                                                <div>
                                                    <p className="font-medium text-muted-foreground">Sample:</p>
                                                    {samples.map((s, i) => (
                                                        <p key={i}>ΓÇó {s.itemName} ({s.quantity} {s.unit})</p>
                                                    ))}
                                                </div>
                                            )}
                                            {training.items.length === 0 && (
                                                <p className="text-muted-foreground italic">Belum ada item</p>
                                            )}
                                            <div className="pt-2 border-t mt-2">
                                                <Button
                                                    variant="ghost"
                                                    size="sm"
                                                    className="text-destructive hover:text-destructive w-full"
                                                    onClick={(e) => {
                                                        e.stopPropagation()
                                                        setDeleteId(training.id)
                                                    }}
                                                >
                                                    <Trash2 className="h-4 w-4 mr-1" />
                                                    Hapus Training Set
                                                </Button>
                                            </div>
                                        </CardContent>
                                    </Card>
                                )
                            })}
                        </div>
                    )}
                </CardContent>
            </Card>

            {/* Pagination */}
            {pagination.totalPages > 1 && (
                <Pagination
                    pagination={pagination}
                    onPageChange={setPage}
                />
            )}

            {/* Stock Check Dialog */}
            <Dialog open={isCheckDialogOpen} onOpenChange={setIsCheckDialogOpen}>
                <DialogContent className="max-w-3xl max-h-[85vh] overflow-y-auto">
                    <DialogHeader>
                        <DialogTitle>Hasil Pengecekan Stok</DialogTitle>
                        <DialogDescription>
                            Training: {displayTrainingSets.find(t => t.id === selectedTraining)?.trainingName} |
                            Peserta: {participants} orang
                        </DialogDescription>
                    </DialogHeader>

                    <div className="rounded-md border">
                        <Table>
                            <TableHeader>
                                <TableRow>
                                    <TableHead>Item</TableHead>
                                    <TableHead>Tipe</TableHead>
                                    <TableHead className="text-right">Dibutuhkan</TableHead>
                                    <TableHead className="text-right">Tersedia</TableHead>
                                    <TableHead>Status</TableHead>
                                </TableRow>
                            </TableHeader>
                            <TableBody>
                                {checkResults.map((result, idx) => (
                                    <TableRow key={idx}>
                                        <TableCell className="font-medium">{result.item}</TableCell>
                                        <TableCell>
                                            <Badge variant="outline">
                                                {result.type === "equipment" || result.type === "barang" ? "Barang" :
                                                    result.type === "consumable" ? "Consumable" :
                                                        result.type === "sample" ? "Sample" : "Reagen"}
                                            </Badge>
                                        </TableCell>
                                        <TableCell className="text-right">
                                            {result.required} {result.unit}
                                        </TableCell>
                                        <TableCell className="text-right">
                                            {result.available} {result.unit}
                                        </TableCell>
                                        <TableCell>
                                            {result.status === "available" ? (
                                                <span className="flex items-center gap-1 text-green-600">
                                                    <CheckCircle2 className="h-4 w-4" /> Tersedia
                                                </span>
                                            ) : result.status === "not_found" ? (
                                                <span className="flex items-center gap-1 text-yellow-600">
                                                    <AlertTriangle className="h-4 w-4" /> Tidak Ditemukan
                                                </span>
                                            ) : (
                                                <span className="flex items-center gap-1 text-red-600">
                                                    <XCircle className="h-4 w-4" /> Tidak Cukup
                                                </span>
                                            )}
                                        </TableCell>
                                    </TableRow>
                                ))}
                            </TableBody>
                        </Table>
                    </div>

                    {hasInsufficientStock && (
                        <div className="flex items-center gap-2 p-3 bg-yellow-50 dark:bg-yellow-950 rounded-lg text-yellow-800 dark:text-yellow-200">
                            <AlertTriangle className="h-5 w-5" />
                            <p className="text-sm">
                                Beberapa item tidak mencukupi. Transaksi tidak dapat dilanjutkan.
                            </p>
                        </div>
                    )}

                    <DialogFooter>
                        <Button variant="outline" onClick={() => setIsCheckDialogOpen(false)}>
                            Tutup
                        </Button>
                        {!hasInsufficientStock && checkResults.length > 0 && (
                            <Button onClick={handleProcessTraining} disabled={isProcessing}>
                                {isProcessing ? "Memproses..." : "Proses & Kurangi Stok"}
                            </Button>
                        )}
                    </DialogFooter>
                </DialogContent>
            </Dialog>

            {/* Delete Confirmation Dialog */}
            <AlertDialog open={!!deleteId} onOpenChange={() => setDeleteId(null)}>
                <AlertDialogContent>
                    <AlertDialogHeader>
                        <AlertDialogTitle>Hapus Training Set?</AlertDialogTitle>
                        <AlertDialogDescription>
                            Apakah Anda yakin ingin menghapus training set ini? Semua konfigurasi item akan ikut terhapus.
                        </AlertDialogDescription>
                    </AlertDialogHeader>
                    <AlertDialogFooter>
                        <AlertDialogCancel disabled={isDeleting}>Batal</AlertDialogCancel>
                        <AlertDialogAction
                            onClick={handleDeleteTraining}
                            disabled={isDeleting}
                            className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
                        >
                            {isDeleting ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : null}
                            Hapus
                        </AlertDialogAction>
                    </AlertDialogFooter>
                </AlertDialogContent>
            </AlertDialog>
        </div>
    )
}

"use client";

import { useState, useEffect, useCallback } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from "@/components/ui/table";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import {
    DollarSign,
    TrendingUp,
    TrendingDown,
    Calendar,
    Users,
    FileText,
    ChevronLeft,
    ChevronRight,
    Eye,
    DownloadCloud,
    RefreshCw,
    Loader2,
} from "lucide-react";
import { format } from "date-fns";
import { id as localeID } from "date-fns/locale";
import {
    AreaChart,
    Area,
    XAxis,
    YAxis,
    CartesianGrid,
    Tooltip,
    ResponsiveContainer,
} from "recharts";

// Types
interface CostStats {
    thisMonth: number;
    lastMonth: number;
    ytd: number;
    percentChange: number;
}

interface CostTrend {
    month: string;
    year: number;
    totalCost: number;
    executionCount: number;
}

interface CostLogItem {
    id: string;
    itemName: string;
    itemType: string;
    quantity: string;
    unit: string;
    unitCost: string;
    totalCost: string;
}

interface CostLog {
    id: string;
    trainingSetId: string | null;
    trainingName: string;
    executedAt: string;
    executedByName: string | null;
    participants: number;
    setsUsed: number;
    totalCost: string;
    notes: string | null;
    items: CostLogItem[];
}

interface CostReportData {
    stats?: CostStats;
    trends?: CostTrend[];
    logs?: {
        data: CostLog[];
        pagination: {
            page: number;
            limit: number;
            total: number;
            totalPages: number;
        };
    };
}

export default function TrainingCostReportsPage() {
    const [data, setData] = useState<CostReportData | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [page, setPage] = useState(1);
    const [selectedLog, setSelectedLog] = useState<CostLog | null>(null);
    const [detailDialogOpen, setDetailDialogOpen] = useState(false);

    // Date range filter state
    const [startDate, setStartDate] = useState<string>("");
    const [endDate, setEndDate] = useState<string>("");

    // Fetch data
    const fetchData = useCallback(async () => {
        setIsLoading(true);
        setError(null);
        try {
            const params = new URLSearchParams({ view: 'all', page: String(page) });
            if (startDate) params.append('startDate', startDate);
            if (endDate) params.append('endDate', endDate);
            const response = await fetch(`/api/reports/training-costs?${params.toString()}`);
            if (!response.ok) {
                const errorData = await response.json();
                throw new Error(errorData.error || "Gagal mengambil data");
            }
            const result = await response.json();
            setData(result);
        } catch (err) {
            setError(err instanceof Error ? err.message : "Terjadi kesalahan");
        } finally {
            setIsLoading(false);
        }
    }, [page, startDate, endDate]);

    useEffect(() => {
        fetchData();
    }, [fetchData]);

    // Format currency
    const formatCurrency = (amount: number | string): string => {
        const num = typeof amount === 'string' ? parseFloat(amount) : amount;
        return new Intl.NumberFormat('id-ID', {
            style: 'currency',
            currency: 'IDR',
            minimumFractionDigits: 0,
            maximumFractionDigits: 0,
        }).format(num);
    };

    // Format currency for chart
    const formatCurrencyShort = (amount: number): string => {
        if (amount >= 1000000000) {
            return `${(amount / 1000000000).toFixed(1)}M`;
        }
        if (amount >= 1000000) {
            return `${(amount / 1000000).toFixed(1)}jt`;
        }
        if (amount >= 1000) {
            return `${(amount / 1000).toFixed(0)}rb`;
        }
        return `Rp${amount}`;
    };

    // View detail dialog
    const handleViewDetail = (log: CostLog) => {
        setSelectedLog(log);
        setDetailDialogOpen(true);
    };

    if (isLoading && !data) {
        return (
            <div className="flex items-center justify-center h-96">
                <Loader2 className="h-8 w-8 animate-spin text-primary" />
                <span className="ml-2">Memuat data laporan...</span>
            </div>
        );
    }

    if (error) {
        return (
            <div className="flex flex-col items-center justify-center h-96 space-y-4">
                <p className="text-destructive">{error}</p>
                <Button onClick={fetchData}>Coba Lagi</Button>
            </div>
        );
    }

    const stats = data?.stats;
    const trends = data?.trends || [];
    const logs = data?.logs?.data || [];
    const pagination = data?.logs?.pagination;

    return (
        <div className="space-y-6">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight">Laporan Pengeluaran</h1>
                    <p className="text-muted-foreground">
                        Monitoring dan analisis biaya penggunaan material
                    </p>
                </div>
                <div className="flex items-center gap-2">
                    <Input
                        type="date"
                        placeholder="Dari"
                        value={startDate}
                        onChange={(e) => setStartDate(e.target.value)}
                        className="w-40"
                    />
                    <span className="text-muted-foreground">-</span>
                    <Input
                        type="date"
                        placeholder="Sampai"
                        value={endDate}
                        onChange={(e) => setEndDate(e.target.value)}
                        className="w-40"
                    />
                    <Button variant="outline" onClick={fetchData} disabled={isLoading}>
                        <RefreshCw className={`mr-2 h-4 w-4 ${isLoading ? 'animate-spin' : ''}`} />
                        Refresh
                    </Button>
                </div>
            </div>

            {/* Stats Cards */}
            <div className="grid gap-4 md:grid-cols-3">
                {/* Bulan Ini */}
                <Card className="bg-gradient-to-br from-blue-50 to-blue-100 dark:from-blue-950 dark:to-blue-900 border-blue-200 dark:border-blue-800">
                    <CardHeader className="flex flex-row items-center justify-between pb-2">
                        <CardTitle className="text-sm font-medium text-blue-700 dark:text-blue-300">
                            Biaya Bulan Ini
                        </CardTitle>
                        <DollarSign className="h-4 w-4 text-blue-500" />
                    </CardHeader>
                    <CardContent>
                        <div className="text-2xl font-bold text-blue-900 dark:text-blue-100">
                            {formatCurrency(stats?.thisMonth || 0)}
                        </div>
                        <div className="flex items-center mt-1">
                            {(stats?.percentChange || 0) >= 0 ? (
                                <TrendingUp className="h-4 w-4 text-red-500 mr-1" />
                            ) : (
                                <TrendingDown className="h-4 w-4 text-green-500 mr-1" />
                            )}
                            <span className={`text-sm ${(stats?.percentChange || 0) >= 0 ? 'text-red-500' : 'text-green-500'}`}>
                                {Math.abs(stats?.percentChange || 0).toFixed(1)}%
                            </span>
                            <span className="text-sm text-muted-foreground ml-1">dari bulan lalu</span>
                        </div>
                    </CardContent>
                </Card>

                {/* Bulan Lalu */}
                <Card className="bg-gradient-to-br from-slate-50 to-slate-100 dark:from-slate-950 dark:to-slate-900">
                    <CardHeader className="flex flex-row items-center justify-between pb-2">
                        <CardTitle className="text-sm font-medium text-muted-foreground">
                            Biaya Bulan Lalu
                        </CardTitle>
                        <Calendar className="h-4 w-4 text-muted-foreground" />
                    </CardHeader>
                    <CardContent>
                        <div className="text-2xl font-bold">
                            {formatCurrency(stats?.lastMonth || 0)}
                        </div>
                    </CardContent>
                </Card>

                {/* YTD */}
                <Card className="bg-gradient-to-br from-emerald-50 to-emerald-100 dark:from-emerald-950 dark:to-emerald-900 border-emerald-200 dark:border-emerald-800">
                    <CardHeader className="flex flex-row items-center justify-between pb-2">
                        <CardTitle className="text-sm font-medium text-emerald-700 dark:text-emerald-300">
                            Total Tahun Ini (YTD)
                        </CardTitle>
                        <TrendingUp className="h-4 w-4 text-emerald-500" />
                    </CardHeader>
                    <CardContent>
                        <div className="text-2xl font-bold text-emerald-900 dark:text-emerald-100">
                            {formatCurrency(stats?.ytd || 0)}
                        </div>
                    </CardContent>
                </Card>
            </div>

            {/* Trend Chart */}
            <Card>
                <CardHeader>
                    <CardTitle>Tren Biaya Bulanan</CardTitle>
                    <CardDescription>Visualisasi pengeluaran 6 bulan terakhir</CardDescription>
                </CardHeader>
                <CardContent>
                    <ResponsiveContainer width="100%" height={300}>
                        <AreaChart data={trends}>
                            <defs>
                                <linearGradient id="colorCost" x1="0" y1="0" x2="0" y2="1">
                                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.3} />
                                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0} />
                                </linearGradient>
                            </defs>
                            <CartesianGrid strokeDasharray="3 3" opacity={0.3} />
                            <XAxis
                                dataKey="month"
                                tick={{ fontSize: 12 }}
                                axisLine={false}
                            />
                            <YAxis
                                tickFormatter={(value) => formatCurrencyShort(value)}
                                tick={{ fontSize: 12 }}
                                axisLine={false}
                            />
                            <Tooltip
                                formatter={(value) => [formatCurrency(value as number ?? 0), 'Biaya']}
                                labelFormatter={(label) => `Bulan: ${label}`}
                                contentStyle={{
                                    borderRadius: '8px',
                                    border: '1px solid #e5e7eb',
                                }}
                            />
                            <Area
                                type="monotone"
                                dataKey="totalCost"
                                stroke="#3b82f6"
                                strokeWidth={2}
                                fill="url(#colorCost)"
                            />
                        </AreaChart>
                    </ResponsiveContainer>
                </CardContent>
            </Card>

            {/* Cost Logs Table */}
            <Card>
                <CardHeader>
                    <CardTitle>Riwayat Pengeluaran</CardTitle>
                    <CardDescription>Log detail biaya penggunaan material</CardDescription>
                </CardHeader>
                <CardContent>
                    <Table>
                        <TableHeader>
                            <TableRow>
                                <TableHead>Tanggal</TableHead>
                                <TableHead>Training</TableHead>
                                <TableHead>Peserta</TableHead>
                                <TableHead>Sets</TableHead>
                                <TableHead className="text-right">Total Biaya</TableHead>
                                <TableHead className="text-center">Aksi</TableHead>
                            </TableRow>
                        </TableHeader>
                        <TableBody>
                            {logs.length === 0 ? (
                                <TableRow>
                                    <TableCell colSpan={6} className="text-center py-8 text-muted-foreground">
                                        Belum ada data pengeluaran
                                    </TableCell>
                                </TableRow>
                            ) : (
                                logs.map((log) => (
                                    <TableRow key={log.id}>
                                        <TableCell>
                                            {format(new Date(log.executedAt), 'dd MMM yyyy HH:mm', { locale: localeID })}
                                        </TableCell>
                                        <TableCell className="font-medium">{log.trainingName}</TableCell>
                                        <TableCell>
                                            <div className="flex items-center">
                                                <Users className="h-4 w-4 mr-1 text-muted-foreground" />
                                                {log.participants}
                                            </div>
                                        </TableCell>
                                        <TableCell>{log.setsUsed}x</TableCell>
                                        <TableCell className="text-right font-medium">
                                            {formatCurrency(log.totalCost)}
                                        </TableCell>
                                        <TableCell className="text-center">
                                            <Button
                                                variant="ghost"
                                                size="sm"
                                                onClick={() => handleViewDetail(log)}
                                            >
                                                <Eye className="h-4 w-4 mr-1" />
                                                Detail
                                            </Button>
                                        </TableCell>
                                    </TableRow>
                                ))
                            )}
                        </TableBody>
                    </Table>

                    {/* Pagination */}
                    {pagination && pagination.totalPages > 1 && (
                        <div className="flex items-center justify-between mt-4">
                            <p className="text-sm text-muted-foreground">
                                Menampilkan {((pagination.page - 1) * pagination.limit) + 1} - {Math.min(pagination.page * pagination.limit, pagination.total)} dari {pagination.total} data
                            </p>
                            <div className="flex items-center space-x-2">
                                <Button
                                    variant="outline"
                                    size="sm"
                                    onClick={() => setPage(page - 1)}
                                    disabled={page <= 1}
                                >
                                    <ChevronLeft className="h-4 w-4" />
                                </Button>
                                <span className="text-sm">
                                    Hal {pagination.page} / {pagination.totalPages}
                                </span>
                                <Button
                                    variant="outline"
                                    size="sm"
                                    onClick={() => setPage(page + 1)}
                                    disabled={page >= pagination.totalPages}
                                >
                                    <ChevronRight className="h-4 w-4" />
                                </Button>
                            </div>
                        </div>
                    )}
                </CardContent>
            </Card>

            {/* Detail Dialog */}
            <Dialog open={detailDialogOpen} onOpenChange={setDetailDialogOpen}>
                <DialogContent className="max-w-3xl max-h-[85vh] overflow-y-auto">
                    <DialogHeader>
                        <DialogTitle>Detail Pengeluaran</DialogTitle>
                        <DialogDescription>
                            {selectedLog?.trainingName} - {selectedLog && format(new Date(selectedLog.executedAt), 'dd MMMM yyyy HH:mm', { locale: localeID })}
                        </DialogDescription>
                    </DialogHeader>

                    {selectedLog && (
                        <div className="space-y-4">
                            {/* Summary */}
                            <div className="grid grid-cols-3 gap-4">
                                <div className="text-center p-3 bg-muted rounded-lg">
                                    <p className="text-sm text-muted-foreground">Peserta</p>
                                    <p className="text-lg font-bold">{selectedLog.participants}</p>
                                </div>
                                <div className="text-center p-3 bg-muted rounded-lg">
                                    <p className="text-sm text-muted-foreground">Sets</p>
                                    <p className="text-lg font-bold">{selectedLog.setsUsed}x</p>
                                </div>
                                <div className="text-center p-3 bg-primary/10 rounded-lg">
                                    <p className="text-sm text-muted-foreground">Total Biaya</p>
                                    <p className="text-lg font-bold text-primary">{formatCurrency(selectedLog.totalCost)}</p>
                                </div>
                            </div>

                            {/* Items Table */}
                            <div className="overflow-x-auto">
                                <h4 className="font-medium mb-2">Rincian Item</h4>
                                <Table>
                                    <TableHeader>
                                        <TableRow>
                                            <TableHead>Item</TableHead>
                                            <TableHead>Tipe</TableHead>
                                            <TableHead className="text-right">Qty</TableHead>
                                            <TableHead className="text-right">Unit Cost</TableHead>
                                            <TableHead className="text-right">Subtotal</TableHead>
                                        </TableRow>
                                    </TableHeader>
                                    <TableBody>
                                        {selectedLog.items?.map((item) => (
                                            <TableRow key={item.id}>
                                                <TableCell className="font-medium">{item.itemName}</TableCell>
                                                <TableCell>
                                                    <Badge variant="outline">{item.itemType}</Badge>
                                                </TableCell>
                                                <TableCell className="text-right">
                                                    {Number(item.quantity).toFixed(2)} {item.unit}
                                                </TableCell>
                                                <TableCell className="text-right">
                                                    {formatCurrency(item.unitCost)}
                                                </TableCell>
                                                <TableCell className="text-right font-medium">
                                                    {formatCurrency(item.totalCost)}
                                                </TableCell>
                                            </TableRow>
                                        ))}
                                    </TableBody>
                                </Table>
                            </div>

                            {selectedLog.notes && (
                                <div>
                                    <h4 className="font-medium mb-1">Catatan</h4>
                                    <p className="text-sm text-muted-foreground">{selectedLog.notes}</p>
                                </div>
                            )}
                        </div>
                    )}
                </DialogContent>
            </Dialog>
        </div>
    );
}

"use client"

import { useState, useEffect } from "react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Textarea } from "@/components/ui/textarea"
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select"
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "@/components/ui/dialog"
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from "@/components/ui/table"
import { Search, ClipboardList, Loader2, RefreshCw, Plus, Trash2 } from "lucide-react"
import {
    AlertDialog,
    AlertDialogAction,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle,
} from "@/components/ui/alert-dialog"
import { useFetchPaginated, useMutation } from "@/hooks/use-api"
import { Pagination } from "@/components/ui/pagination"
import { SearchableSelect } from "@/components/ui/searchable-select"
import { useAuth } from "@/components/providers/auth-provider"

interface UsageLog {
    id: string
    date: string
    usageItem: string
    itemType: string
    quantityUsed: string
    unit: string | null
    notes: string | null
    user?: {
        fullName: string
    }
}

// Interface for warehouse items
interface WarehouseChemical {
    id: string
    name: string
    catalogType: string
    remainingAmount: string
    sizeUnit: string
    status: string
}

interface WarehouseItem {
    id: string
    name: string
    category: string
    currentQuantity: number
    unit: string
}

const itemTypeConfig: Record<string, { label: string; color: string }> = {
    reagent: { label: "Reagen", color: "bg-purple-100 text-purple-800 dark:bg-purple-900 dark:text-purple-200" },
    standard: { label: "Standard", color: "bg-cyan-100 text-cyan-800 dark:bg-cyan-900 dark:text-cyan-200" },
    sample: { label: "Sample", color: "bg-amber-100 text-amber-800 dark:bg-amber-900 dark:text-amber-200" },
    consumable: { label: "Consumable", color: "bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200" },
}

export default function UsageLogsPage() {
    const { user } = useAuth()
    const [typeFilter, setTypeFilter] = useState<string>("all")
    const [isAddDialogOpen, setIsAddDialogOpen] = useState(false)
    const [deleteId, setDeleteId] = useState<string | null>(null)
    const [isDeleting, setIsDeleting] = useState(false)

    // Warehouse items state
    const [warehouseChemicals, setWarehouseChemicals] = useState<WarehouseChemical[]>([])
    const [warehouseItems, setWarehouseItems] = useState<WarehouseItem[]>([])
    const [isLoadingWarehouse, setIsLoadingWarehouse] = useState(false)

    // Form state
    const [formData, setFormData] = useState({
        usageItem: "",
        warehouseItemId: "",
        itemType: "",
        quantityUsed: "",
        unit: "",
        notes: "",
        date: new Date().toISOString().split("T")[0],
    })

    // Fetch warehouse data when dialog opens
    useEffect(() => {
        if (isAddDialogOpen) {
            fetchWarehouseData()
        }
    }, [isAddDialogOpen])

    const fetchWarehouseData = async () => {
        setIsLoadingWarehouse(true)
        try {
            // Fetch warehouse chemicals (reagent & standard) - all items
            const chemicalsRes = await fetch("/api/inventory/warehouse-chemicals?limit=all")
            const chemicalsData = await chemicalsRes.json()
            if (chemicalsData.data) {
                // Filter by stock availability (remainingAmount > 0 and status tersedia)
                const availableChemicals = chemicalsData.data.filter(
                    (c: WarehouseChemical) => parseFloat(c.remainingAmount) > 0 && c.status === "tersedia"
                )
                setWarehouseChemicals(availableChemicals)
            }

            // Fetch warehouse items (consumable) - all items
            const itemsRes = await fetch("/api/inventory/warehouse-items?category=consumable&limit=all")
            const itemsData = await itemsRes.json()
            if (itemsData.data) {
                // Filter by stock availability (currentQuantity > 0)
                const availableItems = itemsData.data.filter(
                    (i: WarehouseItem) => i.currentQuantity > 0
                )
                setWarehouseItems(availableItems)
            }
        } catch (error) {
            console.error("Error fetching warehouse data:", error)
        } finally {
            setIsLoadingWarehouse(false)
        }
    }

    // Get filtered items based on selected type and convert to SearchableSelect options
    const getFilteredWarehouseOptions = () => {
        if (formData.itemType === "reagent") {
            return warehouseChemicals
                .filter(c => c.catalogType === "reagent")
                .map(c => ({
                    value: c.id,
                    label: `${c.name} (${c.remainingAmount} ${c.sizeUnit})`,
                    category: c.catalogType,
                }))
        } else if (formData.itemType === "standard") {
            return warehouseChemicals
                .filter(c => c.catalogType === "standard")
                .map(c => ({
                    value: c.id,
                    label: `${c.name} (${c.remainingAmount} ${c.sizeUnit})`,
                    category: c.catalogType,
                }))
        } else if (formData.itemType === "sample") {
            return warehouseChemicals
                .filter(c => c.catalogType === "sample")
                .map(c => ({
                    value: c.id,
                    label: `${c.name} (${c.remainingAmount} ${c.sizeUnit})`,
                    category: c.catalogType,
                }))
        } else if (formData.itemType === "consumable") {
            return warehouseItems
                .filter(i => i.category === "consumable")
                .map(i => ({
                    value: i.id,
                    label: `${i.name} (${i.currentQuantity} ${i.unit})`,
                    category: i.category,
                }))
        }
        return []
    }

    const warehouseSelectOptions = getFilteredWarehouseOptions()

    // Handle item selection
    const handleItemSelect = (itemId: string) => {
        let selectedItem: { name: string; unit: string } | null = null

        if (formData.itemType === "reagent" || formData.itemType === "standard" || formData.itemType === "sample") {
            const chemical = warehouseChemicals.find(c => c.id === itemId)
            if (chemical) {
                selectedItem = { name: chemical.name, unit: chemical.sizeUnit }
            }
        } else if (formData.itemType === "consumable") {
            const item = warehouseItems.find(i => i.id === itemId)
            if (item) {
                selectedItem = { name: item.name, unit: item.unit }
            }
        }

        if (selectedItem) {
            setFormData({
                ...formData,
                warehouseItemId: itemId,
                usageItem: selectedItem.name,
                unit: selectedItem.unit,
            })
        }
    }

    // Handle type change - reset item selection
    const handleTypeChange = (value: string) => {
        setFormData({
            ...formData,
            itemType: value,
            warehouseItemId: "",
            usageItem: "",
            unit: "",
        })
    }

    // Get available stock for selected item
    const getAvailableStock = (): number => {
        if (!formData.warehouseItemId) return 0

        if (formData.itemType === "reagent" || formData.itemType === "standard" || formData.itemType === "sample") {
            const chemical = warehouseChemicals.find(c => c.id === formData.warehouseItemId)
            return chemical ? parseFloat(chemical.remainingAmount) : 0
        } else if (formData.itemType === "consumable") {
            const item = warehouseItems.find(i => i.id === formData.warehouseItemId)
            return item ? item.currentQuantity : 0
        }
        return 0
    }

    const availableStock = getAvailableStock()
    const requestedQuantity = parseFloat(formData.quantityUsed) || 0
    const isStockInsufficient = Boolean(formData.warehouseItemId && requestedQuantity > availableStock)

    // Fetch usage logs from API with pagination
    const { data: usageLogs, pagination, isLoading, isFetching, error, refetch, search, setSearch, setPage } = useFetchPaginated<UsageLog>(
        "/api/inventory/usage-logs",
        { itemType: typeFilter }
    )
    const displayLogs = usageLogs || []

    // Create mutation
    const createMutation = useMutation<UsageLog, typeof formData & { userId?: string }>(
        "/api/inventory/usage-logs",
        "POST",
        {
            onSuccess: () => {
                setIsAddDialogOpen(false)
                setFormData({
                    usageItem: "",
                    warehouseItemId: "",
                    itemType: "",
                    quantityUsed: "",
                    unit: "",
                    notes: "",
                    date: new Date().toISOString().split("T")[0],
                })
                refetch()
            }
        }
    )

    const handleSubmit = async () => {
        if (!formData.usageItem || !formData.itemType || !formData.quantityUsed || !user?.id) {
            return
        }
        await createMutation.mutate({
            ...formData,
            userId: user.id,
        } as Parameters<typeof createMutation.mutate>[0])
    }

    const handleDelete = async () => {
        if (!deleteId) return
        setIsDeleting(true)
        try {
            const res = await fetch(`/api/inventory/usage-logs/${deleteId}`, { method: "DELETE" })
            if (!res.ok) throw new Error("Gagal menghapus")
            refetch()
        } catch (err) {
            console.error(err)
        } finally {
            setIsDeleting(false)
            setDeleteId(null)
        }
    }

    // Loading state
    if (isLoading) {
        return (
            <div className="flex flex-col items-center justify-center py-24">
                <Loader2 className="h-8 w-8 animate-spin text-primary mb-4" />
                <p className="text-muted-foreground">Memuat data usage logs...</p>
            </div>
        )
    }

    // Error state
    if (error) {
        return (
            <div className="flex flex-col items-center justify-center py-24">
                <p className="text-destructive mb-4">{error}</p>
                <Button onClick={refetch} variant="outline">
                    <RefreshCw className="h-4 w-4 mr-2" />
                    Coba Lagi
                </Button>
            </div>
        )
    }


    return (
        <div className="space-y-6">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight">Log Penggunaan</h1>
                    <p className="text-muted-foreground">
                        Riwayat penggunaan bahan dan peralatan laboratorium
                    </p>
                </div>
                <Dialog open={isAddDialogOpen} onOpenChange={setIsAddDialogOpen}>
                    <DialogTrigger asChild>
                        <Button>
                            <Plus className="mr-2 h-4 w-4" />
                            Tambah Log
                        </Button>
                    </DialogTrigger>
                    <DialogContent className="max-w-lg">
                        <DialogHeader>
                            <DialogTitle>Tambah Log Penggunaan</DialogTitle>
                            <DialogDescription>
                                Catat penggunaan bahan atau peralatan laboratorium
                            </DialogDescription>
                        </DialogHeader>
                        <div className="grid gap-4 py-4">
                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-2">
                                    <Label htmlFor="itemType">Tipe Item *</Label>
                                    <Select
                                        value={formData.itemType}
                                        onValueChange={handleTypeChange}
                                    >
                                        <SelectTrigger>
                                            <SelectValue placeholder="Pilih tipe" />
                                        </SelectTrigger>
                                        <SelectContent>
                                            <SelectItem value="reagent">Reagen</SelectItem>
                                            <SelectItem value="standard">Standard</SelectItem>
                                            <SelectItem value="sample">Sample</SelectItem>
                                            <SelectItem value="consumable">Consumable</SelectItem>
                                        </SelectContent>
                                    </Select>
                                </div>
                                <div className="space-y-2">
                                    <Label htmlFor="date">Tanggal</Label>
                                    <Input
                                        id="date"
                                        type="date"
                                        value={formData.date}
                                        onChange={(e) => setFormData({ ...formData, date: e.target.value })}
                                    />
                                </div>
                            </div>
                            <div className="space-y-2">
                                <Label htmlFor="usageItem">Nama Item *</Label>
                                <SearchableSelect
                                    options={warehouseSelectOptions}
                                    value={formData.warehouseItemId}
                                    onValueChange={handleItemSelect}
                                    placeholder={
                                        isLoadingWarehouse
                                            ? "Memuat data..."
                                            : !formData.itemType
                                                ? "Pilih tipe item terlebih dahulu"
                                                : "Pilih atau cari item..."
                                    }
                                    searchPlaceholder="Ketik untuk mencari..."
                                    disabled={!formData.itemType}
                                    isLoading={isLoadingWarehouse}
                                />
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-2">
                                    <Label htmlFor="quantityUsed">Jumlah Digunakan *</Label>
                                    <Input
                                        id="quantityUsed"
                                        type="number"
                                        placeholder="10"
                                        value={formData.quantityUsed}
                                        onChange={(e) => setFormData({ ...formData, quantityUsed: e.target.value })}
                                    />
                                </div>
                                <div className="space-y-2">
                                    <Label htmlFor="unit">Satuan</Label>
                                    <Input
                                        id="unit"
                                        value={formData.unit}
                                        disabled
                                        placeholder="Auto-fill dari item"
                                        className="bg-muted"
                                    />
                                </div>
                            </div>
                            <div className="space-y-2">
                                <Label htmlFor="notes">Keterangan</Label>
                                <Textarea
                                    id="notes"
                                    placeholder="Catatan penggunaan (opsional)"
                                    value={formData.notes}
                                    onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
                                    rows={3}
                                />
                            </div>
                            {isStockInsufficient && (
                                <div className="p-3 bg-destructive/10 border border-destructive/20 rounded-md text-sm text-destructive">
                                    ΓÜá∩╕Å Stok tidak mencukupi! Tersedia: {availableStock} {formData.unit}, Diminta: {requestedQuantity} {formData.unit}
                                </div>
                            )}
                        </div>
                        <DialogFooter>
                            <Button variant="outline" onClick={() => setIsAddDialogOpen(false)}>
                                Batal
                            </Button>
                            <Button
                                onClick={handleSubmit}
                                disabled={createMutation.isLoading || !formData.usageItem || !formData.itemType || !formData.quantityUsed || isStockInsufficient}
                            >
                                {createMutation.isLoading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                                Simpan
                            </Button>
                        </DialogFooter>
                    </DialogContent>
                </Dialog>
            </div>

            {/* Filters */}
            <div className="flex gap-4">
                <div className="relative flex-1 max-w-sm">
                    <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
                    <Input
                        placeholder="Cari Item"
                        value={search}
                        onChange={(e) => setSearch(e.target.value)}
                        className="pl-9"
                    />
                </div>
                <Select value={typeFilter} onValueChange={setTypeFilter}>
                    <SelectTrigger className="w-[180px]">
                        <SelectValue placeholder="Tipe Item" />
                    </SelectTrigger>
                    <SelectContent>
                        <SelectItem value="all">Semua Tipe</SelectItem>
                        <SelectItem value="reagent">Reagen</SelectItem>
                        <SelectItem value="standard">Standard</SelectItem>
                        <SelectItem value="sample">Sample</SelectItem>
                        <SelectItem value="consumable">Consumable</SelectItem>
                    </SelectContent>
                </Select>
            </div>

            {/* Table */}
            <div className="rounded-md border">
                <Table>
                    <TableHeader>
                        <TableRow>
                            <TableHead>Tanggal</TableHead>
                            <TableHead>Pengguna</TableHead>
                            <TableHead>Item</TableHead>
                            <TableHead>Tipe</TableHead>
                            <TableHead className="text-right">Jumlah</TableHead>
                            <TableHead>Keterangan</TableHead>
                            <TableHead className="text-center">Aksi</TableHead>
                        </TableRow>
                    </TableHeader>
                    <TableBody>
                        {displayLogs.map((log) => (
                            <TableRow key={log.id}>
                                <TableCell>{new Date(log.date).toLocaleDateString("id-ID")}</TableCell>
                                <TableCell className="font-medium">{log.user?.fullName || "-"}</TableCell>
                                <TableCell>{log.usageItem}</TableCell>
                                <TableCell>
                                    <span className={`px-2 py-1 rounded-full text-xs font-medium ${itemTypeConfig[log.itemType]?.color || "bg-gray-100 text-gray-800"}`}>
                                        {itemTypeConfig[log.itemType]?.label || log.itemType}
                                    </span>
                                </TableCell>
                                <TableCell className="text-right">
                                    {log.quantityUsed} {log.unit || ""}
                                </TableCell>
                                <TableCell className="text-muted-foreground">{log.notes || "-"}</TableCell>
                                <TableCell className="text-center">
                                    <Button
                                        variant="ghost"
                                        size="icon"
                                        className="text-destructive hover:text-destructive"
                                        onClick={() => setDeleteId(log.id)}
                                    >
                                        <Trash2 className="h-4 w-4" />
                                    </Button>
                                </TableCell>
                            </TableRow>
                        ))}
                    </TableBody>
                </Table>
            </div>

            {displayLogs.length === 0 && (
                <div className="flex flex-col items-center justify-center py-12 text-center">
                    <ClipboardList className="h-12 w-12 text-muted-foreground/50 mb-4" />
                    <p className="text-muted-foreground">Tidak ada log ditemukan</p>
                </div>
            )}

            {/* Pagination */}
            {pagination.totalPages > 1 && (
                <Pagination
                    pagination={pagination}
                    onPageChange={setPage}
                />
            )}

            {/* Delete Confirmation Dialog */}
            <AlertDialog open={!!deleteId} onOpenChange={() => setDeleteId(null)}>
                <AlertDialogContent>
                    <AlertDialogHeader>
                        <AlertDialogTitle>Hapus Log?</AlertDialogTitle>
                        <AlertDialogDescription>
                            Apakah Anda yakin ingin menghapus log penggunaan ini? Tindakan ini tidak dapat dibatalkan.
                        </AlertDialogDescription>
                    </AlertDialogHeader>
                    <AlertDialogFooter>
                        <AlertDialogCancel disabled={isDeleting}>Batal</AlertDialogCancel>
                        <AlertDialogAction
                            onClick={handleDelete}
                            disabled={isDeleting}
                            className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
                        >
                            {isDeleting ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : null}
                            Hapus
                        </AlertDialogAction>
                    </AlertDialogFooter>
                </AlertDialogContent>
            </AlertDialog>
        </div>
    )
}

"use client"

import { toast } from "sonner"
import { useState } from "react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Badge } from "@/components/ui/badge"
import { Label } from "@/components/ui/label"
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select"
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "@/components/ui/dialog"
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from "@/components/ui/table"
import { Plus, Search, Warehouse, Loader2, RefreshCw, Trash2, Pencil } from "lucide-react"
import {
    AlertDialog,
    AlertDialogAction,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle,
} from "@/components/ui/alert-dialog"
import { WarehouseItemStatus } from "@/types"
import { useFetchPaginated, useMutation } from "@/hooks/use-api"
import { useCatalogItems } from "@/hooks/use-catalog-items"
import { Pagination } from "@/components/ui/pagination"
import { SearchableSelect } from "@/components/ui/searchable-select"

interface WarehouseChemical {
    id: string
    catalogId: string
    catalogType: string
    name: string
    receivedDate: string
    sizeValue: string
    sizeUnit: string
    remainingAmount: string
    unit: string
    expiredDate: string
    totalPrice?: string | number | null
    unitCostBase?: string | number | null
    receivedBy?: string
    receivedByName?: string | null
    receivedByUser?: { fullName: string } | null
    status: WarehouseItemStatus
    daysUntilExpiry: number
}

interface CatalogItem {
    id: string
    name: string
    category: 'reagent' | 'standard' | 'sample'
}

const statusConfig: Record<WarehouseItemStatus, { label: string; variant: "default" | "secondary" | "destructive" | "outline" }> = {
    tersedia: { label: "Tersedia", variant: "default" },
    sedang_digunakan: { label: "Sedang Digunakan", variant: "secondary" },
    habis: { label: "Habis", variant: "outline" },
}

// Static options for "Diterima Oleh" dropdown
const receivedByOptions = [
    { value: "GAP", label: "GAP" },
    { value: "KEP", label: "KEP" },
    { value: "Manager", label: "Manager" },
]

export default function WarehouseChemicalsPage() {
    const [statusFilter, setStatusFilter] = useState<string>("all")
    const [typeFilter, setTypeFilter] = useState<string>("all")
    const [sortBy, setSortBy] = useState<string>("fefo")
    const [isAddDialogOpen, setIsAddDialogOpen] = useState(false)
    const [isEditDialogOpen, setIsEditDialogOpen] = useState(false)
    const [editItem, setEditItem] = useState<WarehouseChemical | null>(null)
    const [isEditLoading, setIsEditLoading] = useState(false)
    const [deleteId, setDeleteId] = useState<string | null>(null)
    const [isDeleting, setIsDeleting] = useState(false)

    // Edit form state
    const [editFormData, setEditFormData] = useState({
        sizeValue: "",
        sizeUnit: "ml",
        remainingAmount: "",
        unit: "ml",
        expiredDate: "",
        receivedByName: "",
        totalPrice: "",
    })

    // Form state
    const [formData, setFormData] = useState({
        catalogId: "",
        catalogType: "",
        name: "",
        amount: "",
        unit: "ml",
        expDate: "",
        receivedBy: "",
        totalPrice: "",
    })

    // Fetch catalogs with caching - reagents and standards
    const { items: reagentCatalog, isLoading: isLoadingReagents } = useCatalogItems(
        "/api/inventory/reagents",
        {
            transform: (data: unknown) => {
                const d = data as { data?: Array<{ id: string; reagentName: string }> }
                return (d.data || []).map(r => ({
                    id: r.id,
                    name: r.reagentName,
                    category: 'reagent',
                }))
            }
        }
    )

    const { items: standardCatalog, isLoading: isLoadingStandards } = useCatalogItems(
        "/api/inventory/standards",
        {
            transform: (data: unknown) => {
                const d = data as { data?: Array<{ id: string; standardName: string }> }
                return (d.data || []).map(s => ({
                    id: s.id,
                    name: s.standardName,
                    category: 'standard',
                }))
            }
        }
    )

    const { items: sampleCatalog, isLoading: isLoadingSamples } = useCatalogItems(
        "/api/inventory/samples",
        {
            transform: (data: unknown) => {
                const d = data as { data?: Array<{ id: string; sampleName: string }> }
                return (d.data || []).map(s => ({
                    id: s.id,
                    name: s.sampleName,
                    category: 'sample' as const,
                }))
            }
        }
    )

    // Combine catalogs
    const catalogItems = [...reagentCatalog, ...standardCatalog, ...sampleCatalog]
    const isLoadingCatalog = isLoadingReagents || isLoadingStandards || isLoadingSamples

    // Fetch warehouse chemicals from API with pagination
    const { data: chemicals, pagination, isLoading, isFetching, error, refetch, search, setSearch, setPage } = useFetchPaginated<WarehouseChemical>(
        "/api/inventory/warehouse-chemicals",
        { status: statusFilter, catalogType: typeFilter, sortBy }
    )
    const displayItems = chemicals || []

    // Create mutation
    const createChemical = useMutation<WarehouseChemical, object>(
        "/api/inventory/warehouse-chemicals",
        "POST",
        {
            onSuccess: () => {
                refetch()
                setIsAddDialogOpen(false)
                setFormData({ catalogId: "", catalogType: "", name: "", amount: "", unit: "ml", expDate: "", receivedBy: "", totalPrice: "" })
            },
        }
    )

    // Handle catalog selection
    const handleCatalogSelect = (catalogId: string) => {
        const selected = catalogItems.find(c => c.id === catalogId)
        if (selected) {
            setFormData({
                ...formData,
                catalogId: selected.id,
                catalogType: selected.category,
                name: selected.name,
            })
        }
    }

    // Filter catalog items by type and convert to SearchableSelect options
    const catalogSelectOptions = (formData.catalogType
        ? catalogItems.filter(c => c.category === formData.catalogType)
        : catalogItems
    ).map(item => ({
        value: item.id,
        label: item.name,
        category: item.category,
    }))

    const handleSubmit = async () => {
        if (!formData.catalogId || !formData.amount || !formData.expDate) {
            return
        }
        // Calculate unitCostBase from totalPrice and amount
        const totalPrice = formData.totalPrice ? parseFloat(formData.totalPrice) : null;
        const amount = parseFloat(formData.amount);
        const unitCostBase = totalPrice && amount ? totalPrice / amount : null;

        await createChemical.mutate({
            catalogId: formData.catalogId,
            catalogType: formData.catalogType,
            name: formData.name,
            receivedDate: new Date().toISOString().split("T")[0],
            sizeValue: formData.amount,
            sizeUnit: formData.unit,
            remainingAmount: formData.amount,
            unit: formData.unit,
            expiredDate: formData.expDate,
            totalPrice: totalPrice,
            unitCostBase: unitCostBase,
            receivedByName: formData.receivedBy,
            status: "tersedia",
        })
    }

    const handleDelete = async () => {
        if (!deleteId) return
        setIsDeleting(true)
        try {
            const res = await fetch(`/api/inventory/warehouse-chemicals/${deleteId}`, { method: "DELETE" })
            if (!res.ok) throw new Error("Gagal menghapus")
            refetch()
        } catch (err) {
            console.error(err)
        } finally {
            setIsDeleting(false)
            setDeleteId(null)
        }
    }

    const handleEdit = (item: WarehouseChemical) => {
        setEditItem(item)
        setEditFormData({
            sizeValue: item.sizeValue || "",
            sizeUnit: item.sizeUnit || "ml",
            remainingAmount: item.remainingAmount || "",
            unit: item.unit || "ml",
            expiredDate: item.expiredDate || "",
            receivedByName: item.receivedByName || "",
            totalPrice: item.totalPrice?.toString() || "",
        })
        setIsEditDialogOpen(true)
    }

    const handleEditSubmit = async () => {
        if (!editItem) return

        setIsEditLoading(true)
        try {
            const response = await fetch(`/api/inventory/warehouse-chemicals/${editItem.id}`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(editFormData),
            })

            if (!response.ok) {
                const errorData = await response.json()
                throw new Error(errorData.error || 'Gagal menyimpan')
            }

            toast.success('Item berhasil diperbarui')
            setIsEditDialogOpen(false)
            setEditItem(null)
            refetch()
        } catch (error) {
            toast.error(error instanceof Error ? error.message : 'Terjadi kesalahan')
        } finally {
            setIsEditLoading(false)
        }
    }

    // Loading state
    if (isLoading) {
        return (
            <div className="flex items-center justify-center h-64">
                <Loader2 className="h-8 w-8 animate-spin text-primary" />
                <span className="ml-2 text-muted-foreground">Memuat data warehouse chemicals...</span>
            </div>
        )
    }

    // Error state
    if (error) {
        return (
            <div className="flex flex-col items-center justify-center h-64 space-y-4">
                <p className="text-destructive">{error}</p>
                <Button variant="outline" onClick={() => refetch()}>
                    <RefreshCw className="mr-2 h-4 w-4" />
                    Coba Lagi
                </Button>
            </div>
        )
    }

    return (
        <div className="space-y-6">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight">Gudang Reagen & Standar</h1>
                    <p className="text-muted-foreground">
                        Detail stok per batch reagen dan larutan standar
                    </p>
                </div>
                <Dialog open={isAddDialogOpen} onOpenChange={setIsAddDialogOpen}>
                    <DialogTrigger asChild>
                        <Button>
                            <Plus className="mr-2 h-4 w-4" />
                            Terima Barang Baru
                        </Button>
                    </DialogTrigger>
                    <DialogContent className="max-w-lg">
                        <DialogHeader>
                            <DialogTitle>Terima Barang Baru</DialogTitle>
                            <DialogDescription>
                                Masukkan informasi batch baru yang diterima
                            </DialogDescription>
                        </DialogHeader>
                        <div className="grid gap-4 py-4">
                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-2">
                                    <Label htmlFor="catalogType">Tipe Katalog</Label>
                                    <Select
                                        value={formData.catalogType}
                                        onValueChange={(value) => setFormData({ ...formData, catalogType: value, catalogId: "", name: "" })}
                                    >
                                        <SelectTrigger>
                                            <SelectValue placeholder="Pilih tipe" />
                                        </SelectTrigger>
                                        <SelectContent>
                                            <SelectItem value="reagent">Reagen</SelectItem>
                                            <SelectItem value="standard">Standard</SelectItem>
                                            <SelectItem value="sample">Sample</SelectItem>
                                        </SelectContent>
                                    </Select>
                                </div>
                                <div className="space-y-2">
                                    <Label htmlFor="catalogItem">Pilih Item Katalog</Label>
                                    <SearchableSelect
                                        options={catalogSelectOptions}
                                        value={formData.catalogId}
                                        onValueChange={handleCatalogSelect}
                                        placeholder={formData.catalogType ? "Pilih atau cari item..." : "Pilih tipe dulu"}
                                        searchPlaceholder="Ketik untuk mencari..."
                                        disabled={!formData.catalogType}
                                        isLoading={isLoadingCatalog}
                                    />
                                </div>
                            </div>
                            {formData.name && (
                                <div className="p-3 bg-muted rounded-lg">
                                    <p className="text-sm text-muted-foreground">Item terpilih:</p>
                                    <p className="font-medium">{formData.name}</p>
                                </div>
                            )}
                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-2">
                                    <Label htmlFor="amount">Jumlah</Label>
                                    <div className="flex gap-2">
                                        <Input
                                            id="amount"
                                            type="number"
                                            placeholder="2500"
                                            value={formData.amount}
                                            onChange={(e) => setFormData({ ...formData, amount: e.target.value })}
                                        />
                                        <Select
                                            value={formData.unit}
                                            onValueChange={(value) => setFormData({ ...formData, unit: value })}
                                        >
                                            <SelectTrigger className="w-20">
                                                <SelectValue />
                                            </SelectTrigger>
                                            <SelectContent>
                                                <SelectItem value="ml">ml</SelectItem>
                                                <SelectItem value="L">L</SelectItem>
                                                <SelectItem value="g">g</SelectItem>
                                                <SelectItem value="kg">kg</SelectItem>
                                            </SelectContent>
                                        </Select>
                                    </div>
                                </div>
                                <div className="space-y-2">
                                    <Label htmlFor="expDate">Tanggal Expired</Label>
                                    <Input
                                        id="expDate"
                                        type="date"
                                        value={formData.expDate}
                                        onChange={(e) => setFormData({ ...formData, expDate: e.target.value })}
                                    />
                                </div>
                            </div>
                            {/* Diterima Oleh Dropdown */}
                            <div className="space-y-2">
                                <Label htmlFor="receivedBy">Diterima Oleh</Label>
                                <Select
                                    value={formData.receivedBy}
                                    onValueChange={(value) => setFormData({ ...formData, receivedBy: value })}
                                >
                                    <SelectTrigger>
                                        <SelectValue placeholder="Pilih penerima" />
                                    </SelectTrigger>
                                    <SelectContent>
                                        {receivedByOptions.map((option) => (
                                            <SelectItem key={option.value} value={option.value}>
                                                {option.label}
                                            </SelectItem>
                                        ))}
                                    </SelectContent>
                                </Select>
                            </div>
                            {/* Harga per Botol */}
                            <div className="space-y-2">
                                <Label htmlFor="totalPrice">Harga per Botol (Rp)</Label>
                                <Input
                                    id="totalPrice"
                                    type="number"
                                    placeholder="Contoh: 500000"
                                    value={formData.totalPrice}
                                    onChange={(e) => setFormData({ ...formData, totalPrice: e.target.value })}
                                />
                                <p className="text-xs text-muted-foreground">
                                    Harga satuan per botol/kemasan untuk perhitungan biaya training
                                    {formData.totalPrice && formData.amount && (
                                        <span className="ml-2 text-primary font-medium">
                                            (Rp {(parseFloat(formData.totalPrice) / parseFloat(formData.amount)).toFixed(2)}/{formData.unit})
                                        </span>
                                    )}
                                </p>
                            </div>
                        </div>
                        <DialogFooter>
                            <Button variant="outline" onClick={() => setIsAddDialogOpen(false)}>
                                Batal
                            </Button>
                            <Button
                                onClick={handleSubmit}
                                disabled={createChemical.isLoading || !formData.catalogId || !formData.amount || !formData.expDate}
                            >
                                {createChemical.isLoading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                                Simpan
                            </Button>
                        </DialogFooter>
                    </DialogContent>
                </Dialog>
            </div>

            {/* Filters */}
            <div className="flex gap-4">
                <div className="relative flex-1 max-w-sm">
                    <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
                    <Input
                        placeholder="Cari nama item..."
                        value={search}
                        onChange={(e) => setSearch(e.target.value)}
                        className="pl-9"
                    />
                </div>
                <Select value={typeFilter} onValueChange={setTypeFilter}>
                    <SelectTrigger className="w-[180px]">
                        <SelectValue placeholder="Tipe" />
                    </SelectTrigger>
                    <SelectContent>
                        <SelectItem value="all">Semua Tipe</SelectItem>
                        <SelectItem value="reagent">Reagen</SelectItem>
                        <SelectItem value="standard">Standard</SelectItem>
                        <SelectItem value="sample">Sample</SelectItem>
                    </SelectContent>
                </Select>
                <Select value={statusFilter} onValueChange={setStatusFilter}>
                    <SelectTrigger className="w-[180px]">
                        <SelectValue placeholder="Filter Status" />
                    </SelectTrigger>
                    <SelectContent>
                        <SelectItem value="all">Semua Status</SelectItem>
                        <SelectItem value="tersedia">Tersedia</SelectItem>
                        <SelectItem value="sedang_digunakan">Sedang Digunakan</SelectItem>
                        <SelectItem value="habis">Habis</SelectItem>
                    </SelectContent>
                </Select>
                <Select value={sortBy} onValueChange={setSortBy}>
                    <SelectTrigger className="w-[180px]">
                        <SelectValue placeholder="Urutan" />
                    </SelectTrigger>
                    <SelectContent>
                        <SelectItem value="fefo">FEFO (Exp Terdekat)</SelectItem>
                        <SelectItem value="name">Nama A-Z</SelectItem>
                        <SelectItem value="newest">Terbaru Diterima</SelectItem>
                    </SelectContent>
                </Select>
                <Button variant="outline" size="icon" onClick={() => refetch()}>
                    <RefreshCw className="h-4 w-4" />
                </Button>
            </div>

            {/* Table */}
            <div className="rounded-md border">
                <Table>
                    <TableHeader>
                        <TableRow>
                            <TableHead>Nama</TableHead>
                            <TableHead>Tipe</TableHead>
                            <TableHead>Tgl Terima</TableHead>
                            <TableHead className="text-right">Sisa</TableHead>
                            <TableHead className="text-right">Ukuran</TableHead>
                            <TableHead className="text-right">Harga</TableHead>
                            <TableHead>Tgl Expired</TableHead>
                            <TableHead className="text-center">Hari</TableHead>
                            <TableHead>Status</TableHead>
                            <TableHead>Diterima Oleh</TableHead>
                            <TableHead className="text-center">Aksi</TableHead>
                        </TableRow>
                    </TableHeader>
                    <TableBody>
                        {displayItems.map((item) => (
                            <TableRow key={item.id}>
                                <TableCell className="font-medium">{item.name}</TableCell>
                                <TableCell>
                                    <span className={`px-2 py-1 rounded-full text-xs font-medium ${item.catalogType === "reagent"
                                        ? "bg-purple-100 text-purple-800 dark:bg-purple-900 dark:text-purple-200"
                                        : item.catalogType === "sample"
                                            ? "bg-amber-100 text-amber-800 dark:bg-amber-900 dark:text-amber-200"
                                            : "bg-cyan-100 text-cyan-800 dark:bg-cyan-900 dark:text-cyan-200"
                                        }`}>
                                        {item.catalogType === "reagent" ? "Reagen" : item.catalogType === "sample" ? "Sample" : "Standard"}
                                    </span>
                                </TableCell>
                                <TableCell>{new Date(item.receivedDate).toLocaleDateString("id-ID")}</TableCell>
                                <TableCell className="text-right font-medium">
                                    {item.remainingAmount} {item.sizeUnit}
                                </TableCell>
                                <TableCell className="text-right">
                                    {item.sizeValue} {item.sizeUnit}
                                </TableCell>
                                <TableCell className="text-right font-medium">
                                    {item.totalPrice ? `Rp ${Number(item.totalPrice).toLocaleString('id-ID')}` : '-'}
                                </TableCell>
                                <TableCell>{new Date(item.expiredDate).toLocaleDateString("id-ID")}</TableCell>
                                <TableCell className={`text-center font-medium ${item.daysUntilExpiry < 0 ? "text-red-600" :
                                    item.daysUntilExpiry < 30 ? "text-yellow-600" : ""
                                    }`}>
                                    {item.daysUntilExpiry < 0 ? `${Math.abs(item.daysUntilExpiry)} hari lalu` : `${item.daysUntilExpiry} hari`}
                                </TableCell>
                                <TableCell>
                                    <Badge variant={statusConfig[item.status].variant}>
                                        {statusConfig[item.status].label}
                                    </Badge>
                                </TableCell>
                                <TableCell>{item.receivedByName || item.receivedByUser?.fullName || "-"}</TableCell>
                                <TableCell className="text-center">
                                    <div className="flex justify-center gap-1">
                                        <Button
                                            variant="ghost"
                                            size="icon"
                                            onClick={() => handleEdit(item)}
                                        >
                                            <Pencil className="h-4 w-4" />
                                        </Button>
                                        <Button
                                            variant="ghost"
                                            size="icon"
                                            className="text-destructive hover:text-destructive"
                                            onClick={() => setDeleteId(item.id)}
                                        >
                                            <Trash2 className="h-4 w-4" />
                                        </Button>
                                    </div>
                                </TableCell>
                            </TableRow>
                        ))}
                    </TableBody>
                </Table>
            </div>

            {
                displayItems.length === 0 && (
                    <div className="flex flex-col items-center justify-center py-12 text-center">
                        <Warehouse className="h-12 w-12 text-muted-foreground/50 mb-4" />
                        <p className="text-muted-foreground">Tidak ada item ditemukan</p>
                    </div>
                )
            }

            {/* Pagination */}
            {pagination.totalPages > 1 && (
                <Pagination
                    pagination={pagination}
                    onPageChange={setPage}
                />
            )}

            {/* Edit Dialog */}
            <Dialog open={isEditDialogOpen} onOpenChange={setIsEditDialogOpen}>
                <DialogContent className="max-w-lg">
                    <DialogHeader>
                        <DialogTitle>Edit Item</DialogTitle>
                        <DialogDescription>
                            Edit data untuk {editItem?.name}
                        </DialogDescription>
                    </DialogHeader>
                    <div className="grid gap-4 py-4">
                        <div className="grid grid-cols-2 gap-4">
                            <div className="space-y-2">
                                <Label>Ukuran Awal</Label>
                                <div className="flex gap-2">
                                    <Input
                                        type="number"
                                        value={editFormData.sizeValue}
                                        onChange={(e) => setEditFormData({ ...editFormData, sizeValue: e.target.value })}
                                    />
                                    <Select
                                        value={editFormData.sizeUnit}
                                        onValueChange={(value) => setEditFormData({ ...editFormData, sizeUnit: value })}
                                    >
                                        <SelectTrigger className="w-20">
                                            <SelectValue />
                                        </SelectTrigger>
                                        <SelectContent>
                                            <SelectItem value="ml">ml</SelectItem>
                                            <SelectItem value="L">L</SelectItem>
                                            <SelectItem value="g">g</SelectItem>
                                            <SelectItem value="kg">kg</SelectItem>
                                        </SelectContent>
                                    </Select>
                                </div>
                            </div>
                            <div className="space-y-2">
                                <Label>Sisa Jumlah</Label>
                                <div className="flex gap-2">
                                    <Input
                                        type="number"
                                        value={editFormData.remainingAmount}
                                        onChange={(e) => setEditFormData({ ...editFormData, remainingAmount: e.target.value })}
                                    />
                                    <Select
                                        value={editFormData.unit}
                                        onValueChange={(value) => setEditFormData({ ...editFormData, unit: value })}
                                    >
                                        <SelectTrigger className="w-20">
                                            <SelectValue />
                                        </SelectTrigger>
                                        <SelectContent>
                                            <SelectItem value="ml">ml</SelectItem>
                                            <SelectItem value="L">L</SelectItem>
                                            <SelectItem value="g">g</SelectItem>
                                            <SelectItem value="kg">kg</SelectItem>
                                        </SelectContent>
                                    </Select>
                                </div>
                            </div>
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <div className="space-y-2">
                                <Label>Tanggal Expired</Label>
                                <Input
                                    type="date"
                                    value={editFormData.expiredDate}
                                    onChange={(e) => setEditFormData({ ...editFormData, expiredDate: e.target.value })}
                                />
                            </div>
                            <div className="space-y-2">
                                <Label>Diterima Oleh</Label>
                                <Select
                                    value={editFormData.receivedByName}
                                    onValueChange={(value) => setEditFormData({ ...editFormData, receivedByName: value })}
                                >
                                    <SelectTrigger>
                                        <SelectValue placeholder="Pilih penerima" />
                                    </SelectTrigger>
                                    <SelectContent>
                                        {receivedByOptions.map((opt) => (
                                            <SelectItem key={opt.value} value={opt.value}>
                                                {opt.label}
                                            </SelectItem>
                                        ))}
                                    </SelectContent>
                                </Select>
                            </div>
                        </div>
                        <div className="space-y-2">
                            <Label>Harga Per Botol (Rp)</Label>
                            <Input
                                type="number"
                                placeholder="100000"
                                value={editFormData.totalPrice}
                                onChange={(e) => setEditFormData({ ...editFormData, totalPrice: e.target.value })}
                            />
                        </div>
                    </div>
                    <DialogFooter>
                        <Button variant="outline" onClick={() => setIsEditDialogOpen(false)}>
                            Batal
                        </Button>
                        <Button onClick={handleEditSubmit} disabled={isEditLoading}>
                            {isEditLoading && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
                            Simpan
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>

            {/* Delete Confirmation Dialog */}
            <AlertDialog open={!!deleteId} onOpenChange={() => setDeleteId(null)}>
                <AlertDialogContent>
                    <AlertDialogHeader>
                        <AlertDialogTitle>Hapus Item?</AlertDialogTitle>
                        <AlertDialogDescription>
                            Apakah Anda yakin ingin menghapus item ini dari gudang? Tindakan ini tidak dapat dibatalkan.
                        </AlertDialogDescription>
                    </AlertDialogHeader>
                    <AlertDialogFooter>
                        <AlertDialogCancel disabled={isDeleting}>Batal</AlertDialogCancel>
                        <AlertDialogAction
                            onClick={handleDelete}
                            disabled={isDeleting}
                            className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
                        >
                            {isDeleting ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : null}
                            Hapus
                        </AlertDialogAction>
                    </AlertDialogFooter>
                </AlertDialogContent>
            </AlertDialog>
        </div>
    )
}

"use client"

import { useState } from "react"
import useSWR from "swr"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select"
import {
    AlertDialog,
    AlertDialogAction,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle,
} from "@/components/ui/alert-dialog"
import { Bell, Calendar, AlertTriangle, CheckCircle, Loader2, RefreshCw, ExternalLink, Check } from "lucide-react"
import { Pagination } from "@/components/ui/pagination"
import { useRouter } from "next/navigation"

interface Notification {
    id: string
    type: 'calibration_h30' | 'expired_h30' | 'maintenance_reminder' | 'calibration_scheduled'
    title: string
    message: string
    referenceId: string
    referenceType: 'instrument' | 'chemical'
    actionUrl: string | null
    isRead: boolean
    webhookSent: boolean
    dueDate: string | null
    createdAt: string
}

interface NotificationResponse {
    data: Notification[]
    pagination: {
        page: number
        limit: number
        total: number
        totalPages: number
    }
    unreadCount: number
}

const typeConfig = {
    calibration_h30: {
        label: "Kalibrasi H-30",
        icon: Calendar,
        color: "text-blue-500",
        bgColor: "bg-blue-50 dark:bg-blue-950",
        badgeVariant: "secondary" as const
    },
    expired_h30: {
        label: "Expired H-30",
        icon: AlertTriangle,
        color: "text-red-500",
        bgColor: "bg-red-50 dark:bg-red-950",
        badgeVariant: "destructive" as const
    },
    maintenance_reminder: {
        label: "Maintenance",
        icon: AlertTriangle,
        color: "text-yellow-500",
        bgColor: "bg-yellow-50 dark:bg-yellow-950",
        badgeVariant: "secondary" as const
    },
    calibration_scheduled: {
        label: "Terjadwalkan",
        icon: CheckCircle,
        color: "text-green-500",
        bgColor: "bg-green-50 dark:bg-green-950",
        badgeVariant: "default" as const
    },
}

const fetcher = (url: string) => fetch(url).then(res => res.json())

export default function NotificationsPage() {
    const router = useRouter()
    const [typeFilter, setTypeFilter] = useState<string>("all")
    const [readFilter, setReadFilter] = useState<string>("all")
    const [page, setPage] = useState(1)
    const [schedulingId, setSchedulingId] = useState<string | null>(null)
    const [isScheduling, setIsScheduling] = useState(false)
    const [confirmSchedule, setConfirmSchedule] = useState<Notification | null>(null)

    // Build URL with filters
    const params = new URLSearchParams()
    params.set('page', page.toString())
    params.set('limit', '10')
    if (typeFilter !== 'all') params.set('type', typeFilter)
    if (readFilter !== 'all') params.set('isRead', readFilter === 'read' ? 'true' : 'false')

    const { data, isLoading, error, mutate } = useSWR<NotificationResponse>(
        `/api/notifications?${params.toString()}`,
        fetcher,
        {
            refreshInterval: 60000, // Refresh every 60 seconds (was 30s)
            dedupingInterval: 30000, // Prevent duplicate requests within 30 seconds
            revalidateOnFocus: false, // Don't refetch on window focus
        }
    )

    const handleMarkAsRead = async (id: string) => {
        try {
            await fetch(`/api/notifications/${id}`, { method: 'PATCH' })
            mutate()
        } catch (err) {
            console.error('Error marking as read:', err)
        }
    }

    const handleMarkAllAsRead = async () => {
        try {
            await fetch('/api/notifications', { method: 'PATCH' })
            mutate()
        } catch (err) {
            console.error('Error marking all as read:', err)
        }
    }

    const handleScheduleCalibration = async (notification: Notification) => {
        setIsScheduling(true)
        setSchedulingId(notification.id)

        try {
            const response = await fetch('/api/notifications/webhook', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ instrumentId: notification.referenceId }),
            })

            if (!response.ok) {
                throw new Error('Failed to schedule calibration')
            }

            // Mark notification as read
            await handleMarkAsRead(notification.id)
            mutate()
            setConfirmSchedule(null)
        } catch (err) {
            console.error('Error scheduling calibration:', err)
        } finally {
            setIsScheduling(false)
            setSchedulingId(null)
        }
    }

    const formatDate = (dateStr: string) => {
        return new Date(dateStr).toLocaleDateString('id-ID', {
            year: 'numeric',
            month: 'long',
            day: 'numeric',
        })
    }

    const formatTime = (dateStr: string) => {
        return new Date(dateStr).toLocaleTimeString('id-ID', {
            hour: '2-digit',
            minute: '2-digit',
        })
    }

    if (isLoading) {
        return (
            <div className="flex flex-col items-center justify-center py-24">
                <Loader2 className="h-8 w-8 animate-spin text-primary mb-4" />
                <p className="text-muted-foreground">Memuat notifikasi...</p>
            </div>
        )
    }

    if (error) {
        return (
            <div className="flex flex-col items-center justify-center py-24">
                <p className="text-destructive mb-4">Gagal memuat notifikasi</p>
                <Button onClick={() => mutate()} variant="outline">
                    <RefreshCw className="h-4 w-4 mr-2" />
                    Coba Lagi
                </Button>
            </div>
        )
    }

    const notifications = data?.data || []
    const pagination = data?.pagination || { page: 1, limit: 10, total: 0, totalPages: 0 }
    const unreadCount = data?.unreadCount || 0

    return (
        <div className="space-y-6">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight flex items-center gap-3">
                        <Bell className="h-8 w-8" />
                        Notifikasi
                        {unreadCount > 0 && (
                            <Badge variant="destructive" className="text-sm">
                                {unreadCount} belum dibaca
                            </Badge>
                        )}
                    </h1>
                    <p className="text-muted-foreground">
                        Notifikasi sistem untuk kalibrasi dan expired items
                    </p>
                </div>
                {unreadCount > 0 && (
                    <Button variant="outline" onClick={handleMarkAllAsRead}>
                        <Check className="h-4 w-4 mr-2" />
                        Tandai Semua Dibaca
                    </Button>
                )}
            </div>

            {/* Filters */}
            <div className="flex gap-4">
                <Select value={typeFilter} onValueChange={setTypeFilter}>
                    <SelectTrigger className="w-[200px]">
                        <SelectValue placeholder="Filter Tipe" />
                    </SelectTrigger>
                    <SelectContent>
                        <SelectItem value="all">Semua Tipe</SelectItem>
                        <SelectItem value="calibration_h30">Kalibrasi H-30</SelectItem>
                        <SelectItem value="expired_h30">Expired H-30</SelectItem>
                        <SelectItem value="calibration_scheduled">Terjadwalkan</SelectItem>
                    </SelectContent>
                </Select>
                <Select value={readFilter} onValueChange={setReadFilter}>
                    <SelectTrigger className="w-[180px]">
                        <SelectValue placeholder="Filter Status" />
                    </SelectTrigger>
                    <SelectContent>
                        <SelectItem value="all">Semua Status</SelectItem>
                        <SelectItem value="unread">Belum Dibaca</SelectItem>
                        <SelectItem value="read">Sudah Dibaca</SelectItem>
                    </SelectContent>
                </Select>
            </div>

            {/* Notification List */}
            <div className="space-y-3">
                {notifications.length === 0 ? (
                    <Card>
                        <CardContent className="flex flex-col items-center justify-center py-12">
                            <Bell className="h-12 w-12 text-muted-foreground/50 mb-4" />
                            <p className="text-muted-foreground">Tidak ada notifikasi</p>
                        </CardContent>
                    </Card>
                ) : (
                    notifications.map((notification) => {
                        const config = typeConfig[notification.type] || typeConfig.calibration_h30
                        const Icon = config.icon

                        return (
                            <Card
                                key={notification.id}
                                className={`transition-colors ${!notification.isRead ? 'border-l-4 border-l-primary bg-muted/30' : ''}`}
                            >
                                <CardContent className="p-4">
                                    <div className="flex items-start justify-between gap-4">
                                        <div className="flex items-start gap-4">
                                            <div className={`rounded-full p-2 ${config.bgColor}`}>
                                                <Icon className={`h-5 w-5 ${config.color}`} />
                                            </div>
                                            <div className="space-y-1">
                                                <div className="flex items-center gap-2">
                                                    <h3 className="font-semibold">{notification.title}</h3>
                                                    <Badge variant={config.badgeVariant}>
                                                        {config.label}
                                                    </Badge>
                                                    {notification.webhookSent && (
                                                        <Badge variant="default" className="bg-green-500">
                                                            <CheckCircle className="h-3 w-3 mr-1" />
                                                            Terkirim
                                                        </Badge>
                                                    )}
                                                </div>
                                                <p className="text-sm text-muted-foreground">
                                                    {notification.message}
                                                </p>
                                                {notification.dueDate && (
                                                    <p className="text-xs text-muted-foreground">
                                                        Jatuh tempo: {formatDate(notification.dueDate)}
                                                    </p>
                                                )}
                                                <p className="text-xs text-muted-foreground">
                                                    {formatDate(notification.createdAt)} {formatTime(notification.createdAt)}
                                                </p>
                                            </div>
                                        </div>
                                        <div className="flex flex-col gap-2">
                                            {/* Show "Jadwalkan Sekarang" button for calibration notifications */}
                                            {notification.type === 'calibration_h30' &&
                                                notification.referenceType === 'instrument' &&
                                                !notification.webhookSent && (
                                                    <Button
                                                        size="sm"
                                                        onClick={() => setConfirmSchedule(notification)}
                                                        disabled={isScheduling && schedulingId === notification.id}
                                                    >
                                                        {isScheduling && schedulingId === notification.id ? (
                                                            <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                                                        ) : (
                                                            <Calendar className="h-4 w-4 mr-2" />
                                                        )}
                                                        Jadwalkan Sekarang
                                                    </Button>
                                                )}
                                            {notification.actionUrl && (
                                                <Button
                                                    size="sm"
                                                    variant="outline"
                                                    onClick={() => {
                                                        handleMarkAsRead(notification.id)
                                                        router.push(notification.actionUrl!)
                                                    }}
                                                >
                                                    <ExternalLink className="h-4 w-4 mr-2" />
                                                    Lihat Detail
                                                </Button>
                                            )}
                                            {!notification.isRead && (
                                                <Button
                                                    size="sm"
                                                    variant="ghost"
                                                    onClick={() => handleMarkAsRead(notification.id)}
                                                >
                                                    <Check className="h-4 w-4 mr-2" />
                                                    Tandai Dibaca
                                                </Button>
                                            )}
                                        </div>
                                    </div>
                                </CardContent>
                            </Card>
                        )
                    })
                )}
            </div>

            {/* Pagination */}
            {pagination.totalPages > 1 && (
                <Pagination
                    pagination={pagination}
                    onPageChange={setPage}
                />
            )}

            {/* Confirmation Dialog */}
            <AlertDialog open={!!confirmSchedule} onOpenChange={() => setConfirmSchedule(null)}>
                <AlertDialogContent>
                    <AlertDialogHeader>
                        <AlertDialogTitle>Jadwalkan Kalibrasi?</AlertDialogTitle>
                        <AlertDialogDescription>
                            Tindakan ini akan mengirimkan notifikasi email ke vendor kalibrasi untuk instrumen{' '}
                            <strong>{confirmSchedule?.title.replace('Kalibrasi ', '')}</strong>.
                            <br /><br />
                            Status instrumen akan berubah menjadi &quot;Sudah Dijadwalkan&quot;.
                        </AlertDialogDescription>
                    </AlertDialogHeader>
                    <AlertDialogFooter>
                        <AlertDialogCancel disabled={isScheduling}>Batal</AlertDialogCancel>
                        <AlertDialogAction
                            onClick={() => confirmSchedule && handleScheduleCalibration(confirmSchedule)}
                            disabled={isScheduling}
                        >
                            {isScheduling ? (
                                <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                            ) : (
                                <Calendar className="h-4 w-4 mr-2" />
                            )}
                            Ya, Jadwalkan
                        </AlertDialogAction>
                    </AlertDialogFooter>
                </AlertDialogContent>
            </AlertDialog>
        </div>
    )
}

