            description: "di bawah minimum",
            icon: Package,
            color: "text-yellow-500",
            bgColor: "bg-yellow-50 dark:bg-yellow-950",
        },
        {
            title: "Stok Habis",
            value: dashboardData?.stats.outOfStockItems?.toString() || "0",
