import { NextRequest, NextResponse } from 'next/server';
import { StorageService, STORAGE_BUCKETS } from '@/lib/services/storage.service';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

export async function POST(request: NextRequest) {
    try {
        const formData = await request.formData();
        const file = formData.get('file') as File | null;
        const catalogType = formData.get('catalogType') as string;
        const catalogId = formData.get('catalogId') as string;
        const documentType = formData.get('documentType') as string;

        if (!file) {
            return NextResponse.json(
                { error: 'File tidak ditemukan' },
                { status: 400 }
            );
        }

        // Validate file type
        const allowedTypes = [
            'application/pdf',
            'application/msword',
            'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
        ];

        if (!allowedTypes.includes(file.type)) {
            return NextResponse.json(
                { error: 'Tipe file tidak didukung. Hanya PDF, DOC, dan DOCX yang diizinkan.' },
                { status: 400 }
            );
        }

        // Validate file size (10MB max)
        if (file.size > 10 * 1024 * 1024) {
            return NextResponse.json(
                { error: 'Ukuran file terlalu besar. Maksimal 10MB.' },
                { status: 400 }
            );
        }

        // Create folder path based on catalog type and document type
        const folder = `${catalogType}/${documentType}`;

        // Upload to Supabase Storage
        const result = await StorageService.uploadFile(
            STORAGE_BUCKETS.DOCUMENTS,
            folder,
            file
        );

        if (!result.success) {
            return NextResponse.json(
                { error: result.error || 'Gagal mengupload file' },
                { status: 500 }
            );
        }

        return NextResponse.json({
            success: true,
            path: result.path,
            publicUrl: result.publicUrl,
            fileName: file.name,
            fileSize: file.size,
            mimeType: file.type,
        });

    } catch (error) {
        console.error('Upload error:', error);
        return NextResponse.json(
            { error: 'Terjadi kesalahan saat mengupload file' },
            { status: 500 }
        );
    }
}

import { NextRequest, NextResponse } from 'next/server';
import { db, schema } from '@/lib/db';

export async function GET(request: NextRequest) {
    try {
        const { searchParams } = new URL(request.url);
        const type = searchParams.get('type');

        if (!type) {
            return NextResponse.json(
                { error: 'Parameter type wajib diisi' },
                { status: 400 }
            );
        }

        let items: { id: string; name: string; unit: string }[] = [];

        if (type === 'reagent' || type === 'standard' || type === 'sample') {
            // Get from warehouse_chemicals based on catalogType
            const chemicals = await db.query.warehouseChemicals.findMany();
            items = chemicals
                .filter(c => c.catalogType === type)
                .map(c => ({
                    id: c.id,
                    name: c.name,
                    unit: c.unit,
                }));
        } else if (type === 'barang' || type === 'consumable') {
            // Get from warehouse_items based on category
            const warehouseItems = await db.query.warehouseItems.findMany();
            items = warehouseItems
                .filter(i => i.category === type)
                .map(i => ({
                    id: i.id,
                    name: i.name,
                    unit: i.unit,
                }));
        } else {
            return NextResponse.json(
                { error: 'Tipe tidak valid. Gunakan: reagent, standard, sample, barang, consumable' },
                { status: 400 }
            );
        }

        // Remove duplicates by name
        const uniqueItems = items.reduce((acc, current) => {
            const exists = acc.find(item => item.name === current.name);
            if (!exists) {
                acc.push(current);
            }
            return acc;
        }, [] as typeof items);

        return NextResponse.json({ items: uniqueItems });
    } catch (error) {
        console.error('Warehouse options GET error:', error);
        return NextResponse.json(
            { error: 'Gagal mengambil data warehouse options' },
            { status: 500 }
        );
    }
}

