                                        <div className={cn(
                                            "p-2 rounded-full",
                                            config.color,
                                            "bg-opacity-20"
                                        )}>
                                            <Icon className={cn("h-4 w-4", config.textColor)} />
                                        </div>
                                        <div className="flex-1 min-w-0">
                                            <div className="flex items-center justify-between gap-2">
                                                <h4 className={cn("font-semibold", config.textColor)}>
                                                    {event.title}
                                                </h4>
                                                <Badge variant={config.badgeVariant} className="shrink-0">
                                                    {config.label}
                                                </Badge>
                                            </div>
                                            {event.instrumentName && (
                                                <p className="text-sm text-muted-foreground mt-1">
                                                    <span className="font-medium">Instrumen:</span> {event.instrumentName}
                                                </p>
                                            )}
                                            {event.location && (
                                                <p className="text-sm text-muted-foreground">
                                                    <span className="font-medium">Lokasi:</span> {event.location}
                                                </p>
                                            )}
                                            {event.description && (
                                                <p className="text-sm text-muted-foreground mt-2">
                                                    {event.description}
                                                </p>
                                            )}
                                            {event.status && (
                                                <p className="text-sm mt-2">
                                                    <span className="font-medium">Status:</span>{" "}
                                                    <Badge variant="outline" className="ml-1">
                                                        {event.status}
                                                    </Badge>
                                                </p>
                                            )}
                                        </div>
                                    </div>
                                </div>
                            )
                        })}
                    </div>
                </DialogContent>
            </Dialog>
        </div>
    )
}

"use client"

import { useState, useEffect } from "react"
import {
    format,
    startOfWeek,
    endOfWeek,
    addDays,
    addWeeks,
    subWeeks,
    isSameDay,
} from "date-fns"
import { id } from "date-fns/locale"
import { Button } from "@/components/ui/button"
import { ChevronLeft, ChevronRight, Calendar as CalendarIcon, AlertTriangle, Wrench } from "lucide-react"
import { cn } from "@/lib/utils"

interface ScheduleEvent {
    id: string
    title: string
    date: Date
    type: "calibration" | "maintenance" | "expired" | "order"
    status?: string
}

interface WeeklyCalendarProps {
    events: ScheduleEvent[]
    onEventClick?: (event: ScheduleEvent) => void
}

const eventTypeConfig = {
    calibration: {
        color: "bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200",
        icon: Wrench
    },
    maintenance: {
        color: "bg-purple-100 text-purple-800 dark:bg-purple-900 dark:text-purple-200",
        icon: Wrench
    },
    expired: {
        color: "bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-200",
        icon: AlertTriangle
    },
    order: {
        color: "bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200",
        icon: CalendarIcon
    },
}

export function WeeklyCalendar({ events, onEventClick }: WeeklyCalendarProps) {
    const [mounted, setMounted] = useState(false)
    const [currentDate, setCurrentDate] = useState(new Date())

    useEffect(() => {
        setMounted(true)
    }, [])

    const weekStart = startOfWeek(currentDate, { weekStartsOn: 1 })
    const weekEnd = endOfWeek(currentDate, { weekStartsOn: 1 })

    const weekDays = Array.from({ length: 7 }, (_, i) => addDays(weekStart, i))

    const goToPreviousWeek = () => setCurrentDate(subWeeks(currentDate, 1))
    const goToNextWeek = () => setCurrentDate(addWeeks(currentDate, 1))
    const goToToday = () => setCurrentDate(new Date())

    const getEventsForDay = (day: Date) => {
        return events.filter(event => isSameDay(event.date, day))
    }

    const isToday = (day: Date) => isSameDay(day, new Date())

    if (!mounted) {
        return <div className="h-[200px] animate-pulse bg-muted rounded-lg" />
    }

    return (
        <div className="space-y-4">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                    <Button variant="outline" size="sm" onClick={goToToday}>
                        Hari Ini
                    </Button>
                    <div className="flex items-center">
                        <Button variant="ghost" size="icon" onClick={goToPreviousWeek}>
                            <ChevronLeft className="h-4 w-4" />
                        </Button>
                        <Button variant="ghost" size="icon" onClick={goToNextWeek}>
                            <ChevronRight className="h-4 w-4" />
                        </Button>
                    </div>
                </div>
                <h3 className="text-lg font-semibold">
                    {format(weekStart, "d MMM", { locale: id })} - {format(weekEnd, "d MMM yyyy", { locale: id })}
                </h3>
            </div>

            {/* Week Grid */}
            <div className="grid grid-cols-7 gap-2">
                {weekDays.map((day) => (
                    <div key={day.toISOString()} className="min-h-[120px]">
                        {/* Day Header */}
                        <div className={cn(
                            "text-center p-2 rounded-t-lg",
                            isToday(day) ? "bg-primary text-primary-foreground" : "bg-muted"
                        )}>
                            <div className="text-xs font-medium">
                                {format(day, "EEE", { locale: id })}
                            </div>
                            <div className="text-lg font-bold">
                                {format(day, "d")}
                            </div>
                        </div>

                        {/* Events */}
                        <div className="border border-t-0 rounded-b-lg p-1 min-h-[80px] space-y-1">
                            {getEventsForDay(day).map((event) => {
                                const config = eventTypeConfig[event.type]
                                const Icon = config.icon
                                return (
                                    <button
                                        key={event.id}
                                        onClick={() => onEventClick?.(event)}
                                        className={cn(
                                            "w-full text-left p-1 rounded text-xs truncate flex items-center gap-1",
                                            config.color,
                                            "hover:opacity-80 transition-opacity"
                                        )}
                                    >
                                        <Icon className="h-3 w-3 shrink-0" />
                                        <span className="truncate">{event.title}</span>
                                    </button>
                                )
                            })}
                        </div>
                    </div>
                ))}
            </div>
        </div>
    )
}

"use client"

import {
    AlertDialog,
    AlertDialogAction,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle,
} from "@/components/ui/alert-dialog"
import { AlertTriangle, Trash2, CheckCircle2, XCircle, Info } from "lucide-react"
import { cn } from "@/lib/utils"

type DialogVariant = "default" | "destructive" | "success" | "warning" | "info"

interface ConfirmDialogProps {
    isOpen: boolean
    onClose: () => void
    onConfirm: () => void
    title: string
    description: string
    confirmText?: string
    cancelText?: string
    variant?: DialogVariant
    isLoading?: boolean
}

const variantConfig: Record<DialogVariant, {
    icon: typeof AlertTriangle
    iconColor: string
    buttonClass: string
}> = {
    default: {
        icon: Info,
        iconColor: "text-blue-500",
        buttonClass: "",
    },
    destructive: {
        icon: Trash2,
        iconColor: "text-red-500",
        buttonClass: "bg-red-600 hover:bg-red-700",
    },
    success: {
        icon: CheckCircle2,
        iconColor: "text-green-500",
        buttonClass: "bg-green-600 hover:bg-green-700",
    },
    warning: {
        icon: AlertTriangle,
        iconColor: "text-yellow-500",
        buttonClass: "bg-yellow-600 hover:bg-yellow-700",
    },
    info: {
        icon: Info,
        iconColor: "text-blue-500",
        buttonClass: "",
    },
}

export function ConfirmDialog({
    isOpen,
    onClose,
    onConfirm,
    title,
    description,
    confirmText = "Konfirmasi",
    cancelText = "Batal",
    variant = "default",
    isLoading = false,
}: ConfirmDialogProps) {
    const config = variantConfig[variant]
    const Icon = config.icon

    const handleConfirm = () => {
        onConfirm()
        if (!isLoading) {
            onClose()
        }
    }

    return (
        <AlertDialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
            <AlertDialogContent>
                <AlertDialogHeader>
                    <div className="flex items-center gap-3">
                        <div className={cn("p-2 rounded-full bg-muted", config.iconColor)}>
                            <Icon className="h-5 w-5" />
                        </div>
                        <AlertDialogTitle>{title}</AlertDialogTitle>
                    </div>
                    <AlertDialogDescription className="pt-2">
                        {description}
                    </AlertDialogDescription>
                </AlertDialogHeader>
                <AlertDialogFooter>
                    <AlertDialogCancel disabled={isLoading}>
                        {cancelText}
                    </AlertDialogCancel>
                    <AlertDialogAction
                        onClick={handleConfirm}
                        disabled={isLoading}
                        className={cn(config.buttonClass)}
                    >
                        {isLoading ? "Memproses..." : confirmText}
                    </AlertDialogAction>
                </AlertDialogFooter>
            </AlertDialogContent>
        </AlertDialog>
    )
}

// Delete Confirmation shorthand
interface DeleteConfirmDialogProps {
    isOpen: boolean
    onClose: () => void
    onConfirm: () => void
    itemName: string
    isLoading?: boolean
}

export function DeleteConfirmDialog({
    isOpen,
    onClose,
    onConfirm,
    itemName,
    isLoading,
}: DeleteConfirmDialogProps) {
    return (
        <ConfirmDialog
            isOpen={isOpen}
            onClose={onClose}
            onConfirm={onConfirm}
            title="Hapus Item"
            description={`Apakah Anda yakin ingin menghapus "${itemName}"? Tindakan ini tidak dapat dibatalkan.`}
            confirmText="Hapus"
            cancelText="Batal"
            variant="destructive"
            isLoading={isLoading}
        />
    )
}

// Approve/Reject Confirmation shorthand
interface ApprovalConfirmDialogProps {
    isOpen: boolean
    onClose: () => void
    onConfirm: () => void
    action: "approve" | "reject"
    itemName: string
    isLoading?: boolean
}

export function ApprovalConfirmDialog({
    isOpen,
    onClose,
    onConfirm,
    action,
    itemName,
    isLoading,
}: ApprovalConfirmDialogProps) {
    const isApprove = action === "approve"

    return (
        <ConfirmDialog
            isOpen={isOpen}
            onClose={onClose}
            onConfirm={onConfirm}
            title={isApprove ? "Setujui Pesanan" : "Tolak Pesanan"}
            description={
                isApprove
                    ? `Apakah Anda yakin ingin menyetujui "${itemName}"?`
                    : `Apakah Anda yakin ingin menolak "${itemName}"? Mohon pastikan alasan penolakan sudah dikomunikasikan.`
            }
            confirmText={isApprove ? "Setujui" : "Tolak"}
            cancelText="Batal"
            variant={isApprove ? "success" : "destructive"}
            isLoading={isLoading}
        />
    )
}

"use client"

import { useState, useRef, useCallback } from "react"
import { Button } from "@/components/ui/button"
import { Upload, X, ImageIcon, Loader2 } from "lucide-react"
import { cn } from "@/lib/utils"

interface ImageUploadProps {
    /**
     * Current image URL (for displaying existing image)
     */
    value?: string | null
    /**
     * Callback when image is selected/uploaded
     */
    onChange: (url: string | null, file?: File) => void
    /**
     * Whether to upload directly to API or just return file
     */
    uploadImmediately?: boolean
    /**
     * Upload endpoint (default: /api/upload)
     */
    uploadEndpoint?: string
    /**
     * Upload bucket name
     */
    bucket?: 'images' | 'documents' | 'calibration-reports' | 'maintenance-photos'
    /**
     * Maximum file size in MB (default: 5)
     */
    maxSizeMB?: number
    /**
     * Accepted file types
     */
    accept?: string
    /**
     * Placeholder text
     */
    placeholder?: string
    /**
     * Disabled state
     */
    disabled?: boolean
    /**
     * Custom className
     */
    className?: string
}

export function ImageUpload({
    value,
    onChange,
    uploadImmediately = false,
    uploadEndpoint = "/api/upload",
    bucket = "images",
    maxSizeMB = 5,
    accept = "image/*",
    placeholder = "Klik atau drag foto untuk upload",
    disabled = false,
    className,
}: ImageUploadProps) {
    const [isUploading, setIsUploading] = useState(false)
    const [isDragOver, setIsDragOver] = useState(false)
    const [error, setError] = useState<string | null>(null)
    const [previewUrl, setPreviewUrl] = useState<string | null>(null)
    const inputRef = useRef<HTMLInputElement>(null)

    const handleFile = useCallback(async (file: File) => {
        setError(null)

        // Validate file size
        if (file.size > maxSizeMB * 1024 * 1024) {
            setError(`Ukuran file maksimal ${maxSizeMB}MB`)
            return
        }

        // Create preview
        const objectUrl = URL.createObjectURL(file)
        setPreviewUrl(objectUrl)

        if (uploadImmediately) {
            // Upload to server
            setIsUploading(true)
            try {
                const formData = new FormData()
                formData.append("file", file)
                formData.append("bucket", bucket)

                const response = await fetch(uploadEndpoint, {
                    method: "POST",
                    body: formData,
                })

                if (!response.ok) {
                    throw new Error("Upload gagal")
                }

                const data = await response.json()
                onChange(data.url, file)
            } catch (err) {
                setError("Gagal mengupload gambar")
                setPreviewUrl(null)
            } finally {
                setIsUploading(false)
            }
        } else {
            // Just return file without uploading
            onChange(objectUrl, file)
        }
    }, [maxSizeMB, uploadImmediately, bucket, uploadEndpoint, onChange])

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0]
        if (file) {
            handleFile(file)
        }
    }

    const handleDrop = useCallback((e: React.DragEvent<HTMLDivElement>) => {
        e.preventDefault()
        setIsDragOver(false)

        if (disabled) return

        const file = e.dataTransfer.files?.[0]
        if (file && file.type.startsWith('image/')) {
            handleFile(file)
        }
    }, [disabled, handleFile])

    const handleDragOver = (e: React.DragEvent<HTMLDivElement>) => {
        e.preventDefault()
        if (!disabled) {
            setIsDragOver(true)
        }
    }

    const handleDragLeave = () => {
        setIsDragOver(false)
    }

    const handleRemove = () => {
        setPreviewUrl(null)
        onChange(null)
        if (inputRef.current) {
            inputRef.current.value = ""
        }
    }

    const displayUrl = previewUrl || value

    return (
        <div className={cn("space-y-2", className)}>
            <div
                className={cn(
                    "relative border-2 border-dashed rounded-lg transition-colors",
                    isDragOver && "border-primary bg-primary/5",
                    !displayUrl && !disabled && "hover:border-primary hover:bg-muted/50 cursor-pointer",
                    disabled && "opacity-50 cursor-not-allowed",
                    error && "border-destructive"
                )}
                onDrop={handleDrop}
                onDragOver={handleDragOver}
                onDragLeave={handleDragLeave}
                onClick={() => !disabled && !displayUrl && inputRef.current?.click()}
            >
                <input
                    ref={inputRef}
                    type="file"
                    accept={accept}
                    onChange={handleInputChange}
                    disabled={disabled}
                    className="hidden"
                />

                {isUploading ? (
                    <div className="flex flex-col items-center justify-center py-12">
                        <Loader2 className="h-10 w-10 text-primary animate-spin mb-2" />
                        <p className="text-sm text-muted-foreground">Mengupload...</p>
                    </div>
                ) : displayUrl ? (
                    <div className="relative aspect-video">
                        {/* eslint-disable-next-line @next/next/no-img-element */}
                        <img
                            src={displayUrl}
                            alt="Preview"
                            className="w-full h-full object-contain rounded-lg"
                        />
                        {!disabled && (
                            <Button
                                type="button"
                                variant="destructive"
                                size="icon"
                                className="absolute top-2 right-2"
                                onClick={(e) => {
                                    e.stopPropagation()
                                    handleRemove()
                                }}
                            >
                                <X className="h-4 w-4" />
                            </Button>
                        )}
                    </div>
                ) : (
                    <div className="flex flex-col items-center justify-center py-12">
                        <div className="p-3 bg-muted rounded-full mb-3">
                            {isDragOver ? (
                                <Upload className="h-8 w-8 text-primary" />
                            ) : (
                                <ImageIcon className="h-8 w-8 text-muted-foreground" />
                            )}
                        </div>
                        <p className="text-sm text-muted-foreground text-center">
                            {placeholder}
                        </p>
                        <p className="text-xs text-muted-foreground mt-1">
                            Maks. {maxSizeMB}MB
                        </p>
                    </div>
                )}
            </div>

            {error && (
                <p className="text-sm text-destructive">{error}</p>
            )}
        </div>
    )
}

"use client"

import * as React from "react"
import { useState, useRef, useEffect, useCallback, useMemo } from "react"
import { Check, ChevronsUpDown, Search, Loader2 } from "lucide-react"
import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"

export interface SearchableSelectOption {
    value: string
    label: string
    category?: string
    disabled?: boolean
}

interface SearchableSelectProps {
    options: SearchableSelectOption[]
    value: string
    onValueChange: (value: string) => void
    placeholder?: string
    searchPlaceholder?: string
    emptyMessage?: string
    disabled?: boolean
    isLoading?: boolean
    className?: string
    // Virtual scrolling config
    itemHeight?: number
    maxDisplayItems?: number
}

const ITEM_HEIGHT = 36
const MAX_DISPLAY_ITEMS = 8
const VIRTUAL_BUFFER = 5

export function SearchableSelect({
    options,
    value,
    onValueChange,
    placeholder = "Pilih item...",
    searchPlaceholder = "Cari item...",
    emptyMessage = "Tidak ada item ditemukan",
    disabled = false,
    isLoading = false,
    className,
    itemHeight = ITEM_HEIGHT,
    maxDisplayItems = MAX_DISPLAY_ITEMS,
}: SearchableSelectProps) {
    const [open, setOpen] = useState(false)
    const [search, setSearch] = useState("")
    const [scrollTop, setScrollTop] = useState(0)
    const containerRef = useRef<HTMLDivElement>(null)
    const inputRef = useRef<HTMLInputElement>(null)
    const scrollRef = useRef<HTMLDivElement>(null)

    // Filter options based on search
    const filteredOptions = useMemo(() => {
        if (!search.trim()) return options
        const searchLower = search.toLowerCase()
        return options.filter(option =>
            option.label.toLowerCase().includes(searchLower) ||
            (option.category?.toLowerCase().includes(searchLower) ?? false)
        )
    }, [options, search])

    // Virtual scrolling calculations
    const totalHeight = filteredOptions.length * itemHeight
    const visibleHeight = maxDisplayItems * itemHeight
    const startIndex = Math.max(0, Math.floor(scrollTop / itemHeight) - VIRTUAL_BUFFER)
    const endIndex = Math.min(
        filteredOptions.length,
        Math.ceil((scrollTop + visibleHeight) / itemHeight) + VIRTUAL_BUFFER
    )
    const visibleItems = filteredOptions.slice(startIndex, endIndex)
    const offsetY = startIndex * itemHeight

    // Handle scroll
    const handleScroll = useCallback((e: React.UIEvent<HTMLDivElement>) => {
        setScrollTop(e.currentTarget.scrollTop)
    }, [])

    // Close dropdown when clicking outside
    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
                setOpen(false)
            }
        }
        if (open) {
            document.addEventListener("mousedown", handleClickOutside)
        }
        return () => document.removeEventListener("mousedown", handleClickOutside)
    }, [open])

    // Reset search when closing
    useEffect(() => {
        if (!open) {
            setSearch("")
            setScrollTop(0)
        } else {
            // Focus search input when opening
            setTimeout(() => inputRef.current?.focus(), 10)
        }
    }, [open])

    // Get selected label
    const selectedLabel = options.find(opt => opt.value === value)?.label

    return (
        <div ref={containerRef} className={cn("relative", className)}>
            <Button
                type="button"
                variant="outline"
                role="combobox"
                aria-expanded={open}
                disabled={disabled || isLoading}
                onClick={() => setOpen(!open)}
                className={cn(
                    "w-full justify-between font-normal",
                    !value && "text-muted-foreground"
                )}
            >
                {isLoading ? (
                    <span className="flex items-center gap-2">
                        <Loader2 className="h-4 w-4 animate-spin" />
                        Loading...
                    </span>
                ) : (
                    <span className="truncate">
                        {selectedLabel || placeholder}
                    </span>
                )}
                <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
            </Button>

            {open && (
                <div className="absolute z-50 mt-1 w-full rounded-md border bg-popover shadow-lg">
                    {/* Search input */}
                    <div className="flex items-center border-b px-3 py-2">
                        <Search className="mr-2 h-4 w-4 shrink-0 opacity-50" />
                        <Input
                            ref={inputRef}
                            placeholder={searchPlaceholder}
                            value={search}
                            onChange={(e) => setSearch(e.target.value)}
                            className="h-8 border-0 bg-transparent p-0 shadow-none focus-visible:ring-0"
                        />
                    </div>

                    {/* Virtual scrolling list */}
                    <div
                        ref={scrollRef}
                        onScroll={handleScroll}
                        className="overflow-y-auto"
                        style={{ maxHeight: visibleHeight }}
                    >
                        {filteredOptions.length === 0 ? (
                            <div className="py-6 text-center text-sm text-muted-foreground">
                                {emptyMessage}
                            </div>
                        ) : (
                            <div style={{ height: totalHeight, position: "relative" }}>
                                <div style={{ transform: `translateY(${offsetY}px)` }}>
                                    {visibleItems.map((option) => (
                                        <div
                                            key={option.value}
                                            onClick={() => {
                                                if (!option.disabled) {
                                                    onValueChange(option.value)
                                                    setOpen(false)
                                                }
                                            }}
                                            className={cn(
                                                "relative flex cursor-pointer select-none items-center px-3 py-2 text-sm outline-none transition-colors",
                                                "hover:bg-accent hover:text-accent-foreground",
                                                option.value === value && "bg-accent",
                                                option.disabled && "pointer-events-none opacity-50"
                                            )}
                                            style={{ height: itemHeight }}
                                        >
                                            <Check
                                                className={cn(
                                                    "mr-2 h-4 w-4 shrink-0",
                                                    option.value === value ? "opacity-100" : "opacity-0"
                                                )}
                                            />
                                            <span className="truncate flex-1">{option.label}</span>
                                            {option.category && (
                                                <span className="ml-2 text-xs text-muted-foreground">
                                                    {option.category}
                                                </span>
                                            )}
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )}
                    </div>

                    {/* Item count footer */}
                    {filteredOptions.length > 0 && (
                        <div className="border-t px-3 py-2 text-xs text-muted-foreground">
                            {search ? (
                                <span>{filteredOptions.length} dari {options.length} item</span>
                            ) : (
                                <span>{options.length} item</span>
                            )}
                        </div>
                    )}
                </div>
            )}
        </div>
    )
}

