// Paginated fetch hook
import { PaginationMeta, PaginatedResponse, DEFAULT_PAGE, DEFAULT_PAGE_SIZE } from "@/types/pagination";

interface UseFetchPaginatedOptions {
    immediate?: boolean;
    debounceMs?: number;
}

interface UseFetchPaginatedResult<T> {
    data: T[];
    pagination: PaginationMeta;
    isLoading: boolean;
    isFetching: boolean; // NEW: For subtle loading indicator during refetch
    error: string | null;
    refetch: () => Promise<void>;
    page: number;
    setPage: (page: number) => void;
    search: string;
    setSearch: (search: string) => void;
}

export function useFetchPaginated<T>(
    baseUrl: string,
    filters: Record<string, string | undefined> = {},
    options: UseFetchPaginatedOptions = { immediate: true, debounceMs: 500 }
): UseFetchPaginatedResult<T> {
    const [data, setData] = useState<T[]>([]);
    const [pagination, setPagination] = useState<PaginationMeta>({
        page: DEFAULT_PAGE,
        limit: DEFAULT_PAGE_SIZE,
        total: 0,
        totalPages: 0,
    });
    // Separate loading states for better UX
    const [isInitialLoad, setIsInitialLoad] = useState(true);
    const [isFetching, setIsFetching] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [page, setPageState] = useState(DEFAULT_PAGE);
    const [search, setSearchState] = useState("");
    const [debouncedSearch, setDebouncedSearch] = useState("");

    // Debounce search with 500ms delay (best practice for search UX)
    useEffect(() => {
        const timer = setTimeout(() => {
            setDebouncedSearch(search);
        }, options.debounceMs ?? 500);
        return () => clearTimeout(timer);
    }, [search, options.debounceMs]);

    // Reset page to 1 when search changes
    useEffect(() => {
        setPageState(DEFAULT_PAGE);
    }, [debouncedSearch]);

    // Reset page to 1 when filters change
    const filtersKey = JSON.stringify(filters);
    useEffect(() => {
        setPageState(DEFAULT_PAGE);
    }, [filtersKey]);

    // Build URL with query params
    const buildUrl = useCallback(() => {
        const params = new URLSearchParams();
        params.set("page", page.toString());
        params.set("limit", DEFAULT_PAGE_SIZE.toString());
        if (debouncedSearch) {
            params.set("search", debouncedSearch);
        }
        // Add filters
        Object.entries(filters).forEach(([key, value]) => {
            if (value && value !== "all") {
                params.set(key, value);
            }
        });
        return `${baseUrl}?${params.toString()}`;
    }, [baseUrl, page, debouncedSearch, filtersKey]);

    const fetchData = useCallback(async () => {
        // Don't clear data during fetch (SWR pattern - Stale While Revalidate)
        // This prevents blank screen during search
        setIsFetching(true);
        setError(null);
        try {
            const url = buildUrl();
            const response = await fetch(url);
            if (!response.ok) {
                const errorData = await response.json();
                throw new Error(errorData.error || "Gagal mengambil data");
            }
            const result: PaginatedResponse<T> = await response.json();
            setData(result.data);
            setPagination(result.pagination);
        } catch (err) {
            setError(err instanceof Error ? err.message : "Terjadi kesalahan");
            // Only clear data on initial load error, keep previous data on refetch error
            if (isInitialLoad) {
                setData([]);
                setPagination({
                    page: DEFAULT_PAGE,
                    limit: DEFAULT_PAGE_SIZE,
                    total: 0,
                    totalPages: 0,
                });
            }
        } finally {
            setIsFetching(false);
            setIsInitialLoad(false);
        }
    }, [buildUrl, isInitialLoad]);

    useEffect(() => {
        if (options.immediate) {
            fetchData();
        }
    }, [fetchData, options.immediate]);

    const setPage = useCallback((newPage: number) => {
        setPageState(newPage);
    }, []);

    const setSearch = useCallback((newSearch: string) => {
        setSearchState(newSearch);
    }, []);

    return {
        data,
        pagination,
        isLoading: isInitialLoad && isFetching, // Only true on first load
        isFetching, // True during any fetch (for subtle indicator)
        error,
        refetch: fetchData,
        page,
        setPage,
        search,
        setSearch,
    };
}

import { pgTable, uuid, varchar, text, integer, decimal, timestamp, date, pgEnum, boolean } from 'drizzle-orm/pg-core';
import { relations } from 'drizzle-orm';
import { profiles } from './users';

// Enums
export const stockStatusEnum = pgEnum('stock_status', ['available', 'low_stock', 'out_of_stock', 'expired']);
export const itemFormEnum = pgEnum('item_form', ['solid', 'liquid', 'gas']);
export const storageLocationEnum = pgEnum('storage_location', ['TC 1', 'TC 2', 'TC 3']);
export const stockUnitEnum = pgEnum('stock_unit', ['unit', 'pack', 'pcs', 'set', 'roll', 'ml', 'L', 'g', 'kg']);
export const itemCategoryEnum = pgEnum('item_category', ['barang', 'consumable']);
export const warehouseItemStatusEnum = pgEnum('warehouse_item_status', ['tersedia', 'sedang_digunakan', 'habis']);
export const orderStatusEnum = pgEnum('order_status', ['pending', 'approved', 'rejected', 'received', 'cancelled']);

// Reagent Catalog
export const reagentCatalog = pgTable('reagent_catalog', {
    id: uuid('id').primaryKey().defaultRandom(),
    reagentName: varchar('reagent_name', { length: 255 }).notNull(),
    casNumber: varchar('cas_number', { length: 50 }),
    supplier: varchar('supplier', { length: 255 }),
    storageLocation: storageLocationEnum('storage_location').notNull(),
    form: itemFormEnum('form').notNull(),
    msdsDocument: text('msds_document'), // Storage URL
    coaDocument: text('coa_document'), // Storage URL - Quick access reference
    productPhoto: text('product_photo'), // Storage URL
    minimumStockLevel: integer('minimum_stock_level').default(0).notNull(),
    createdAt: timestamp('created_at').defaultNow().notNull(),
    updatedAt: timestamp('updated_at').defaultNow().notNull(),
});

// Standard Stock Catalog
export const standardCatalog = pgTable('standard_catalog', {
    id: uuid('id').primaryKey().defaultRandom(),
    standardName: varchar('standard_name', { length: 255 }).notNull(),
    casNumber: varchar('cas_number', { length: 50 }),
    chemicalFormula: varchar('chemical_formula', { length: 100 }),
    supplier: varchar('supplier', { length: 255 }),
    sizeValue: decimal('size_value', { precision: 10, scale: 2 }),
    sizeUnit: varchar('size_unit', { length: 20 }),
    form: itemFormEnum('form').notNull(),
    storageLocation: storageLocationEnum('storage_location').notNull(),
