/**
 * Rate Limiter Utility
 * Token bucket algorithm for API rate limiting
 */

interface RateLimitEntry {
    tokens: number;
    lastRefill: number;
}

interface RateLimitConfig {
    maxTokens: number;      // Maximum requests allowed
    refillRate: number;     // Tokens refilled per interval
    refillInterval: number; // Interval in milliseconds
}

// In-memory store for rate limiting (resets on server restart)
const rateLimitStore = new Map<string, RateLimitEntry>();

// Default configurations for different endpoints
export const RATE_LIMIT_CONFIGS = {
    chat: {
        maxTokens: 10,          // 10 requests max
        refillRate: 10,         // Refill all tokens
        refillInterval: 60000,  // Per minute
    },
    upload: {
        maxTokens: 20,          // 20 requests max
        refillRate: 20,         // Refill all tokens
        refillInterval: 60000,  // Per minute
    },
    default: {
        maxTokens: 100,         // 100 requests max
        refillRate: 100,        // Refill all tokens
        refillInterval: 60000,  // Per minute
    },
} as const;

export type RateLimitEndpoint = keyof typeof RATE_LIMIT_CONFIGS;

/**
 * Get client identifier from request (IP-based)
 */
export function getClientId(request: Request): string {
    // Try to get real IP from headers (for proxied requests)
    const forwarded = request.headers.get('x-forwarded-for');
    if (forwarded) {
        return forwarded.split(',')[0].trim();
    }

    const realIp = request.headers.get('x-real-ip');
    if (realIp) {
        return realIp;
    }

    // Fallback to a hash of user-agent + timestamp for same-session tracking
    return 'unknown-' + Math.random().toString(36).substring(2);
}

/**
 * Check if request is rate limited
 * Returns remaining tokens or -1 if limited
 */
export function checkRateLimit(
    clientId: string,
    endpoint: RateLimitEndpoint = 'default'
): { allowed: boolean; remaining: number; resetIn: number } {
    const config = RATE_LIMIT_CONFIGS[endpoint];
    const now = Date.now();
    const key = `${endpoint}:${clientId}`;

    let entry = rateLimitStore.get(key);

    if (!entry) {
        // First request from this client
        entry = {
            tokens: config.maxTokens - 1,
            lastRefill: now,
        };
        rateLimitStore.set(key, entry);
        return {
            allowed: true,
            remaining: entry.tokens,
            resetIn: config.refillInterval,
        };
    }

    // Calculate time since last refill
    const timeSinceRefill = now - entry.lastRefill;

    // Refill tokens if interval has passed
    if (timeSinceRefill >= config.refillInterval) {
        entry.tokens = config.maxTokens;
        entry.lastRefill = now;
    }

    // Check if tokens available
    if (entry.tokens <= 0) {
        const resetIn = config.refillInterval - timeSinceRefill;
        return {
            allowed: false,
            remaining: 0,
            resetIn: Math.max(0, resetIn),
        };
    }

    // Consume token
    entry.tokens--;
    rateLimitStore.set(key, entry);

    return {
        allowed: true,
        remaining: entry.tokens,
        resetIn: config.refillInterval - timeSinceRefill,
    };
}

/**
 * Create rate limit headers for response
 */
export function getRateLimitHeaders(
    endpoint: RateLimitEndpoint,
    remaining: number,
    resetIn: number
): Record<string, string> {
    const config = RATE_LIMIT_CONFIGS[endpoint];
    return {
        'X-RateLimit-Limit': config.maxTokens.toString(),
        'X-RateLimit-Remaining': Math.max(0, remaining).toString(),
        'X-RateLimit-Reset': Math.ceil(resetIn / 1000).toString(),
    };
}

/**
 * Clean up old entries (call periodically to prevent memory leaks)
 */
export function cleanupRateLimitStore(): void {
    const now = Date.now();
    const maxAge = 5 * 60 * 1000; // 5 minutes

    for (const [key, entry] of rateLimitStore.entries()) {
        if (now - entry.lastRefill > maxAge) {
            rateLimitStore.delete(key);
        }
    }
}

import { db, schema } from '@/lib/db';

interface ChatContext {
    stockSummary: {
        reagents: { total: number; lowStock: number; outOfStock: number };
        standards: { total: number; lowStock: number; outOfStock: number };
        items: { total: number; lowStock: number; outOfStock: number };
    };
    upcomingCalibrations: { name: string; daysUntilDue: number }[];
    expiringChemicals: { name: string; daysUntilExpiry: number }[];
}

class ChatService {
    private webhookUrl = process.env.N8N_WEBHOOK_URL!;

    /**
     * Build context from database for AI assistant
     */
    private async buildContext(): Promise<ChatContext> {
        // Get stock summary
        const reagents = await db.query.reagentCatalog.findMany();
        const standards = await db.query.standardCatalog.findMany();
        const items = await db.query.itemsCatalog.findMany();
        const warehouseChemicals = await db.query.warehouseChemicals.findMany();
        const warehouseItems = await db.query.warehouseItems.findMany();

        // Calculate reagent stock counts
        const reagentStock = {
            total: reagents.length,
            lowStock: 0,
            outOfStock: 0,
        };

        for (const reagent of reagents) {
            const stock = warehouseChemicals.filter(
                wc => wc.catalogId === reagent.id && wc.catalogType === 'reagent'
            ).length;
            if (stock === 0) reagentStock.outOfStock++;
            else if (stock <= reagent.minimumStockLevel) reagentStock.lowStock++;
        }

        // Standard stock counts (similar logic)
        const standardStock = {
            total: standards.length,
            lowStock: 0,
            outOfStock: 0,
        };

        for (const standard of standards) {
            const stock = warehouseChemicals.filter(
                wc => wc.catalogId === standard.id && wc.catalogType === 'standard'
            ).length;
            if (stock === 0) standardStock.outOfStock++;
            else if (stock <= standard.minimumStockLevel) standardStock.lowStock++;
        }

        // Items stock counts
        const itemStock = {
            total: items.length,
            lowStock: 0,
            outOfStock: 0,
        };

        for (const item of items) {
            const stock = warehouseItems
                .filter(wi => wi.catalogId === item.id)
                .reduce((sum, wi) => sum + wi.currentQuantity, 0);
            if (stock === 0) itemStock.outOfStock++;
            else if (stock <= item.minimumStockLevel) itemStock.lowStock++;
        }

        // Get upcoming calibrations
        const instruments = await db.query.instruments.findMany();
        const today = new Date();
        const upcomingCalibrations = instruments
            .filter(inst => inst.nextCalibrationDate)
            .map(inst => {
                const nextDate = new Date(inst.nextCalibrationDate!);
                const diffTime = nextDate.getTime() - today.getTime();
                const daysUntilDue = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
                return { name: inst.name, daysUntilDue };
            })
            .filter(c => c.daysUntilDue <= 60) // Only next 60 days
            .sort((a, b) => a.daysUntilDue - b.daysUntilDue)
            .slice(0, 5);

        // Get expiring chemicals
        const expiringChemicals = warehouseChemicals
            .map(wc => {
                const expDate = new Date(wc.expiredDate);
                const diffTime = expDate.getTime() - today.getTime();
                const daysUntilExpiry = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
                return { name: wc.name, daysUntilExpiry };
            })
            .filter(c => c.daysUntilExpiry <= 30 && c.daysUntilExpiry > 0)
            .sort((a, b) => a.daysUntilExpiry - b.daysUntilExpiry)
            .slice(0, 5);

        return {
            stockSummary: {
                reagents: reagentStock,
                standards: standardStock,
                items: itemStock,
            },
            upcomingCalibrations,
            expiringChemicals,
        };
    }

    /**
     * Send message to n8n webhook with database context
     */
    async sendMessage(userMessage: string, sessionId?: string, userId?: string): Promise<string> {
        try {
            const context = await this.buildContext();

            // Get API key for webhook authentication
            const apiKey = process.env.N8N_WEBHOOK_API_KEY;
            if (!apiKey) {
                console.warn('N8N_WEBHOOK_API_KEY not configured');
            }

            const response = await fetch(this.webhookUrl, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    ...(apiKey && { 'X-API-Key': apiKey }),
                },
                body: JSON.stringify({
                    message: userMessage,
                    sessionId: sessionId || null,
                    userId: userId || null,
                    context: {
                        timestamp: new Date().toISOString(),
                        stockSummary: context.stockSummary,
                        upcomingCalibrations: context.upcomingCalibrations,
                        expiringChemicals: context.expiringChemicals,
                    },
                }),
            });

            if (!response.ok) {
                if (response.status === 401 || response.status === 403) {
                    console.error('Webhook authentication failed');
                }
                throw new Error(`Webhook responded with status: ${response.status}`);
            }

            const data = await response.json();
            return data.response || data.message || 'Tidak ada respons dari asisten.';
        } catch (error) {
            console.error('Chat service error:', error);
            return 'Maaf, terjadi kesalahan saat menghubungi asisten. Silakan coba lagi.';
        }
    }
}

export const chatService = new ChatService();

import { db, schema } from '@/lib/db';
import { eq, desc, and, gte, lte, sql } from 'drizzle-orm';
import type { TrainingCostLog, TrainingCostLogItem } from '@/lib/db/schema/inventory';
import crypto from 'crypto';

// ============================================
// Types
// ============================================

export interface CostCalculationResult {
    unitCost: number;
    totalCost: number;
    warehouseId: string;
    warehouseType: 'chemical' | 'item';
}

export interface TrainingCostStats {
    thisMonth: number;
    lastMonth: number;
    ytd: number;
    percentChange: number;
}

export interface CostTrendData {
    month: string;
    year: number;
    totalCost: number;
    executionCount: number;
}

export interface TrainingCostLogWithItems extends TrainingCostLog {
    items: TrainingCostLogItem[];
}

export interface CostReportFilters {
    startDate?: string;
    endDate?: string;
    trainingSetId?: string;
    page?: number;
    limit?: number;
}

// ============================================
// Cost Service
// ============================================

class CostService {
    /**
     * Generate idempotency key to prevent double execution
     */
    generateIdempotencyKey(trainingSetId: string, participants: number, userId: string): string {
        const timestamp = new Date();
        // Round to minute to allow for slight timing variations
        timestamp.setSeconds(0, 0);
        const data = `${trainingSetId}-${participants}-${userId}-${timestamp.toISOString()}`;
        return crypto.createHash('sha256').update(data).digest('hex').substring(0, 64);
    }

    /**
     * Check if execution with same idempotency key already exists
     */
    async checkDuplicateExecution(idempotencyKey: string): Promise<boolean> {
        const existing = await db.query.trainingCostLogs.findFirst({
            where: eq(schema.trainingCostLogs.idempotencyKey, idempotencyKey),
        });
        return !!existing;
    }

    /**
     * Calculate cost for a warehouse item (consumable)
     * Uses FIFO - first available item with quantity
     */
    async calculateItemCost(itemName: string): Promise<CostCalculationResult | null> {
        const warehouseItems = await db.query.warehouseItems.findMany({
            orderBy: [schema.warehouseItems.receivedDate], // FIFO - oldest first
        });

        const matchingItem = warehouseItems.find(
            wi => wi.name.toLowerCase() === itemName.toLowerCase() &&
                wi.currentQuantity > 0 &&
                wi.unitCost !== null
        );

        if (!matchingItem || !matchingItem.unitCost) {
            return null;
        }

        return {
            unitCost: Number(matchingItem.unitCost),
            totalCost: 0, // Will be calculated by caller
            warehouseId: matchingItem.id,
            warehouseType: 'item',
        };
    }

    /**
     * Calculate cost for a warehouse chemical (reagent/standard)
     * Uses unit_cost_base (Rp/mL or Rp/g)
     */
    async calculateChemicalCost(itemName: string): Promise<CostCalculationResult | null> {
        const chemicals = await db.query.warehouseChemicals.findMany({
            orderBy: [schema.warehouseChemicals.expiredDate], // FEFO - earliest expiry first
        });

        const matchingChemical = chemicals.find(
            c => c.name.toLowerCase() === itemName.toLowerCase() &&
                Number(c.remainingAmount) > 0 &&
                c.unitCostBase !== null
        );

        if (!matchingChemical || !matchingChemical.unitCostBase) {
            // Try to calculate from totalPrice and sizeValue if unitCostBase not set
            const chemWithPrice = chemicals.find(
                c => c.name.toLowerCase() === itemName.toLowerCase() &&
                    Number(c.remainingAmount) > 0 &&
                    c.totalPrice !== null &&
                    Number(c.sizeValue) > 0
            );

            if (chemWithPrice && chemWithPrice.totalPrice) {
                const calculatedUnitCost = Number(chemWithPrice.totalPrice) / Number(chemWithPrice.sizeValue);
                return {
                    unitCost: calculatedUnitCost,
                    totalCost: 0,
                    warehouseId: chemWithPrice.id,
                    warehouseType: 'chemical',
                };
            }
            return null;
        }

        return {
            unitCost: Number(matchingChemical.unitCostBase),
            totalCost: 0,
            warehouseId: matchingChemical.id,
            warehouseType: 'chemical',
        };
    }

    /**
     * Get training cost statistics (this month, last month, YTD)
     */
    async getTrainingCostStats(): Promise<TrainingCostStats> {
        const now = new Date();
        const thisMonthStart = new Date(now.getFullYear(), now.getMonth(), 1);
        const lastMonthStart = new Date(now.getFullYear(), now.getMonth() - 1, 1);
        const lastMonthEnd = new Date(now.getFullYear(), now.getMonth(), 0, 23, 59, 59);
        const ytdStart = new Date(now.getFullYear(), 0, 1);

        const allLogs = await db.query.trainingCostLogs.findMany();

        const thisMonthTotal = allLogs
            .filter(log => new Date(log.executedAt) >= thisMonthStart)
            .reduce((sum, log) => sum + Number(log.totalCost), 0);

        const lastMonthTotal = allLogs
            .filter(log => {
                const date = new Date(log.executedAt);
                return date >= lastMonthStart && date <= lastMonthEnd;
            })
            .reduce((sum, log) => sum + Number(log.totalCost), 0);

        const ytdTotal = allLogs
            .filter(log => new Date(log.executedAt) >= ytdStart)
            .reduce((sum, log) => sum + Number(log.totalCost), 0);

        const percentChange = lastMonthTotal > 0
            ? ((thisMonthTotal - lastMonthTotal) / lastMonthTotal) * 100
            : 0;

        return {
            thisMonth: thisMonthTotal,
            lastMonth: lastMonthTotal,
            ytd: ytdTotal,
            percentChange: Math.round(percentChange * 10) / 10,
        };
    }

    /**
     * Get monthly cost trends for chart
     */
    async getTrainingCostTrends(months: number = 6): Promise<CostTrendData[]> {
        const allLogs = await db.query.trainingCostLogs.findMany({
            orderBy: [desc(schema.trainingCostLogs.executedAt)],
        });

        // Group by month
        const monthlyData: Map<string, { totalCost: number; count: number }> = new Map();

        allLogs.forEach(log => {
            const date = new Date(log.executedAt);
            const key = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;

            const existing = monthlyData.get(key) || { totalCost: 0, count: 0 };
            existing.totalCost += Number(log.totalCost);
            existing.count += 1;
            monthlyData.set(key, existing);
        });

        // Generate last N months
        const result: CostTrendData[] = [];
        const now = new Date();

        for (let i = months - 1; i >= 0; i--) {
            const date = new Date(now.getFullYear(), now.getMonth() - i, 1);
            const key = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;
            const monthName = date.toLocaleString('id-ID', { month: 'short' });
            const data = monthlyData.get(key) || { totalCost: 0, count: 0 };

            result.push({
                month: monthName,
                year: date.getFullYear(),
                totalCost: data.totalCost,
                executionCount: data.count,
            });
        }

        return result;
    }

    /**
     * Get paginated training cost logs with items
     */
    async getTrainingCostLogs(filters?: CostReportFilters): Promise<{
        data: TrainingCostLogWithItems[];
        pagination: { page: number; limit: number; total: number; totalPages: number };
    }> {
        const page = filters?.page || 1;
        const limit = filters?.limit || 10;

        let logs = await db.query.trainingCostLogs.findMany({
            orderBy: [desc(schema.trainingCostLogs.executedAt)],
            with: {
                items: true,
            },
        });

        // Apply filters
        if (filters?.startDate) {
            logs = logs.filter(log => new Date(log.executedAt) >= new Date(filters.startDate!));
        }
        if (filters?.endDate) {
            logs = logs.filter(log => new Date(log.executedAt) <= new Date(filters.endDate!));
        }
        if (filters?.trainingSetId) {
            logs = logs.filter(log => log.trainingSetId === filters.trainingSetId);
        }

        const total = logs.length;
        const totalPages = Math.ceil(total / limit);
        const offset = (page - 1) * limit;
        const paginatedLogs = logs.slice(offset, offset + limit);

        return {
            data: paginatedLogs as TrainingCostLogWithItems[],
            pagination: { page, limit, total, totalPages },
        };
    }

    /**
     * Get single training cost log by ID
     */
    async getTrainingCostLogById(id: string): Promise<TrainingCostLogWithItems | null> {
        const log = await db.query.trainingCostLogs.findFirst({
            where: eq(schema.trainingCostLogs.id, id),
            with: {
                items: true,
            },
        });

        return log as TrainingCostLogWithItems | null;
    }

    /**
     * Format currency to Indonesian Rupiah
     */
    formatCurrency(amount: number): string {
        return new Intl.NumberFormat('id-ID', {
            style: 'currency',
            currency: 'IDR',
            minimumFractionDigits: 0,
            maximumFractionDigits: 0,
        }).format(amount);
    }

    /**
     * Format currency shorthand (e.g., 1.2 jt)
     */
    formatCurrencyShort(amount: number): string {
        if (amount >= 1000000000) {
            return `${(amount / 1000000000).toFixed(1)} M`;
        }
        if (amount >= 1000000) {
            return `${(amount / 1000000).toFixed(1)} jt`;
        }
        if (amount >= 1000) {
            return `${(amount / 1000).toFixed(0)} rb`;
        }
        return `Rp ${amount}`;
    }
}

